import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import postgres from "https://deno.land/x/postgresjs@v3.4.5/mod.js";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.4";

// DDL delivery vehicle for staff-app operations features. The remote
// migration history is out of sync, so schema changes are applied here
// idempotently via SUPABASE_DB_URL (see the moderate-review function for the
// same pattern). SQL mirrors supabase/migrations/20260717_driver_exceptions_run_completion.sql.

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

/**
 * A temporary password for a newly created staff account.
 *
 * Drawn from crypto.getRandomValues rather than Math.random, and guaranteed to
 * contain an upper, a lower, a digit and a symbol so it satisfies the project's
 * strong-password policy on the first try. Ambiguous glyphs (O/0, l/1/I) are
 * excluded because this gets read aloud down a phone line.
 */
function generateTempPassword(): string {
  const upper = "ABCDEFGHJKMNPQRSTUVWXYZ";
  const lower = "abcdefghijkmnpqrstuvwxyz";
  const digits = "23456789";
  const symbols = "!@#$%*?";
  const all = upper + lower + digits + symbols;

  const pick = (set: string) => {
    const buf = new Uint32Array(1);
    crypto.getRandomValues(buf);
    return set[buf[0] % set.length];
  };

  // One of each class, then fill to 14 characters.
  const chars = [pick(upper), pick(lower), pick(digits), pick(symbols)];
  while (chars.length < 14) chars.push(pick(all));

  // Fisher-Yates, so the guaranteed characters aren't always in front.
  for (let i = chars.length - 1; i > 0; i--) {
    const buf = new Uint32Array(1);
    crypto.getRandomValues(buf);
    const j = buf[0] % (i + 1);
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return chars.join("");
}

/**
 * Every action here is privileged: "setup" runs DDL, "verify" reads operational
 * aggregates, "invite_staff" creates accounts. Only "invite_staff" used to check
 * the caller, so anyone holding the publishable key — which ships in the browser
 * bundle and is therefore public — could POST {"action":"setup"} and re-run the
 * whole schema script against the live database.
 *
 * Returns the admin's user id, or a Response to send back immediately.
 */
async function requireAdmin(req: Request): Promise<{ userId: string } | { response: Response }> {
  const json = (body: unknown, status: number) =>
    new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

  const authHeader = req.headers.get("Authorization") || "";
  // An apikey-only request carries no user, so bail before hitting the network.
  if (!authHeader.toLowerCase().startsWith("bearer ")) {
    return { response: json({ error: "Admin authentication required" }, 401) };
  }

  const caller = createClient(supabaseUrl, anonKey, { global: { headers: { Authorization: authHeader } } });
  const { data: { user } } = await caller.auth.getUser();
  if (!user) return { response: json({ error: "Admin authentication required" }, 401) };

  const admin = createClient(supabaseUrl, serviceKey);
  const { data: profile } = await admin.from("profiles").select("is_admin,role").eq("id", user.id).maybeSingle();
  const isAdmin = Boolean(profile?.is_admin) || String(profile?.role || "").toLowerCase() === "admin";
  if (!isAdmin) return { response: json({ error: "Admin access required" }, 403) };

  return { userId: user.id };
}

// SQL mirrored from supabase/migrations/20260719_operations_upgrade.sql
// (regenerate with tools/embed-staff-ops-sql.js after editing the migration).
const SETUP_SQL_V2 = "-- Operations upgrade: detailed goods descriptions with driver corrections,\r\n-- metal coded seals, saved delivery addresses with per-address pricing,\r\n-- server-side customer references (AAAMMYY0000) and booking pricing,\r\n-- quote-to-booking workflow, richer customer notifications, driver-proof\r\n-- retention bookkeeping, AI rate limiting, and route-based driver assignment.\r\n-- Applied to the live DB via the staff-ops edge function's \"setup\" action.\r\n\r\ncreate extension if not exists pgcrypto;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Goods descriptions + non-destructive driver corrections\r\n-- ---------------------------------------------------------------------------\r\n\r\nalter table public.shipments\r\n  add column if not exists goods_description text,\r\n  add column if not exists driver_description_correction text,\r\n  add column if not exists seals_requested integer not null default 0;\r\n\r\nalter table public.custom_quotes\r\n  add column if not exists currency text not null default 'GBP',\r\n  add column if not exists valid_until date,\r\n  add column if not exists quoted_by uuid references auth.users(id) on delete set null,\r\n  add column if not exists quoted_at timestamptz,\r\n  add column if not exists booked_shipment_id uuid references public.shipments(id) on delete set null;\r\n\r\ncreate or replace function public.driver_correct_goods_description(\r\n  p_stop_id uuid,\r\n  p_correction text\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_stop public.driver_run_stops%rowtype; v_run public.driver_runs%rowtype; v_ship public.shipments%rowtype;\r\nbegin\r\n  select * into v_stop from public.driver_run_stops where id = p_stop_id;\r\n  if not found then raise exception 'Stop not found'; end if;\r\n  select * into v_run from public.driver_runs where id = v_stop.run_id;\r\n  if v_run.driver_id <> auth.uid() and not public.is_operations_admin() then\r\n    raise exception 'This stop is not assigned to you';\r\n  end if;\r\n  if trim(coalesce(p_correction, '')) = '' then raise exception 'Enter the correction first'; end if;\r\n\r\n  select * into v_ship from public.shipments where id = v_stop.shipment_id for update;\r\n  -- The customer's original description is never overwritten; corrections are\r\n  -- stored separately and every change is audited.\r\n  update public.shipments set\r\n    driver_description_correction = trim(p_correction),\r\n    updated_at = now(),\r\n    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(\r\n      'driverDescriptionCorrection', jsonb_build_object(\r\n        'text', trim(p_correction), 'driverId', auth.uid(), 'correctedAt', now(),\r\n        'original', coalesce(v_ship.goods_description, v_ship.metadata->'shipment'->>'description')\r\n      )\r\n    )\r\n  where id = v_ship.id;\r\n\r\n  insert into public.shipment_events(shipment_id, event_type, previous_status, new_status, actor_id, details)\r\n  values (v_ship.id, 'description_corrected', null, null, auth.uid(),\r\n          jsonb_build_object('stopId', v_stop.id, 'correction', trim(p_correction),\r\n                             'original', coalesce(v_ship.goods_description, v_ship.metadata->'shipment'->>'description')));\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'CORRECT_DESCRIPTION', 'SHIPMENT', v_ship.id,\r\n          jsonb_build_object('stopId', v_stop.id, 'correction', trim(p_correction)));\r\n\r\n  return jsonb_build_object('shipmentId', v_ship.id, 'correction', trim(p_correction));\r\nend $$;\r\ngrant execute on function public.driver_correct_goods_description(uuid, text) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. Metal coded seals\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.shipment_seals (\r\n  id uuid primary key default gen_random_uuid(),\r\n  shipment_id uuid not null references public.shipments(id) on delete cascade,\r\n  stop_id uuid references public.driver_run_stops(id) on delete set null,\r\n  seals_used boolean not null default true,\r\n  seal_count integer not null default 0 check (seal_count >= 0),\r\n  seal_codes text[] not null default '{}',\r\n  condition text not null default 'intact' check (condition in ('intact', 'damaged', 'missing', 'other')),\r\n  notes text,\r\n  photo_path text,\r\n  recorded_by uuid references auth.users(id) on delete set null,\r\n  recorded_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now(),\r\n  unique (shipment_id)\r\n);\r\ncreate index if not exists shipment_seals_shipment_idx on public.shipment_seals(shipment_id);\r\n\r\nalter table public.shipment_seals enable row level security;\r\n\r\ndrop policy if exists \"Staff manage shipment seals\" on public.shipment_seals;\r\ncreate policy \"Staff manage shipment seals\" on public.shipment_seals\r\n  for all to authenticated\r\n  using (public.is_operations_admin() or public.is_finance_staff() or recorded_by = auth.uid())\r\n  with check (public.is_operations_admin() or public.is_finance_staff() or recorded_by = auth.uid());\r\n\r\ndrop policy if exists \"Customers view own shipment seals\" on public.shipment_seals;\r\ncreate policy \"Customers view own shipment seals\" on public.shipment_seals\r\n  for select to authenticated\r\n  using (exists (select 1 from public.shipments s where s.id = shipment_seals.shipment_id and s.user_id = auth.uid()));\r\n\r\n-- Driver records seal details during pickup (server stamps who/when and\r\n-- mirrors the seals onto the shipment metadata for invoices/delivery notes).\r\ncreate or replace function public.record_shipment_seals(\r\n  p_stop_id uuid,\r\n  p_seals_used boolean,\r\n  p_seal_count integer default 0,\r\n  p_seal_codes text[] default '{}',\r\n  p_condition text default 'intact',\r\n  p_notes text default null,\r\n  p_photo_path text default null\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_stop public.driver_run_stops%rowtype; v_run public.driver_runs%rowtype; v_row public.shipment_seals%rowtype;\r\nbegin\r\n  select * into v_stop from public.driver_run_stops where id = p_stop_id;\r\n  if not found then raise exception 'Stop not found'; end if;\r\n  select * into v_run from public.driver_runs where id = v_stop.run_id;\r\n  if v_run.driver_id <> auth.uid() and not public.is_operations_admin() then\r\n    raise exception 'This stop is not assigned to you';\r\n  end if;\r\n  if p_seals_used and coalesce(p_seal_count, 0) <> coalesce(array_length(p_seal_codes, 1), 0) then\r\n    raise exception 'Enter every seal code (% seals, % codes)', p_seal_count, coalesce(array_length(p_seal_codes, 1), 0);\r\n  end if;\r\n\r\n  insert into public.shipment_seals(shipment_id, stop_id, seals_used, seal_count, seal_codes, condition, notes, photo_path, recorded_by)\r\n  values (v_stop.shipment_id, v_stop.id, p_seals_used,\r\n          case when p_seals_used then coalesce(p_seal_count, 0) else 0 end,\r\n          case when p_seals_used then coalesce(p_seal_codes, '{}') else '{}' end,\r\n          coalesce(p_condition, 'intact'), p_notes, p_photo_path, auth.uid())\r\n  on conflict (shipment_id) do update set\r\n    stop_id = excluded.stop_id, seals_used = excluded.seals_used, seal_count = excluded.seal_count,\r\n    seal_codes = excluded.seal_codes, condition = excluded.condition, notes = excluded.notes,\r\n    photo_path = coalesce(excluded.photo_path, shipment_seals.photo_path),\r\n    recorded_by = auth.uid(), updated_at = now()\r\n  returning * into v_row;\r\n\r\n  update public.shipments set\r\n    updated_at = now(),\r\n    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(\r\n      'seals', jsonb_build_object(\r\n        'used', v_row.seals_used, 'count', v_row.seal_count, 'codes', to_jsonb(v_row.seal_codes),\r\n        'condition', v_row.condition, 'notes', v_row.notes,\r\n        'recordedBy', v_row.recorded_by, 'recordedAt', v_row.updated_at))\r\n  where id = v_stop.shipment_id;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'RECORD_SEALS', 'SHIPMENT', v_stop.shipment_id,\r\n          jsonb_build_object('stopId', v_stop.id, 'used', v_row.seals_used, 'count', v_row.seal_count, 'codes', v_row.seal_codes));\r\n\r\n  return to_jsonb(v_row);\r\nend $$;\r\ngrant execute on function public.record_shipment_seals(uuid, boolean, integer, text[], text, text, text) to authenticated;\r\n\r\n-- Seal and goods photos share the driver-proofs pipeline (and retention).\r\nalter table public.driver_proofs drop constraint if exists driver_proofs_proof_type_check;\r\nalter table public.driver_proofs add constraint driver_proofs_proof_type_check\r\n  check (proof_type in ('pickup_departure', 'depot_arrival', 'depot_departure', 'delivery_arrival', 'exception', 'seal', 'goods'));\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. Saved customer delivery addresses (£25 UK / €25 Ireland per address)\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.customer_addresses (\r\n  id uuid primary key default gen_random_uuid(),\r\n  user_id uuid not null references auth.users(id) on delete cascade,\r\n  recipient_name text not null,\r\n  recipient_phone text not null,\r\n  address_line1 text not null,\r\n  address_line2 text,\r\n  city text not null,\r\n  province text,\r\n  country text not null default 'Zimbabwe',\r\n  postal_code text,\r\n  delivery_instructions text,\r\n  is_default boolean not null default false,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\ncreate index if not exists customer_addresses_user_idx on public.customer_addresses(user_id, created_at desc);\r\n\r\nalter table public.customer_addresses enable row level security;\r\ndrop policy if exists \"Customers manage own addresses\" on public.customer_addresses;\r\ncreate policy \"Customers manage own addresses\" on public.customer_addresses\r\n  for all to authenticated\r\n  using (user_id = auth.uid() or public.is_operations_admin() or public.is_finance_staff())\r\n  with check (user_id = auth.uid() or public.is_operations_admin());\r\n\r\ncreate or replace function public.enforce_single_default_address() returns trigger\r\nlanguage plpgsql set search_path = public as $$\r\nbegin\r\n  if new.is_default then\r\n    update public.customer_addresses set is_default = false\r\n    where user_id = new.user_id and id <> new.id and is_default;\r\n  end if;\r\n  new.updated_at := now();\r\n  return new;\r\nend $$;\r\ndrop trigger if exists customer_addresses_default_trigger on public.customer_addresses;\r\ncreate trigger customer_addresses_default_trigger\r\n  before insert or update on public.customer_addresses\r\n  for each row execute function public.enforce_single_default_address();\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Server-side customer references — AAAMMYY0000\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.customer_reference_counters (\r\n  period text primary key,\r\n  counter integer not null default 0\r\n);\r\n\r\ncreate or replace function public.next_customer_reference(p_name text) returns text\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_prefix text; v_period text; v_n integer; v_ref text;\r\nbegin\r\n  v_prefix := upper(rpad(left(regexp_replace(coalesce(p_name, ''), '[^A-Za-z]', '', 'g'), 3), 3, 'X'));\r\n  v_period := to_char(now(), 'MMYY');\r\n  loop\r\n    insert into public.customer_reference_counters(period, counter) values (v_period, 1)\r\n      on conflict (period) do update set counter = customer_reference_counters.counter + 1\r\n      returning counter into v_n;\r\n    v_ref := v_prefix || v_period || case when v_n < 10000 then lpad(v_n::text, 4, '0') else v_n::text end;\r\n    exit when not exists (select 1 from public.shipments where customer_reference = v_ref);\r\n  end loop;\r\n  return v_ref;\r\nend $$;\r\ngrant execute on function public.next_customer_reference(text) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- E. Canonical catalogue + fully server-priced booking\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.catalogue_items (\r\n  id text primary key,\r\n  label text not null,\r\n  price_uk numeric(12,2),\r\n  price_ie numeric(12,2),\r\n  note text,\r\n  active boolean not null default true\r\n);\r\ninsert into public.catalogue_items (id, label, price_uk, price_ie, note) values\r\n  ('drum', 'Drum (200-220L)', 280, 360, null),\r\n  ('trunk', 'Trunk / storage box', null, 220, 'UK boxes £180-£280 by size - team confirms'),\r\n  ('seal', 'Metal coded seal', 5, 7, null),\r\n  ('stove', 'Stove / cooker', 260, 325, null),\r\n  ('washing_machine', 'Washing machine', 300, 328, null),\r\n  ('fridge', 'Fridge', 450, null, 'Ireland €490-€620 by size - team confirms'),\r\n  ('american_fridge', 'American fridge freezer', 600, null, null),\r\n  ('sofa', 'Sofa / lounge suite', 1500, 1560, null),\r\n  ('suitcase', 'Suitcase', null, null, 'UK £180-£200, Ireland €200-€230 by size')\r\non conflict (id) do update set label = excluded.label, price_uk = excluded.price_uk,\r\n  price_ie = excluded.price_ie, note = excluded.note, active = true;\r\n\r\nalter table public.catalogue_items enable row level security;\r\ndrop policy if exists \"Catalogue is readable\" on public.catalogue_items;\r\ncreate policy \"Catalogue is readable\" on public.catalogue_items for select to authenticated, anon using (true);\r\n\r\n-- All booking pricing is computed here from the catalogue, the caller's saved\r\n-- delivery addresses, seals, and (optionally) an approved custom quote. The\r\n-- mobile app's totals are display-only.\r\ncreate or replace function public.create_customer_booking(p jsonb) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_country text := coalesce(p->>'country', 'United Kingdom');\r\n  v_is_ireland boolean;\r\n  v_currency text; v_symbol text;\r\n  v_full_name text;\r\n  v_reference text; v_tracking text; v_qr text;\r\n  v_items jsonb := coalesce(p->'items', '{}'::jsonb);\r\n  v_lines jsonb := '[]'::jsonb;\r\n  v_line record;\r\n  v_subtotal numeric := 0;\r\n  v_has_custom boolean := false;\r\n  v_seals integer := greatest(0, coalesce((p->>'sealsRequested')::integer, 0));\r\n  v_seal_price numeric;\r\n  v_addr_ids uuid[];\r\n  v_addresses jsonb := '[]'::jsonb;\r\n  v_addr record;\r\n  v_addr_count integer := 0;\r\n  v_quote public.custom_quotes%rowtype;\r\n  v_quote_id uuid := nullif(p->>'quoteId', '')::uuid;\r\n  v_description text;\r\n  v_recipient jsonb;\r\n  v_invoice jsonb;\r\n  v_shipment public.shipments%rowtype;\r\n  v_discount numeric := 0;\r\nbegin\r\n  if v_uid is null then raise exception 'Sign in to book a shipment'; end if;\r\n  if v_country not in ('United Kingdom', 'Ireland') then raise exception 'Unknown collection country'; end if;\r\n  v_is_ireland := v_country = 'Ireland';\r\n  v_currency := case when v_is_ireland then 'EUR' else 'GBP' end;\r\n  v_symbol := case when v_is_ireland then '€' else '£' end;\r\n  v_full_name := trim(coalesce(p->'sender'->>'firstName', '') || ' ' || coalesce(p->'sender'->>'lastName', ''));\r\n  if v_full_name = '' then raise exception 'Sender name is required'; end if;\r\n  v_description := nullif(trim(coalesce(p->>'goodsDescription', '')), '');\r\n  if v_description is null then raise exception 'A detailed goods description is required'; end if;\r\n\r\n  -- Catalogue items priced server-side.\r\n  for v_line in\r\n    select c.id, c.label, case when v_is_ireland then c.price_ie else c.price_uk end as unit,\r\n           least(greatest((v_items->>c.id)::integer, 0), 500) as qty\r\n    from public.catalogue_items c\r\n    where c.active and v_items ? c.id and coalesce((v_items->>c.id)::integer, 0) > 0 and c.id <> 'seal'\r\n  loop\r\n    v_lines := v_lines || jsonb_build_array(jsonb_build_object(\r\n      'description', v_line.label, 'quantity', v_line.qty, 'unitPrice', coalesce(v_line.unit, 0)));\r\n    if v_line.unit is null then v_has_custom := true;\r\n    else v_subtotal := v_subtotal + v_line.qty * v_line.unit; end if;\r\n  end loop;\r\n\r\n  if nullif(trim(coalesce(p->>'otherItems', '')), '') is not null then\r\n    v_lines := v_lines || jsonb_build_array(jsonb_build_object(\r\n      'description', trim(p->>'otherItems'), 'quantity', 1, 'unitPrice', 0));\r\n    v_has_custom := true;\r\n  end if;\r\n\r\n  -- Optional approved custom quote carried into the booking (amount locked).\r\n  if v_quote_id is not null then\r\n    select * into v_quote from public.custom_quotes\r\n      where id = v_quote_id and user_id = v_uid and status = 'approved' for update;\r\n    if not found then raise exception 'This quote is not approved for booking'; end if;\r\n    if v_quote.valid_until is not null and v_quote.valid_until < current_date then\r\n      raise exception 'This quote has expired — please request an updated quote';\r\n    end if;\r\n    if coalesce(v_quote.currency, v_currency) <> v_currency then\r\n      raise exception 'This quote was priced in % — choose the matching collection country', v_quote.currency;\r\n    end if;\r\n    v_lines := v_lines || jsonb_build_array(jsonb_build_object(\r\n      'description', 'Approved quote: ' || left(coalesce(v_quote.description, 'custom goods'), 160),\r\n      'quantity', 1, 'unitPrice', coalesce(v_quote.quoted_amount, 0)));\r\n    v_subtotal := v_subtotal + coalesce(v_quote.quoted_amount, 0);\r\n  end if;\r\n\r\n  -- Metal coded seals at the catalogue price.\r\n  if v_seals > 0 then\r\n    select case when v_is_ireland then price_ie else price_uk end into v_seal_price\r\n      from public.catalogue_items where id = 'seal';\r\n    v_lines := v_lines || jsonb_build_array(jsonb_build_object(\r\n      'description', 'Metal coded seal', 'quantity', v_seals, 'unitPrice', coalesce(v_seal_price, 0)));\r\n    v_subtotal := v_subtotal + v_seals * coalesce(v_seal_price, 0);\r\n  end if;\r\n\r\n  -- Delivery addresses: each saved address selected adds £25/€25 in the\r\n  -- booking currency. Addresses must belong to the caller.\r\n  select coalesce(array_agg(value::uuid), '{}') into v_addr_ids\r\n    from jsonb_array_elements_text(coalesce(p->'deliveryAddressIds', '[]'::jsonb));\r\n  for v_addr in\r\n    select * from public.customer_addresses\r\n    where user_id = v_uid and id = any(v_addr_ids)\r\n    order by array_position(v_addr_ids, id)\r\n  loop\r\n    v_addr_count := v_addr_count + 1;\r\n    v_addresses := v_addresses || jsonb_build_array(jsonb_build_object(\r\n      'id', v_addr.id, 'recipientName', v_addr.recipient_name, 'recipientPhone', v_addr.recipient_phone,\r\n      'address', trim(v_addr.address_line1 || coalesce(', ' || nullif(v_addr.address_line2, ''), '')),\r\n      'city', v_addr.city, 'province', v_addr.province, 'country', v_addr.country,\r\n      'postalCode', v_addr.postal_code, 'instructions', v_addr.delivery_instructions));\r\n  end loop;\r\n  if v_addr_count <> coalesce(array_length(v_addr_ids, 1), 0) then\r\n    raise exception 'One of the selected delivery addresses could not be found';\r\n  end if;\r\n  if v_addr_count > 0 then\r\n    v_lines := v_lines || jsonb_build_array(jsonb_build_object(\r\n      'description', 'Zimbabwe door delivery (' || v_addr_count || ' address' || case when v_addr_count > 1 then 'es' else '' end || ')',\r\n      'quantity', v_addr_count, 'unitPrice', 25));\r\n    v_subtotal := v_subtotal + v_addr_count * 25;\r\n  end if;\r\n\r\n  if jsonb_array_length(v_lines) = 0 then raise exception 'Add at least one item to the booking'; end if;\r\n\r\n  -- Primary receiver: first selected delivery address, else the typed one.\r\n  if v_addr_count > 0 then\r\n    v_recipient := v_addresses->0;\r\n    v_recipient := jsonb_build_object(\r\n      'name', v_recipient->>'recipientName', 'phone', v_recipient->>'recipientPhone',\r\n      'address', v_recipient->>'address', 'city', v_recipient->>'city');\r\n  else\r\n    v_recipient := jsonb_build_object(\r\n      'name', coalesce(p->'recipient'->>'name', ''), 'phone', coalesce(p->'recipient'->>'phone', ''),\r\n      'address', coalesce(p->'recipient'->>'address', ''), 'city', coalesce(p->'recipient'->>'city', ''));\r\n    if trim(coalesce(v_recipient->>'name', '')) = '' then\r\n      raise exception 'Add a receiver or select a saved delivery address';\r\n    end if;\r\n  end if;\r\n\r\n  v_reference := public.next_customer_reference(v_full_name);\r\n  loop\r\n    v_tracking := 'ZIMSHIP-' || lpad(floor(random() * 90000 + 10000)::text, 5, '0');\r\n    exit when not exists (select 1 from public.shipments where tracking_number = v_tracking);\r\n  end loop;\r\n  v_qr := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');\r\n\r\n  v_invoice := jsonb_build_object(\r\n    'invoiceNumber', 'INV-' || v_reference,\r\n    'issueDate', to_char(now(), 'YYYY-MM-DD'),\r\n    'dueDate', to_char(now() + interval '14 days', 'YYYY-MM-DD'),\r\n    'items', v_lines,\r\n    'discount', v_discount,\r\n    'taxRate', 0,\r\n    'paymentTerms', coalesce(p->>'paymentMethod', 'Bank Transfer'),\r\n    'notes', case when v_has_custom\r\n      then 'Includes custom-quote items - final price to be confirmed by the Zimbabwe Shipping team.'\r\n      else 'Booked via the customer app.' end,\r\n    'currency', v_currency,\r\n    'paid', false, 'payments', '[]'::jsonb, 'sentAt', null);\r\n\r\n  insert into public.shipments (\r\n    tracking_number, status, origin, destination, user_id, customer_reference, qr_token,\r\n    collection_status, delivery_note_status, collection_schedule_id,\r\n    goods_description, seals_requested, metadata\r\n  ) values (\r\n    v_tracking, 'Booking Confirmed',\r\n    v_country || ': ' || coalesce(p->>'collectionAddress', '') || ', ' || coalesce(p->>'collectionCity', '') || ' ' || coalesce(p->>'collectionPostcode', ''),\r\n    coalesce(v_recipient->>'address', '') || ', ' || coalesce(v_recipient->>'city', ''),\r\n    v_uid, v_reference, v_qr,\r\n    'Awaiting Collection', 'Draft', nullif(p->>'scheduleId', '')::uuid,\r\n    v_description, v_seals,\r\n    jsonb_build_object(\r\n      'source', 'customer_app',\r\n      'customerReference', v_reference,\r\n      'qrToken', v_qr,\r\n      'sender', jsonb_build_object(\r\n        'firstName', p->'sender'->>'firstName', 'lastName', p->'sender'->>'lastName',\r\n        'name', v_full_name, 'email', p->'sender'->>'email', 'phone', p->'sender'->>'phone',\r\n        'address', p->>'collectionAddress', 'city', p->>'collectionCity',\r\n        'postalCode', p->>'collectionPostcode', 'country', v_country),\r\n      'recipient', v_recipient,\r\n      'deliveryAddresses', v_addresses,\r\n      'shipment', jsonb_build_object('description', v_description, 'includeOtherItems', v_has_custom),\r\n      'shipmentDetails', jsonb_build_object('description', v_description, 'includeOtherItems', v_has_custom),\r\n      'collection', jsonb_build_object(\r\n        'route', coalesce(nullif(p->>'route', ''), 'To be assigned'),\r\n        'date', coalesce(nullif(p->>'collectionDate', ''), 'To be confirmed'),\r\n        'scheduleId', nullif(p->>'scheduleId', '')),\r\n      'pricing', jsonb_build_object(\r\n        'paymentMethod', coalesce(p->>'paymentMethod', 'Bank Transfer'), 'currency', v_currency,\r\n        'estimatedTotal', v_subtotal, 'deliveryAddressCount', v_addr_count,\r\n        'deliveryFeePerAddress', 25, 'sealsRequested', v_seals, 'serverPriced', true),\r\n      'discounts', jsonb_build_object(\r\n        'returningResident', coalesce((p->>'returningResident')::boolean, false),\r\n        'referredBy', nullif(trim(coalesce(p->>'referredBy', '')), '')),\r\n      'sealsRequested', v_seals,\r\n      'quoteId', v_quote_id,\r\n      'invoice', v_invoice,\r\n      'deliveryNote', jsonb_build_object('status', 'Draft', 'number', 'DN-' || v_reference),\r\n      'whatsappNumber', p->'sender'->>'phone',\r\n      'createdAt', now()\r\n    )\r\n  ) returning * into v_shipment;\r\n\r\n  if v_quote_id is not null then\r\n    update public.custom_quotes set status = 'booked', booked_shipment_id = v_shipment.id, updated_at = now()\r\n    where id = v_quote_id;\r\n  end if;\r\n\r\n  insert into public.customer_requests (shipment_id, customer_name, whatsapp_number, request_type, message,\r\n                                        customer_reference, status, unread, source)\r\n  values (v_shipment.id, v_full_name, p->'sender'->>'phone', 'App Booking',\r\n          left(v_description, 500)\r\n            || case when coalesce((p->>'returningResident')::boolean, false) then ' - RETURNING RESIDENT' else '' end\r\n            || case when nullif(trim(coalesce(p->>'referredBy', '')), '') is not null then ' - referred by ' || trim(p->>'referredBy') else '' end,\r\n          v_reference, 'New', true, 'customer_app');\r\n\r\n  return jsonb_build_object(\r\n    'id', v_shipment.id, 'trackingNumber', v_tracking, 'customerReference', v_reference,\r\n    'currency', v_currency, 'estimatedTotal', v_subtotal, 'hasCustomItems', v_has_custom,\r\n    'invoice', v_invoice);\r\nend $$;\r\ngrant execute on function public.create_customer_booking(jsonb) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- F. Quote-to-booking workflow\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.respond_custom_quote(\r\n  p_quote_id uuid,\r\n  p_action text,\r\n  p_amount numeric default null,\r\n  p_currency text default null,\r\n  p_valid_until date default null,\r\n  p_notes text default null\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_quote public.custom_quotes%rowtype;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\r\n  select * into v_quote from public.custom_quotes where id = p_quote_id for update;\r\n  if not found then raise exception 'Quote not found'; end if;\r\n  if v_quote.status = 'booked' then raise exception 'This quote has already been booked'; end if;\r\n\r\n  if p_action = 'approve' then\r\n    if coalesce(p_amount, 0) <= 0 then raise exception 'Enter the quoted price first'; end if;\r\n    update public.custom_quotes set\r\n      status = 'approved', quoted_amount = p_amount,\r\n      currency = coalesce(upper(p_currency), currency, 'GBP'),\r\n      valid_until = coalesce(p_valid_until, current_date + 30),\r\n      admin_notes = coalesce(p_notes, admin_notes),\r\n      quoted_by = auth.uid(), quoted_at = now(), updated_at = now()\r\n    where id = p_quote_id returning * into v_quote;\r\n  elsif p_action = 'reject' then\r\n    update public.custom_quotes set status = 'rejected', admin_notes = coalesce(p_notes, admin_notes),\r\n      quoted_by = auth.uid(), quoted_at = now(), updated_at = now()\r\n    where id = p_quote_id returning * into v_quote;\r\n  elsif p_action = 'request_info' then\r\n    update public.custom_quotes set status = 'info_requested', admin_notes = coalesce(p_notes, admin_notes),\r\n      quoted_by = auth.uid(), quoted_at = now(), updated_at = now()\r\n    where id = p_quote_id returning * into v_quote;\r\n  else\r\n    raise exception 'Action must be approve, reject or request_info';\r\n  end if;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'QUOTE_' || upper(p_action), 'CUSTOM_QUOTE', p_quote_id,\r\n          jsonb_build_object('amount', p_amount, 'currency', v_quote.currency, 'notes', p_notes));\r\n\r\n  if v_quote.user_id is not null then\r\n    insert into public.notifications(user_id, title, message, type, related_id)\r\n    values (v_quote.user_id,\r\n      case p_action when 'approve' then 'Your quote is ready'\r\n                    when 'reject' then 'Quote update'\r\n                    else 'We need more information' end,\r\n      case p_action\r\n        when 'approve' then 'Your custom quote is ' || v_quote.currency || ' ' || to_char(v_quote.quoted_amount, 'FM999999990.00')\r\n          || coalesce(' (valid until ' || to_char(v_quote.valid_until, 'DD Mon YYYY') || ')', '') || '. Open the app to book your shipment.'\r\n        when 'reject' then coalesce('We could not quote this request: ' || p_notes, 'We could not quote this request. Ask Zimmy or contact the team for help.')\r\n        else coalesce(p_notes, 'Please add more details to your quote request so the team can price it.') end,\r\n      'quote', v_quote.id);\r\n  end if;\r\n\r\n  return to_jsonb(v_quote);\r\nend $$;\r\ngrant execute on function public.respond_custom_quote(uuid, text, numeric, text, date, text) to authenticated;\r\n\r\n-- New quote requests alert the admin team and confirm receipt to the customer.\r\ncreate or replace function public.notify_new_custom_quote() returns trigger\r\nlanguage plpgsql security definer set search_path = public as $$\r\nbegin\r\n  insert into public.notifications(user_id, title, message, type, related_id, is_read)\r\n  select p.id, 'New quote request',\r\n         coalesce(left(new.description, 120), 'A customer') || ' — respond in Custom Quotes.',\r\n         'quote_request', new.id, false\r\n  from public.profiles p\r\n  where p.is_admin = true or lower(coalesce(p.role, '')) = 'admin';\r\n  if new.user_id is not null then\r\n    insert into public.notifications(user_id, title, message, type, related_id)\r\n    values (new.user_id, 'Quote request received',\r\n            'Our team is pricing your request and will reply shortly.', 'quote', new.id);\r\n  end if;\r\n  return new;\r\nend $$;\r\ndrop trigger if exists custom_quote_admin_notification on public.custom_quotes;\r\ncreate trigger custom_quote_admin_notification after insert on public.custom_quotes\r\n  for each row execute function public.notify_new_custom_quote();\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- G. Customer notifications for driver progress (dedup by transition)\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.notify_customer_driver_progress() returns trigger\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_title text; v_message text; v_ref text;\r\nbegin\r\n  if new.user_id is null or new.driver_status is not distinct from old.driver_status then return new; end if;\r\n  if coalesce((select (notification_preferences->>'shipment')::boolean from public.profiles where id = new.user_id), true) = false then\r\n    return new;\r\n  end if;\r\n  v_ref := coalesce(new.customer_reference, new.tracking_number);\r\n  v_title := case new.driver_status\r\n    when 'assigned' then 'Driver assigned'\r\n    when 'en_route' then 'Driver en route'\r\n    when 'arrived' then 'Driver has arrived'\r\n    when 'collected' then 'Goods collected'\r\n    when 'delivered' then 'Delivered'\r\n    when 'failed' then 'Collection or delivery issue'\r\n    else null end;\r\n  if v_title is null then return new; end if;\r\n  v_message := case new.driver_status\r\n    when 'assigned' then v_ref || ': a driver has been assigned to your collection.'\r\n    when 'en_route' then v_ref || ': your driver is on the way.'\r\n    when 'arrived' then v_ref || ': your driver has arrived.'\r\n    when 'collected' then v_ref || ': your goods have been collected. Thank you!'\r\n    when 'delivered' then v_ref || ' has been delivered.'\r\n    else v_ref || ': there was an issue — the team will contact you to replan.' end;\r\n  insert into public.notifications(user_id, title, message, type, related_id)\r\n  select new.user_id, v_title, v_message, 'shipment', new.id\r\n  where not exists (\r\n    select 1 from public.notifications\r\n    where user_id = new.user_id and related_id = new.id and title = v_title\r\n      and created_at > now() - interval '6 hours');\r\n  return new;\r\nend $$;\r\ndrop trigger if exists customer_driver_progress_notification on public.shipments;\r\ncreate trigger customer_driver_progress_notification after update of driver_status on public.shipments\r\n  for each row execute function public.notify_customer_driver_progress();\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- H. Driver photograph retention bookkeeping (deleted 48h after delivery)\r\n-- ---------------------------------------------------------------------------\r\n\r\nalter table public.driver_proofs\r\n  add column if not exists deleted_at timestamptz,\r\n  add column if not exists deletion_reason text;\r\ncreate index if not exists driver_proofs_retention_idx on public.driver_proofs(shipment_id) where deleted_at is null;\r\n\r\ncreate schema if not exists private;\r\ncreate table if not exists private.app_config (key text primary key, value text not null);\r\ninsert into private.app_config(key, value)\r\nvalues ('retention_secret', encode(gen_random_bytes(24), 'hex'))\r\non conflict (key) do nothing;\r\n\r\n-- Hourly retention sweep: pg_cron + pg_net call the photo-retention edge\r\n-- function, which removes the storage objects and stamps the audit fields.\r\ndo $$ begin create extension if not exists pg_cron; exception when others then null; end $$;\r\ndo $$ begin create extension if not exists pg_net; exception when others then null; end $$;\r\ndo $$\r\nbegin\r\n  if exists (select 1 from pg_extension where extname = 'pg_cron')\r\n     and exists (select 1 from pg_extension where extname = 'pg_net') then\r\n    perform cron.unschedule(jobid) from cron.job where jobname = 'driver-proofs-retention';\r\n    perform cron.schedule(\r\n      'driver-proofs-retention',\r\n      '17 * * * *',\r\n      format(\r\n        $job$select net.http_post(\r\n          url := 'https://oncsaunsqtekwwbzvvyh.supabase.co/functions/v1/photo-retention',\r\n          headers := jsonb_build_object('Content-Type', 'application/json', 'x-retention-secret', %L),\r\n          body := '{}'::jsonb)$job$,\r\n        (select value from private.app_config where key = 'retention_secret')));\r\n  end if;\r\nexception when others then null;\r\nend $$;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- I. AI rate limiting (consumed by the ai-chat / admin-zimmy edge functions)\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.ai_usage_events (\r\n  id bigint generated always as identity primary key,\r\n  identity text not null,\r\n  scope text not null default 'ai-chat',\r\n  created_at timestamptz not null default now()\r\n);\r\ncreate index if not exists ai_usage_events_lookup_idx on public.ai_usage_events(scope, identity, created_at desc);\r\nalter table public.ai_usage_events enable row level security;\r\n\r\ncreate or replace function public.consume_ai_quota(\r\n  p_identity text,\r\n  p_scope text default 'ai-chat',\r\n  p_short_limit integer default 8,\r\n  p_short_seconds integer default 60,\r\n  p_daily_limit integer default 100\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_short integer; v_daily integer; v_oldest timestamptz; v_retry integer;\r\nbegin\r\n  if coalesce(trim(p_identity), '') = '' then\r\n    return jsonb_build_object('allowed', false, 'reason', 'missing_identity', 'retryAfterSeconds', 60);\r\n  end if;\r\n  select count(*) into v_daily from public.ai_usage_events\r\n    where scope = p_scope and identity = p_identity and created_at > now() - interval '24 hours';\r\n  if v_daily >= p_daily_limit then\r\n    select min(created_at) into v_oldest from public.ai_usage_events\r\n      where scope = p_scope and identity = p_identity and created_at > now() - interval '24 hours';\r\n    v_retry := greatest(60, extract(epoch from (v_oldest + interval '24 hours' - now()))::integer);\r\n    return jsonb_build_object('allowed', false, 'reason', 'daily_limit', 'retryAfterSeconds', v_retry);\r\n  end if;\r\n  select count(*) into v_short from public.ai_usage_events\r\n    where scope = p_scope and identity = p_identity and created_at > now() - make_interval(secs => p_short_seconds);\r\n  if v_short >= p_short_limit then\r\n    select min(created_at) into v_oldest from public.ai_usage_events\r\n      where scope = p_scope and identity = p_identity and created_at > now() - make_interval(secs => p_short_seconds);\r\n    v_retry := greatest(5, extract(epoch from (v_oldest + make_interval(secs => p_short_seconds) - now()))::integer);\r\n    return jsonb_build_object('allowed', false, 'reason', 'short_limit', 'retryAfterSeconds', v_retry);\r\n  end if;\r\n  insert into public.ai_usage_events(identity, scope) values (p_identity, p_scope);\r\n  delete from public.ai_usage_events where created_at < now() - interval '8 days';\r\n  return jsonb_build_object('allowed', true, 'remainingToday', p_daily_limit - v_daily - 1);\r\nend $$;\r\nrevoke all on function public.consume_ai_quota(text, text, integer, integer, integer) from public, authenticated, anon;\r\ngrant execute on function public.consume_ai_quota(text, text, integer, integer, integer) to service_role;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- J. Invoice + delivery-note access, and description-only driver edits\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- Customers may replace their proof of payment while it is still pending\r\n-- review (rejected/verified proofs are immutable to the customer).\r\ndrop policy if exists \"Customers replace own pending proofs\" on public.payment_proofs;\r\ncreate policy \"Customers replace own pending proofs\" on public.payment_proofs\r\n  for update to authenticated\r\n  using (user_id = auth.uid() and status = 'pending')\r\n  with check (user_id = auth.uid() and status = 'pending');\r\n\r\ndrop policy if exists \"Customers view own shipment invoices\" on public.driver_invoices;\r\ncreate policy \"Customers view own shipment invoices\" on public.driver_invoices\r\n  for select to authenticated\r\n  using (exists (select 1 from public.shipments s where s.id = driver_invoices.shipment_id and s.user_id = auth.uid()));\r\n\r\ndrop policy if exists \"Customers view own delivery notes\" on public.delivery_notes;\r\ncreate policy \"Customers view own delivery notes\" on public.delivery_notes\r\n  for select to authenticated\r\n  using (exists (select 1 from public.shipments s where s.id = delivery_notes.shipment_id and s.user_id = auth.uid()));\r\n\r\n-- The collection invoice takes its prices from the booking (server-priced\r\n-- metadata invoice) when one exists; the driver's payload may only contribute\r\n-- corrected line descriptions. Manual bookings with no stored invoice keep the\r\n-- legacy path, and every use of it is audited.\r\ncreate or replace function public.create_driver_invoice(\r\n  p_stop_id uuid, p_line_items jsonb, p_discount numeric default 0, p_tax_rate numeric default 0,\r\n  p_currency text default 'GBP', p_notes text default null\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_stop public.driver_run_stops%rowtype; v_run public.driver_runs%rowtype;\r\n  v_ship public.shipments%rowtype; v_invoice public.driver_invoices%rowtype;\r\n  v_meta_invoice jsonb; v_items jsonb; v_discount numeric; v_tax_rate numeric; v_currency text;\r\n  v_subtotal numeric := 0; v_tax numeric := 0; v_total numeric := 0; v_number text;\r\n  v_item jsonb; v_idx integer := 0; v_correction text; v_server_priced boolean := false;\r\nbegin\r\n  select * into v_stop from public.driver_run_stops where id = p_stop_id;\r\n  if not found then raise exception 'Stop not found'; end if;\r\n  select * into v_run from public.driver_runs where id = v_stop.run_id;\r\n  if v_run.driver_id <> auth.uid() or v_stop.stop_type <> 'collection' then raise exception 'Pickup driver access required'; end if;\r\n  if v_stop.status <> 'arrived' then raise exception 'Mark the collection as arrived first'; end if;\r\n\r\n  select * into v_ship from public.shipments where id = v_stop.shipment_id;\r\n  v_meta_invoice := v_ship.metadata->'invoice';\r\n\r\n  if v_meta_invoice is not null and jsonb_typeof(v_meta_invoice->'items') = 'array'\r\n     and jsonb_array_length(v_meta_invoice->'items') > 0 then\r\n    v_server_priced := true;\r\n    v_items := '[]'::jsonb;\r\n    for v_item in select * from jsonb_array_elements(v_meta_invoice->'items') loop\r\n      v_correction := nullif(trim(coalesce(p_line_items->v_idx->>'description', '')), '');\r\n      -- Drivers may correct the wording only — quantity and price are locked.\r\n      v_items := v_items || jsonb_build_array(jsonb_build_object(\r\n        'description', coalesce(v_correction, v_item->>'description'),\r\n        'quantity', coalesce((v_item->>'quantity')::numeric, 1),\r\n        'unitPrice', coalesce((v_item->>'unitPrice')::numeric, 0)));\r\n      v_idx := v_idx + 1;\r\n    end loop;\r\n    v_discount := coalesce((v_meta_invoice->>'discount')::numeric, 0);\r\n    v_tax_rate := coalesce((v_meta_invoice->>'taxRate')::numeric, 0);\r\n    v_currency := coalesce(v_meta_invoice->>'currency', 'GBP');\r\n  else\r\n    if jsonb_typeof(p_line_items) <> 'array' or jsonb_array_length(p_line_items) = 0 then\r\n      raise exception 'Add at least one invoice item';\r\n    end if;\r\n    v_items := p_line_items; v_discount := coalesce(p_discount, 0);\r\n    v_tax_rate := coalesce(p_tax_rate, 0); v_currency := upper(coalesce(p_currency, 'GBP'));\r\n  end if;\r\n\r\n  select coalesce(sum(coalesce((x->>'quantity')::numeric, 0) * coalesce((x->>'unitPrice')::numeric, 0)), 0)\r\n    into v_subtotal from jsonb_array_elements(v_items) x;\r\n  v_tax := greatest(0, v_subtotal - v_discount) * greatest(0, v_tax_rate) / 100;\r\n  v_total := greatest(0, v_subtotal - v_discount) + v_tax;\r\n  v_number := coalesce(v_meta_invoice->>'invoiceNumber',\r\n                       'INV-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(v_stop.id::text, '-', ''), 1, 6)));\r\n\r\n  insert into public.driver_invoices(shipment_id, stop_id, driver_id, invoice_number, currency, line_items, subtotal, discount, tax, total, notes)\r\n  values (v_stop.shipment_id, v_stop.id, auth.uid(), v_number, v_currency, v_items, v_subtotal, v_discount, v_tax, v_total, p_notes)\r\n  on conflict (stop_id) do update set line_items = excluded.line_items, subtotal = excluded.subtotal,\r\n    discount = excluded.discount, tax = excluded.tax, total = excluded.total, notes = excluded.notes, updated_at = now()\r\n  returning * into v_invoice;\r\n\r\n  update public.shipments set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(\r\n    'invoice', coalesce(v_meta_invoice, '{}'::jsonb) || jsonb_build_object(\r\n      'invoiceNumber', v_invoice.invoice_number, 'issueDate', v_invoice.issue_date, 'dueDate', v_invoice.due_date,\r\n      'items', v_invoice.line_items, 'discount', v_invoice.discount, 'taxRate', v_tax_rate,\r\n      'currency', v_invoice.currency, 'sentAt', now()))\r\n  where id = v_stop.shipment_id;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), case when v_server_priced then 'DRIVER_INVOICE_CONFIRM' else 'DRIVER_INVOICE_MANUAL' end,\r\n          'DRIVER_INVOICE', v_invoice.id,\r\n          jsonb_build_object('stopId', v_stop.id, 'serverPriced', v_server_priced, 'total', v_total));\r\n\r\n  return to_jsonb(v_invoice);\r\nend $$;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- K. Route-based driver assignment\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate index if not exists shipments_schedule_idx on public.shipments(collection_schedule_id) where deleted_at is null;\r\ncreate index if not exists custom_quotes_user_status_idx on public.custom_quotes(user_id, status, created_at desc);\r\ncreate index if not exists notifications_user_created_idx on public.notifications(user_id, created_at desc);\r\n\r\n-- Assign one driver to a whole route for a given day: creates (or reuses) the\r\n-- run and adds a stop for every matching shipment not already on an active run.\r\ncreate or replace function public.assign_route_run(\r\n  p_route text,\r\n  p_run_date date,\r\n  p_driver_id uuid,\r\n  p_run_type text default 'pickup',\r\n  p_vehicle text default null\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_run public.driver_runs%rowtype;\r\n  v_added integer := 0; v_skipped integer := 0;\r\n  v_next_order integer;\r\n  v_ship record;\r\n  v_stop_type text;\r\n  v_address text;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\r\n  if p_run_type not in ('pickup', 'delivery') then raise exception 'Run type must be pickup or delivery'; end if;\r\n  v_stop_type := case when p_run_type = 'delivery' then 'delivery' else 'collection' end;\r\n\r\n  select * into v_run from public.driver_runs where driver_id = p_driver_id and run_date = p_run_date;\r\n  if found then\r\n    update public.driver_runs set route_name = p_route, run_type = p_run_type,\r\n      vehicle_label = coalesce(p_vehicle, vehicle_label), updated_at = now()\r\n    where id = v_run.id returning * into v_run;\r\n  else\r\n    insert into public.driver_runs(driver_id, run_date, status, vehicle_label, route_name, run_type)\r\n    values (p_driver_id, p_run_date, 'planned', coalesce(p_vehicle, 'Assigned vehicle'), p_route, p_run_type)\r\n    returning * into v_run;\r\n  end if;\r\n\r\n  select coalesce(max(stop_order), 0) into v_next_order from public.driver_run_stops where run_id = v_run.id;\r\n\r\n  for v_ship in\r\n    select s.*\r\n    from public.shipments s\r\n    left join public.collection_schedules cs on cs.id = s.collection_schedule_id\r\n    where s.deleted_at is null\r\n      and s.status not in ('Delivered', 'Cancelled')\r\n      and (cs.route = p_route or s.metadata->'collection'->>'route' = p_route)\r\n      and (v_stop_type <> 'collection' or coalesce(s.status, '') <> 'Collected')\r\n    order by s.created_at\r\n  loop\r\n    if exists (select 1 from public.driver_run_stops\r\n               where shipment_id = v_ship.id and stop_type = v_stop_type and status <> 'failed') then\r\n      v_skipped := v_skipped + 1;\r\n      continue;\r\n    end if;\r\n    v_next_order := v_next_order + 1;\r\n    v_address := case when v_stop_type = 'collection'\r\n      then coalesce(v_ship.metadata->'sender'->>'address', '') || ', ' || coalesce(v_ship.metadata->'sender'->>'city', '')\r\n      else coalesce(v_ship.metadata->'recipient'->>'address', '') || ', ' || coalesce(v_ship.metadata->'recipient'->>'city', '') end;\r\n    insert into public.driver_run_stops(run_id, shipment_id, stop_order, stop_type, status, address)\r\n    values (v_run.id, v_ship.id, v_next_order, v_stop_type, 'planned', nullif(trim(both ', ' from v_address), ''));\r\n    update public.shipments set assigned_driver_id = p_driver_id, driver_status = 'assigned', updated_at = now()\r\n    where id = v_ship.id;\r\n    v_added := v_added + 1;\r\n  end loop;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'ASSIGN_ROUTE', 'DRIVER_RUN', v_run.id,\r\n          jsonb_build_object('route', p_route, 'runDate', p_run_date, 'driverId', p_driver_id,\r\n                             'added', v_added, 'skipped', v_skipped));\r\n\r\n  return jsonb_build_object('runId', v_run.id, 'added', v_added, 'alreadyAssigned', v_skipped);\r\nend $$;\r\ngrant execute on function public.assign_route_run(text, date, uuid, text, text) to authenticated;\r\n\r\n-- Move a whole run to a different driver (merging into their existing run for\r\n-- that day when needed).\r\ncreate or replace function public.reassign_run_driver(p_run_id uuid, p_driver_id uuid) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_run public.driver_runs%rowtype; v_target public.driver_runs%rowtype; v_moved integer := 0;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\r\n  select * into v_run from public.driver_runs where id = p_run_id for update;\r\n  if not found then raise exception 'Run not found'; end if;\r\n  if v_run.status = 'completed' then raise exception 'This run is already completed'; end if;\r\n\r\n  select * into v_target from public.driver_runs where driver_id = p_driver_id and run_date = v_run.run_date;\r\n  if found and v_target.id <> v_run.id then\r\n    update public.driver_run_stops set run_id = v_target.id,\r\n      stop_order = stop_order + (select coalesce(max(stop_order), 0) from public.driver_run_stops where run_id = v_target.id)\r\n    where run_id = v_run.id;\r\n    get diagnostics v_moved = row_count;\r\n    update public.driver_runs set status = 'cancelled', updated_at = now() where id = v_run.id;\r\n    update public.driver_runs set route_name = coalesce(v_run.route_name, route_name), updated_at = now() where id = v_target.id;\r\n    update public.shipments set assigned_driver_id = p_driver_id\r\n    where id in (select shipment_id from public.driver_run_stops where run_id = v_target.id);\r\n    return jsonb_build_object('runId', v_target.id, 'movedStops', v_moved, 'merged', true);\r\n  end if;\r\n\r\n  update public.driver_runs set driver_id = p_driver_id, updated_at = now() where id = p_run_id;\r\n  update public.shipments set assigned_driver_id = p_driver_id\r\n  where id in (select shipment_id from public.driver_run_stops where run_id = p_run_id);\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'REASSIGN_RUN', 'DRIVER_RUN', p_run_id, jsonb_build_object('driverId', p_driver_id));\r\n  return jsonb_build_object('runId', p_run_id, 'merged', false);\r\nend $$;\r\ngrant execute on function public.reassign_run_driver(uuid, uuid) to authenticated;\r\n\r\n-- Remove one stop from a run (admin replanning).\r\ncreate or replace function public.remove_run_stop(p_stop_id uuid) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_stop public.driver_run_stops%rowtype;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\r\n  select * into v_stop from public.driver_run_stops where id = p_stop_id for update;\r\n  if not found then raise exception 'Stop not found'; end if;\r\n  if v_stop.status = 'completed' then raise exception 'A completed stop cannot be removed'; end if;\r\n  delete from public.driver_run_stops where id = p_stop_id;\r\n  update public.shipments set assigned_driver_id = null, driver_status = null, updated_at = now()\r\n  where id = v_stop.shipment_id\r\n    and not exists (select 1 from public.driver_run_stops where shipment_id = v_stop.shipment_id and status <> 'failed');\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'REMOVE_STOP', 'DRIVER_RUN_STOP', p_stop_id,\r\n          jsonb_build_object('shipmentId', v_stop.shipment_id, 'runId', v_stop.run_id));\r\n  return jsonb_build_object('removed', true, 'shipmentId', v_stop.shipment_id);\r\nend $$;\r\ngrant execute on function public.remove_run_stop(uuid) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- L. Deduplicated customer records for the admin Customers screen\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.admin_customer_records() returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_result jsonb;\r\nbegin\r\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\r\n    raise exception 'Admin or finance access required';\r\n  end if;\r\n\r\n  with shipment_identities as (\r\n    select s.id as shipment_id, s.user_id,\r\n      lower(nullif(trim(coalesce(s.metadata->'sender'->>'email', '')), '')) as email,\r\n      nullif(regexp_replace(coalesce(s.metadata->'sender'->>'phone', s.metadata->>'whatsappNumber', ''), '[^0-9]', '', 'g'), '') as phone,\r\n      coalesce(nullif(trim(s.metadata->'sender'->>'name'), ''), 'Unknown customer') as name,\r\n      s.customer_reference, s.created_at,\r\n      coalesce((\r\n        select sum(coalesce((i->>'quantity')::numeric, 0) * coalesce((i->>'unitPrice')::numeric, 0))\r\n        from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'items') = 'array'\r\n                                       then s.metadata->'invoice'->'items' else '[]'::jsonb end) i\r\n      ), 0) as invoice_total,\r\n      coalesce((s.metadata->'invoice'->>'paid')::boolean, false) as invoice_paid,\r\n      coalesce(s.metadata->'invoice'->>'currency', 'GBP') as invoice_currency,\r\n      coalesce(s.metadata->'sender'->>'country', 'United Kingdom') as country,\r\n      trim(coalesce(s.metadata->'sender'->>'address', '') || ', ' || coalesce(s.metadata->'sender'->>'city', '')) as pickup_address\r\n    from public.shipments s\r\n    where s.deleted_at is null\r\n  ),\r\n  keyed as (\r\n    select *, coalesce(user_id::text, email, phone, shipment_id::text) as dedupe_key\r\n    from shipment_identities\r\n  ),\r\n  quote_identities as (\r\n    select q.id as quote_id, q.user_id,\r\n      nullif(regexp_replace(coalesce(q.phone_number, ''), '[^0-9]', '', 'g'), '') as phone,\r\n      q.created_at\r\n    from public.custom_quotes q\r\n  ),\r\n  profile_rows as (\r\n    select p.id, p.full_name, p.email, p.phone_number, p.country, p.customer_code,\r\n           trim(coalesce(p.pickup_address, '') || ', ' || coalesce(p.pickup_city, '')) as pickup_address,\r\n           p.created_at\r\n    from public.profiles p\r\n    where coalesce(p.is_admin, false) = false\r\n      and lower(coalesce(p.role, 'customer')) not in ('admin', 'driver', 'finance', 'logistics')\r\n  ),\r\n  merged as (\r\n    select\r\n      coalesce(pr.id::text, k.dedupe_key) as key,\r\n      coalesce(pr.full_name, max(k.name)) as full_name,\r\n      coalesce(pr.email, max(k.email)) as email,\r\n      coalesce(pr.phone_number, max(k.phone)) as phone,\r\n      coalesce(pr.country, max(k.country)) as country,\r\n      coalesce(pr.customer_code, max(k.customer_reference)) as customer_reference,\r\n      coalesce(nullif(pr.pickup_address, ','), max(nullif(k.pickup_address, ','))) as pickup_address,\r\n      count(distinct k.shipment_id) as shipment_count,\r\n      sum(case when not k.invoice_paid then k.invoice_total else 0 end) as outstanding,\r\n      max(k.invoice_currency) as currency,\r\n      greatest(coalesce(max(k.created_at), 'epoch'::timestamptz), coalesce(pr.created_at, 'epoch'::timestamptz)) as last_activity,\r\n      pr.id as profile_id\r\n    from profile_rows pr\r\n    full outer join keyed k\r\n      on k.user_id = pr.id\r\n      or (k.user_id is null and k.email is not null and k.email = lower(coalesce(pr.email, '')))\r\n      or (k.user_id is null and k.email is null and k.phone is not null\r\n          and k.phone = regexp_replace(coalesce(pr.phone_number, ''), '[^0-9]', '', 'g'))\r\n    group by pr.id, pr.full_name, pr.email, pr.phone_number, pr.country, pr.customer_code, pr.pickup_address, pr.created_at, coalesce(pr.id::text, k.dedupe_key)\r\n  )\r\n  select coalesce(jsonb_agg(jsonb_build_object(\r\n    'key', m.key,\r\n    'profileId', m.profile_id,\r\n    'fullName', coalesce(m.full_name, 'Unknown customer'),\r\n    'email', m.email,\r\n    'phone', m.phone,\r\n    'country', m.country,\r\n    'customerReference', m.customer_reference,\r\n    'pickupAddress', m.pickup_address,\r\n    'shipmentCount', m.shipment_count,\r\n    'quoteCount', coalesce((\r\n      select count(*) from quote_identities qi\r\n      where (m.profile_id is not null and qi.user_id = m.profile_id)\r\n         or (m.profile_id is null and qi.phone is not null and qi.phone = m.phone)), 0),\r\n    'outstanding', coalesce(m.outstanding, 0),\r\n    'currency', coalesce(m.currency, 'GBP'),\r\n    'lastActivity', m.last_activity\r\n  ) order by m.last_activity desc), '[]'::jsonb)\r\n  into v_result\r\n  from merged m;\r\n\r\n  return v_result;\r\nend $$;\r\ngrant execute on function public.admin_customer_records() to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- M. Realtime for quotes (customer app updates live)\r\n-- ---------------------------------------------------------------------------\r\n\r\ndo $$ begin alter publication supabase_realtime add table public.custom_quotes; exception when duplicate_object then null; end $$;\r\n\n\n-- Admin app redesign: server-side aggregation for Reports / Analytics /\n-- Finance Overview, pickup zones connected to real routes, staff management\n-- fields + RPCs, and richer deduplicated customer records.\n-- Applied to the live DB via the staff-ops edge function's \"setup\" action.\n\n-- ---------------------------------------------------------------------------\n-- A. Staff management fields + RPCs\n-- ---------------------------------------------------------------------------\n\nalter table public.profiles\n  add column if not exists vehicle_label text,\n  add column if not exists on_leave boolean not null default false,\n  add column if not exists staff_active boolean not null default true;\n\ncreate or replace function public.admin_staff_records() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_result jsonb;\nbegin\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'id', p.id,\n    'fullName', p.full_name,\n    'email', p.email,\n    'phone', p.phone_number,\n    'role', case when coalesce(p.is_admin, false) then 'admin' else lower(coalesce(p.role, 'staff')) end,\n    'isAdmin', coalesce(p.is_admin, false),\n    'driverType', p.driver_type,\n    'vehicle', p.vehicle_label,\n    'onLeave', p.on_leave,\n    'active', p.staff_active,\n    'createdAt', p.created_at,\n    'attendanceToday', (\n      select jsonb_build_object('clockedInAt', a.clocked_in_at, 'clockedOutAt', a.clocked_out_at)\n      from public.driver_attendance a\n      where a.driver_id = p.id and a.work_date = current_date),\n    'lastAttendance', (\n      select max(a.work_date) from public.driver_attendance a where a.driver_id = p.id),\n    'runStats', (\n      select jsonb_build_object(\n        'runs', count(distinct r.id),\n        'completedStops', count(s.id) filter (where s.status = 'completed'),\n        'failedStops', count(s.id) filter (where s.status = 'failed'),\n        'lastRunDate', max(r.run_date))\n      from public.driver_runs r\n      left join public.driver_run_stops s on s.run_id = r.id\n      where r.driver_id = p.id)\n  ) order by coalesce(p.full_name, p.email)), '[]'::jsonb)\n  into v_result\n  from public.profiles p\n  where coalesce(p.is_admin, false)\n     or lower(coalesce(p.role, '')) in ('admin', 'driver', 'finance', 'logistics', 'dispatcher', 'staff');\n  return v_result;\nend $$;\ngrant execute on function public.admin_staff_records() to authenticated;\n\ncreate or replace function public.admin_update_staff(p_user_id uuid, p_patch jsonb) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_row public.profiles%rowtype; v_role text;\nbegin\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\n  if p_patch ? 'role' then\n    v_role := lower(p_patch->>'role');\n    if v_role not in ('admin', 'driver', 'finance', 'logistics', 'dispatcher', 'customer') then\n      raise exception 'Unknown role %', v_role;\n    end if;\n  end if;\n  update public.profiles set\n    full_name = coalesce(p_patch->>'fullName', full_name),\n    phone_number = coalesce(p_patch->>'phone', phone_number),\n    role = coalesce(v_role, role),\n    driver_type = case when p_patch ? 'driverType'\n      then nullif(p_patch->>'driverType', '') else driver_type end,\n    vehicle_label = case when p_patch ? 'vehicle' then nullif(p_patch->>'vehicle', '') else vehicle_label end,\n    on_leave = coalesce((p_patch->>'onLeave')::boolean, on_leave),\n    staff_active = coalesce((p_patch->>'active')::boolean, staff_active)\n  where id = p_user_id\n  returning * into v_row;\n  if not found then raise exception 'Staff member not found'; end if;\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\n  values (auth.uid(), 'UPDATE_STAFF', 'PROFILE', p_user_id, p_patch);\n  return jsonb_build_object('id', v_row.id, 'role', v_row.role, 'active', v_row.staff_active, 'onLeave', v_row.on_leave);\nend $$;\ngrant execute on function public.admin_update_staff(uuid, jsonb) to authenticated;\n\n-- ---------------------------------------------------------------------------\n-- B. Pickup zones — real records connected to collection routes\n-- ---------------------------------------------------------------------------\n\ncreate table if not exists public.pickup_zones (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  country text not null default 'United Kingdom',\n  areas text[] not null default '{}',\n  route text,\n  color text not null default '#009B68',\n  active boolean not null default true,\n  latitude double precision,\n  longitude double precision,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (name)\n);\nalter table public.pickup_zones enable row level security;\ndrop policy if exists \"Staff read pickup zones\" on public.pickup_zones;\ncreate policy \"Staff read pickup zones\" on public.pickup_zones\n  for select to authenticated using (public.is_operations_admin() or public.is_finance_staff());\ndrop policy if exists \"Admins manage pickup zones\" on public.pickup_zones;\ncreate policy \"Admins manage pickup zones\" on public.pickup_zones\n  for all to authenticated using (public.is_operations_admin()) with check (public.is_operations_admin());\n\n-- Seed zones from the live collection routes (idempotent: only missing routes).\ninsert into public.pickup_zones (name, country, areas, route, color, latitude, longitude)\nselect distinct on (cs.route)\n  cs.route,\n  coalesce(nullif(cs.country, ''), 'United Kingdom'),\n  case when jsonb_typeof(to_jsonb(cs.areas)) = 'array'\n       then coalesce(array(select jsonb_array_elements_text(to_jsonb(cs.areas))), '{}')\n       else array[coalesce(to_jsonb(cs.areas) #>> '{}', '')] end,\n  cs.route,\n  (array['#009B68','#1d4ed8','#ea580c','#7c3aed','#0891b2','#a16207','#dc2626','#0f766e','#b45309','#4338ca'])\n    [1 + (abs(hashtext(cs.route)) % 10)],\n  case cs.route\n    when 'LONDON ROUTE' then 51.5074 when 'BIRMINGHAM ROUTE' then 52.4862\n    when 'MANCHESTER ROUTE' then 53.4808 when 'LEEDS ROUTE' then 53.8008\n    when 'CARDIFF ROUTE' then 51.4816 when 'BOURNEMOUTH ROUTE' then 50.7192\n    when 'NOTTINGHAM ROUTE' then 52.9548 when 'BRIGHTON ROUTE' then 50.8225\n    when 'SOUTHEND ROUTE' then 51.5459 when 'NORTHAMPTON ROUTE' then 52.2405\n    when 'SCOTLAND ROUTE' then 55.8642\n    else case when lower(coalesce(cs.country, '')) like '%ireland%' then 53.3498 else null end end,\n  case cs.route\n    when 'LONDON ROUTE' then -0.1278 when 'BIRMINGHAM ROUTE' then -1.8904\n    when 'MANCHESTER ROUTE' then -2.2426 when 'LEEDS ROUTE' then -1.5491\n    when 'CARDIFF ROUTE' then -3.1791 when 'BOURNEMOUTH ROUTE' then -1.8808\n    when 'NOTTINGHAM ROUTE' then -1.1581 when 'BRIGHTON ROUTE' then -0.1372\n    when 'SOUTHEND ROUTE' then 0.7077 when 'NORTHAMPTON ROUTE' then -0.9027\n    when 'SCOTLAND ROUTE' then -4.2518\n    else case when lower(coalesce(cs.country, '')) like '%ireland%' then -6.2603 else null end end\nfrom public.collection_schedules cs\nwhere nullif(trim(coalesce(cs.route, '')), '') is not null\non conflict (name) do nothing;\n\ncreate or replace function public.touch_pickup_zone() returns trigger\nlanguage plpgsql as $$ begin new.updated_at := now(); return new; end $$;\ndrop trigger if exists pickup_zones_touch on public.pickup_zones;\ncreate trigger pickup_zones_touch before update on public.pickup_zones\n  for each row execute function public.touch_pickup_zone();\n\n-- Live stats per zone: waiting shipments, drivers on the route, schedule dates.\ncreate or replace function public.admin_zone_stats() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_result jsonb;\nbegin\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\n    raise exception 'Staff access required';\n  end if;\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'zoneId', z.id,\n    'pendingCollections', (\n      select count(*) from public.shipments s\n      left join public.collection_schedules cs on cs.id = s.collection_schedule_id\n      where s.deleted_at is null\n        and s.status not in ('Delivered', 'Cancelled', 'Collected')\n        and (cs.route = z.route or s.metadata->'collection'->>'route' = z.route)),\n    'activeDrivers', (\n      select coalesce(jsonb_agg(distinct jsonb_build_object('id', p.id, 'name', coalesce(p.full_name, p.email))), '[]'::jsonb)\n      from public.driver_runs r join public.profiles p on p.id = r.driver_id\n      where r.route_name = z.route and r.run_date >= current_date and r.status in ('planned', 'active')),\n    'completedCollections', (\n      select count(*) from public.driver_run_stops st\n      join public.driver_runs r on r.id = st.run_id\n      where r.route_name = z.route and st.stop_type = 'collection' and st.status = 'completed'),\n    'scheduleDates', (\n      select coalesce(jsonb_agg(cs.pickup_date order by cs.pickup_date), '[]'::jsonb)\n      from public.collection_schedules cs where cs.route = z.route)\n  )), '[]'::jsonb)\n  into v_result from public.pickup_zones z;\n  return v_result;\nend $$;\ngrant execute on function public.admin_zone_stats() to authenticated;\n\n-- ---------------------------------------------------------------------------\n-- C. Finance overview aggregate\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.admin_finance_overview() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v jsonb;\nbegin\n  if not public.is_finance_staff() then raise exception 'Finance access required'; end if;\n\n  with completed as (\n    select * from public.payments\n    where lower(coalesce(payment_status, '')) in ('completed', 'paid', 'success', 'succeeded')\n  ),\n  approved_expenses as (\n    select * from public.finance_expenses where status in ('recorded', 'approved')\n  ),\n  currency_totals as (\n    select coalesce(c.currency, 'GBP') as currency,\n           sum(c.amount) as collected\n    from completed c group by 1\n  ),\n  daily as (\n    select d::date as day,\n      coalesce((select sum(amount) from completed where created_at::date = d::date and coalesce(currency,'GBP') = 'GBP'), 0) as in_gbp,\n      coalesce((select sum(amount) from completed where created_at::date = d::date and coalesce(currency,'GBP') = 'EUR'), 0) as in_eur,\n      coalesce((select sum(amount) from approved_expenses where expense_date = d::date), 0) as out_gbp\n    from generate_series(current_date - 29, current_date, interval '1 day') d\n  )\n  select jsonb_build_object(\n    'collectedByCurrency', (select coalesce(jsonb_object_agg(currency, collected), '{}'::jsonb) from currency_totals),\n    -- Payments awaiting a collected status: without this the screen would show\n    -- a £0 cash position while real money is sitting in \"pending\".\n    'pendingByCurrency', (select coalesce(jsonb_object_agg(currency, total), '{}'::jsonb) from (\n      select coalesce(currency, 'GBP') as currency, sum(amount) as total\n      from public.payments\n      where lower(coalesce(payment_status, '')) not in ('completed', 'paid', 'success', 'succeeded')\n        and lower(coalesce(payment_status, '')) not in ('failed', 'cancelled', 'refunded')\n      group by 1) p),\n    'pendingPaymentCount', (select count(*) from public.payments\n      where lower(coalesce(payment_status, '')) not in ('completed', 'paid', 'success', 'succeeded', 'failed', 'cancelled', 'refunded')),\n    'expensesTotal', (select coalesce(sum(amount), 0) from approved_expenses),\n    'incoming30', (select coalesce(sum(amount), 0) from completed where created_at > now() - interval '30 days'),\n    'incomingPrev30', (select coalesce(sum(amount), 0) from completed\n                       where created_at between now() - interval '60 days' and now() - interval '30 days'),\n    'outgoing30', (select coalesce(sum(amount), 0) from approved_expenses where expense_date > current_date - 30),\n    'outgoingPrev30', (select coalesce(sum(amount), 0) from approved_expenses\n                       where expense_date between current_date - 60 and current_date - 30),\n    'billedByCurrency', (select coalesce(jsonb_object_agg(currency, total), '{}'::jsonb) from (\n      select coalesce(currency, 'GBP') as currency, sum(total) as total\n      from public.driver_invoices where status <> 'void' group by 1) b),\n    'unpaidInvoices', (select count(*) from public.driver_invoices where status in ('issued', 'partial', 'overdue')),\n    'outstandingByCurrency', (select coalesce(jsonb_object_agg(currency, total), '{}'::jsonb) from (\n      select coalesce(currency, 'GBP') as currency, sum(total) as total\n      from public.driver_invoices where status in ('issued', 'partial', 'overdue') group by 1) o),\n    'unreconciledPayments', (select count(*) from public.payments where reconciled_at is null),\n    'pendingProofs', (select count(*) from public.payment_proofs where status = 'pending'),\n    'cashflow', (select coalesce(jsonb_agg(jsonb_build_object(\n      'day', to_char(day, 'YYYY-MM-DD'), 'inGBP', in_gbp, 'inEUR', in_eur, 'out', out_gbp) order by day), '[]'::jsonb) from daily),\n    'recentTransactions', (select coalesce(jsonb_agg(t order by t->>'createdAt' desc), '[]'::jsonb) from (\n      select jsonb_build_object(\n        'id', p.id, 'amount', p.amount, 'currency', coalesce(p.currency, 'GBP'),\n        'method', p.payment_method, 'status', p.payment_status,\n        'reconciled', p.reconciled_at is not null,\n        'createdAt', p.created_at,\n        'shipmentId', p.shipment_id,\n        'reference', coalesce(s.customer_reference, s.tracking_number),\n        'customer', coalesce(s.metadata->'sender'->>'name', 'Customer'),\n        'proofId', (select pp.id from public.payment_proofs pp where pp.shipment_id = p.shipment_id order by pp.created_at desc limit 1)\n      ) as t\n      from public.payments p\n      left join public.shipments s on s.id = p.shipment_id\n      order by p.created_at desc limit 20) tx)\n  ) into v;\n  return v;\nend $$;\ngrant execute on function public.admin_finance_overview() to authenticated;\n\n-- ---------------------------------------------------------------------------\n-- D. Reports / Analytics aggregate (filterable, currency-aware)\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.admin_reports(\n  p_from date,\n  p_to date,\n  p_filters jsonb default '{}'::jsonb\n) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v jsonb;\n  v_days integer := greatest(1, p_to - p_from + 1);\n  v_prev_from date := p_from - (p_to - p_from + 1);\n  v_prev_to date := p_from - 1;\n  f_country text := nullif(p_filters->>'country', '');\n  f_route text := nullif(p_filters->>'route', '');\n  f_driver uuid := nullif(p_filters->>'driver', '')::uuid;\n  f_status text := nullif(p_filters->>'status', '');\n  f_currency text := nullif(p_filters->>'currency', '');\nbegin\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\n    raise exception 'Staff access required';\n  end if;\n\n  with ships as (\n    select s.*, cs.route as schedule_route,\n      coalesce(cs.route, s.metadata->'collection'->>'route') as route,\n      coalesce(s.metadata->'sender'->>'country', 'United Kingdom') as country\n    from public.shipments s\n    left join public.collection_schedules cs on cs.id = s.collection_schedule_id\n    where s.deleted_at is null\n      and (f_country is null or coalesce(s.metadata->'sender'->>'country', 'United Kingdom') ilike '%' || f_country || '%')\n      and (f_route is null or coalesce(cs.route, s.metadata->'collection'->>'route') = f_route)\n      and (f_driver is null or s.assigned_driver_id = f_driver)\n      and (f_status is null or s.status = f_status)\n  ),\n  range_ships as (select * from ships where created_at::date between p_from and p_to),\n  prev_ships as (select * from ships where created_at::date between v_prev_from and v_prev_to),\n  -- Payments are LEFT joined so revenue is never silently understated by\n  -- payments that have no linked shipment; a matching shipment is only\n  -- required when a shipment-scoped filter is active.\n  pays as (\n    select p.*, sh.route, sh.country\n    from public.payments p\n    left join ships sh on sh.id = p.shipment_id\n    where lower(coalesce(p.payment_status, '')) in ('completed', 'paid', 'success', 'succeeded')\n      and (f_currency is null or coalesce(p.currency, 'GBP') = f_currency)\n      and (sh.id is not null\n           or (f_country is null and f_route is null and f_driver is null and f_status is null))\n  ),\n  range_pays as (select * from pays where created_at::date between p_from and p_to),\n  prev_pays as (select * from pays where created_at::date between v_prev_from and v_prev_to),\n  stops as (\n    select st.*, r.driver_id, r.route_name, r.run_date\n    from public.driver_run_stops st join public.driver_runs r on r.id = st.run_id\n    where r.run_date between p_from and p_to\n      and (f_driver is null or r.driver_id = f_driver)\n      and (f_route is null or r.route_name = f_route)\n  )\n  select jsonb_build_object(\n    'range', jsonb_build_object('from', p_from, 'to', p_to, 'days', v_days),\n    'revenue', jsonb_build_object(\n      'byCurrency', (select coalesce(jsonb_object_agg(c, t), '{}'::jsonb) from\n        (select coalesce(currency, 'GBP') c, sum(amount) t from range_pays group by 1) x),\n      'prevByCurrency', (select coalesce(jsonb_object_agg(c, t), '{}'::jsonb) from\n        (select coalesce(currency, 'GBP') c, sum(amount) t from prev_pays group by 1) x),\n      'series', (select coalesce(jsonb_agg(jsonb_build_object('day', d, 'gbp', g, 'eur', e) order by d), '[]'::jsonb) from\n        (select created_at::date d,\n                sum(amount) filter (where coalesce(currency,'GBP') = 'GBP') g,\n                sum(amount) filter (where coalesce(currency,'GBP') = 'EUR') e\n         from range_pays group by 1) x),\n      'byRoute', (select coalesce(jsonb_agg(jsonb_build_object('route', route, 'currency', c, 'total', t) order by t desc), '[]'::jsonb) from\n        (select coalesce(route, 'Unrouted') route, coalesce(currency, 'GBP') c, sum(amount) t\n         from range_pays group by 1, 2 order by 3 desc limit 12) x),\n      'byMethod', (select coalesce(jsonb_agg(jsonb_build_object('method', m, 'currency', c, 'total', t) order by t desc), '[]'::jsonb) from\n        (select coalesce(payment_method, 'Unknown') m, coalesce(currency, 'GBP') c, sum(amount) t\n         from range_pays group by 1, 2 order by 3 desc limit 12) x)),\n    'shipments', jsonb_build_object(\n      'total', (select count(*) from range_ships),\n      'prevTotal', (select count(*) from prev_ships),\n      'series', (select coalesce(jsonb_agg(jsonb_build_object('day', d, 'count', c) order by d), '[]'::jsonb) from\n        (select created_at::date d, count(*) c from range_ships group by 1) x),\n      'byStatus', (select coalesce(jsonb_object_agg(status, c), '{}'::jsonb) from\n        (select status, count(*) c from range_ships group by 1) x),\n      'byRoute', (select coalesce(jsonb_agg(jsonb_build_object('route', r, 'count', c) order by c desc), '[]'::jsonb) from\n        (select coalesce(route, 'Unrouted') r, count(*) c from range_ships group by 1 order by 2 desc limit 12) x)),\n    'collections', jsonb_build_object(\n      'completed', (select count(*) from stops where stop_type = 'collection' and status = 'completed'),\n      'failed', (select count(*) from stops where stop_type = 'collection' and status = 'failed'),\n      'byRoute', (select coalesce(jsonb_agg(jsonb_build_object('route', r, 'done', d, 'failed', f) order by d desc), '[]'::jsonb) from\n        (select coalesce(route_name, 'Unrouted') r,\n                count(*) filter (where status = 'completed') d,\n                count(*) filter (where status = 'failed') f\n         from stops where stop_type = 'collection' group by 1) x)),\n    'deliveries', jsonb_build_object(\n      'completed', (select count(*) from stops where stop_type = 'delivery' and status = 'completed'),\n      'failed', (select count(*) from stops where stop_type = 'delivery' and status = 'failed'),\n      'successRate', (select case when count(*) = 0 then null\n        else round(100.0 * count(*) filter (where status = 'completed') / count(*), 1) end\n        from stops where stop_type = 'delivery' and status in ('completed', 'failed'))),\n    'driverPerformance', (select coalesce(jsonb_agg(jsonb_build_object(\n        'driverId', driver_id, 'name', name, 'completed', done, 'failed', failed) order by done desc), '[]'::jsonb) from\n      (select st.driver_id, coalesce(p.full_name, p.email, 'Driver') as name,\n              count(*) filter (where st.status = 'completed') done,\n              count(*) filter (where st.status = 'failed') failed\n       from stops st left join public.profiles p on p.id = st.driver_id\n       group by 1, 2 order by 3 desc limit 15) x),\n    'failReasons', (select coalesce(jsonb_object_agg(reason, c), '{}'::jsonb) from\n      (select coalesce(failure_reason, 'other') reason, count(*) c\n       from stops where status = 'failed' group by 1) x),\n    'quotes', jsonb_build_object(\n      'requested', (select count(*) from public.custom_quotes where created_at::date between p_from and p_to),\n      'approved', (select count(*) from public.custom_quotes\n        where created_at::date between p_from and p_to and status in ('approved', 'booked')),\n      'booked', (select count(*) from public.custom_quotes\n        where created_at::date between p_from and p_to and status = 'booked')),\n    'customers', jsonb_build_object(\n      'new', (select count(*) from public.profiles\n        where created_at::date between p_from and p_to\n          and coalesce(is_admin, false) = false\n          and lower(coalesce(role, 'customer')) not in ('admin', 'driver', 'finance', 'logistics', 'dispatcher')),\n      'returning', (select count(*) from\n        (select user_id from range_ships where user_id is not null group by user_id\n         having count(*) > 1 or user_id in (select user_id from prev_ships where user_id is not null)) x),\n      'series', (select coalesce(jsonb_agg(jsonb_build_object('day', d, 'count', c) order by d), '[]'::jsonb) from\n        (select created_at::date d, count(*) c from public.profiles\n         where created_at::date between p_from and p_to\n           and coalesce(is_admin, false) = false\n           and lower(coalesce(role, 'customer')) not in ('admin', 'driver', 'finance', 'logistics', 'dispatcher')\n         group by 1) x)),\n    'proofs', jsonb_build_object(\n      'pending', (select count(*) from public.payment_proofs where status = 'pending'),\n      'verified', (select count(*) from public.payment_proofs\n        where status = 'verified' and reviewed_at::date between p_from and p_to),\n      'rejected', (select count(*) from public.payment_proofs\n        where status = 'rejected' and reviewed_at::date between p_from and p_to),\n      'avgValidationHours', (select round(avg(extract(epoch from (reviewed_at - created_at)) / 3600.0)::numeric, 1)\n        from public.payment_proofs where reviewed_at is not null and reviewed_at::date between p_from and p_to)),\n    'outstanding', jsonb_build_object(\n      'byCurrency', (select coalesce(jsonb_object_agg(c, t), '{}'::jsonb) from\n        (select coalesce(currency, 'GBP') c, sum(total) t from public.driver_invoices\n         where status in ('issued', 'partial', 'overdue') group by 1) x),\n      'invoices', (select count(*) from public.driver_invoices where status in ('issued', 'partial', 'overdue')))\n  ) into v;\n  return v;\nend $$;\ngrant execute on function public.admin_reports(date, date, jsonb) to authenticated;\n\n-- ---------------------------------------------------------------------------\n-- E. Customer records v2 — lifetime value, last booking, active flag\n-- ---------------------------------------------------------------------------\n\ncreate or replace function public.admin_customer_records() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_result jsonb;\nbegin\n  if not (public.is_operations_admin() or public.is_finance_staff()) then\n    raise exception 'Admin or finance access required';\n  end if;\n\n  with shipment_identities as (\n    select s.id as shipment_id, s.user_id,\n      lower(nullif(trim(coalesce(s.metadata->'sender'->>'email', '')), '')) as email,\n      nullif(regexp_replace(coalesce(s.metadata->'sender'->>'phone', s.metadata->>'whatsappNumber', ''), '[^0-9]', '', 'g'), '') as phone,\n      -- Resolve the sender name the same way the app does: prefer sender.name,\n      -- then firstName + lastName. Leave NULL when truly absent so max() below\n      -- picks a real name from the group instead of a premature 'Unknown\n      -- customer' literal (which sorts high and would win the max()).\n      coalesce(\n        nullif(trim(s.metadata->'sender'->>'name'), ''),\n        nullif(trim(coalesce(s.metadata->'sender'->>'firstName', '') || ' ' || coalesce(s.metadata->'sender'->>'lastName', '')), '')\n      ) as name,\n      s.customer_reference, s.created_at, s.tracking_number,\n      coalesce((\n        select sum(coalesce((i->>'quantity')::numeric, 0) * coalesce((i->>'unitPrice')::numeric, 0))\n        from jsonb_array_elements(case when jsonb_typeof(s.metadata->'invoice'->'items') = 'array'\n                                       then s.metadata->'invoice'->'items' else '[]'::jsonb end) i\n      ), 0) as invoice_total,\n      coalesce((s.metadata->'invoice'->>'paid')::boolean, false) as invoice_paid,\n      coalesce(s.metadata->'invoice'->>'currency', 'GBP') as invoice_currency,\n      coalesce(s.metadata->'sender'->>'country', 'United Kingdom') as country,\n      trim(coalesce(s.metadata->'sender'->>'address', '') || ', ' || coalesce(s.metadata->'sender'->>'city', '')) as pickup_address\n    from public.shipments s\n    where s.deleted_at is null\n  ),\n  keyed as (\n    select *, coalesce(user_id::text, email, phone, shipment_id::text) as dedupe_key\n    from shipment_identities\n  ),\n  quote_identities as (\n    select q.id as quote_id, q.user_id,\n      nullif(regexp_replace(coalesce(q.phone_number, ''), '[^0-9]', '', 'g'), '') as phone,\n      q.created_at\n    from public.custom_quotes q\n  ),\n  profile_rows as (\n    select p.id, p.full_name, p.email, p.phone_number, p.country, p.customer_code,\n           trim(coalesce(p.pickup_address, '') || ', ' || coalesce(p.pickup_city, '')) as pickup_address,\n           p.created_at\n    from public.profiles p\n    where coalesce(p.is_admin, false) = false\n      and lower(coalesce(p.role, 'customer')) not in ('admin', 'driver', 'finance', 'logistics', 'dispatcher')\n  ),\n  -- A FULL OUTER JOIN cannot use OR conditions in Postgres, so shipments are\n  -- matched to profiles with a LEFT JOIN and profile-only customers are added\n  -- back with a UNION.\n  keyed_matched as (\n    select k.*, pr.id as matched_profile\n    from keyed k\n    left join profile_rows pr\n      on k.user_id = pr.id\n      or (k.user_id is null and k.email is not null and k.email = lower(coalesce(pr.email, '')))\n      or (k.user_id is null and k.email is null and k.phone is not null\n          and k.phone = regexp_replace(coalesce(pr.phone_number, ''), '[^0-9]', '', 'g'))\n  ),\n  grouped as (\n    select\n      coalesce(km.matched_profile::text, km.dedupe_key) as key,\n      km.matched_profile as profile_id,\n      max(km.name) as ship_name,\n      max(km.email) as ship_email,\n      max(km.phone) as ship_phone,\n      max(km.country) as ship_country,\n      max(km.customer_reference) as ship_reference,\n      max(nullif(km.pickup_address, ',')) as ship_pickup,\n      count(distinct km.shipment_id) as shipment_count,\n      sum(km.invoice_total) as lifetime_value,\n      sum(case when not km.invoice_paid then km.invoice_total else 0 end) as outstanding,\n      max(km.invoice_currency) as currency,\n      max(km.created_at) as last_booking\n    from keyed_matched km\n    group by 1, 2\n  ),\n  merged as (\n    select g.key,\n      coalesce(pr.full_name, g.ship_name) as full_name,\n      coalesce(pr.email, g.ship_email) as email,\n      coalesce(pr.phone_number, g.ship_phone) as phone,\n      coalesce(pr.country, g.ship_country) as country,\n      coalesce(pr.customer_code, g.ship_reference) as customer_reference,\n      coalesce(nullif(pr.pickup_address, ','), g.ship_pickup) as pickup_address,\n      g.shipment_count, g.lifetime_value, g.outstanding, g.currency, g.last_booking,\n      greatest(coalesce(g.last_booking, 'epoch'::timestamptz), coalesce(pr.created_at, 'epoch'::timestamptz)) as last_activity,\n      g.profile_id\n    from grouped g\n    left join profile_rows pr on pr.id = g.profile_id\n    union all\n    select pr.id::text, pr.full_name, pr.email, pr.phone_number, pr.country, pr.customer_code,\n      nullif(pr.pickup_address, ','), 0, 0, 0, 'GBP', null,\n      coalesce(pr.created_at, 'epoch'::timestamptz), pr.id\n    from profile_rows pr\n    where not exists (select 1 from grouped g where g.profile_id = pr.id)\n  )\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'key', m.key,\n    'profileId', m.profile_id,\n    'fullName', coalesce(m.full_name, 'Unknown customer'),\n    'email', m.email,\n    'phone', m.phone,\n    'country', m.country,\n    'customerReference', m.customer_reference,\n    'pickupAddress', m.pickup_address,\n    'shipmentCount', m.shipment_count,\n    'quoteCount', coalesce((\n      select count(*) from quote_identities qi\n      where (m.profile_id is not null and qi.user_id = m.profile_id)\n         or (m.profile_id is null and qi.phone is not null and qi.phone = m.phone)), 0),\n    'lifetimeValue', coalesce(m.lifetime_value, 0),\n    'outstanding', coalesce(m.outstanding, 0),\n    'currency', coalesce(m.currency, 'GBP'),\n    'lastBooking', m.last_booking,\n    'lastActivity', m.last_activity,\n    'active', m.last_activity > now() - interval '180 days'\n  ) order by m.last_activity desc), '[]'::jsonb)\n  into v_result\n  from merged m;\n\n  return v_result;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- F. Reorder a stop within its run\n-- ---------------------------------------------------------------------------\n\n-- driver_run_stops has unique(run_id, stop_order), so a direct swap violates\n-- the constraint mid-statement; the moving row is parked on a negative order\n-- first. Completed stops keep their position in the delivered sequence.\ncreate or replace function public.reorder_run_stop(p_stop_id uuid, p_direction text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_stop public.driver_run_stops%rowtype; v_other public.driver_run_stops%rowtype;\nbegin\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\n  if p_direction not in ('up', 'down') then raise exception 'Direction must be up or down'; end if;\n\n  select * into v_stop from public.driver_run_stops where id = p_stop_id for update;\n  if not found then raise exception 'Stop not found'; end if;\n  if v_stop.status in ('completed', 'failed') then\n    raise exception 'A completed or failed stop cannot be moved';\n  end if;\n\n  if p_direction = 'up' then\n    select * into v_other from public.driver_run_stops\n    where run_id = v_stop.run_id and stop_order < v_stop.stop_order\n      and status not in ('completed', 'failed')\n    order by stop_order desc limit 1 for update;\n  else\n    select * into v_other from public.driver_run_stops\n    where run_id = v_stop.run_id and stop_order > v_stop.stop_order\n      and status not in ('completed', 'failed')\n    order by stop_order asc limit 1 for update;\n  end if;\n  if not found then return jsonb_build_object('moved', false, 'reason', 'already at the end'); end if;\n\n  update public.driver_run_stops set stop_order = -1, updated_at = now() where id = v_stop.id;\n  update public.driver_run_stops set stop_order = v_stop.stop_order, updated_at = now() where id = v_other.id;\n  update public.driver_run_stops set stop_order = v_other.stop_order, updated_at = now() where id = v_stop.id;\n\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\n  values (auth.uid(), 'REORDER_STOP', 'DRIVER_RUN_STOP', v_stop.id,\n          jsonb_build_object('runId', v_stop.run_id, 'from', v_stop.stop_order, 'to', v_other.stop_order));\n\n  return jsonb_build_object('moved', true, 'stopOrder', v_other.stop_order);\nend $$;\ngrant execute on function public.reorder_run_stop(uuid, text) to authenticated;\n\n-- ---------------------------------------------------------------------------\n-- G. Indexes for the report ranges and lists\n-- ---------------------------------------------------------------------------\n\ncreate index if not exists payments_created_idx on public.payments(created_at desc);\ncreate index if not exists shipments_created_idx on public.shipments(created_at desc) where deleted_at is null;\ncreate index if not exists driver_runs_date_idx on public.driver_runs(run_date desc);\ncreate index if not exists custom_quotes_created_idx on public.custom_quotes(created_at desc);\ncreate index if not exists delivery_notes_created_idx on public.delivery_notes(created_at desc);\ncreate index if not exists payment_proofs_reviewed_idx on public.payment_proofs(reviewed_at desc) where reviewed_at is not null;\n\n\n-- Data fix: correct misspelled area names in collection_schedules.\n-- These area names drive postcode/city -> route matching in the customer app,\n-- staff app and website, so typos silently misroute or fail to match.\n--\n-- collection_schedules.areas is a Postgres text[] array. Each UPDATE replaces\n-- the whole array with the corrected version but is GUARDED by the presence of\n-- a distinctive typo token (areas @> ARRAY['TYPO']). That makes every statement\n-- idempotent AND self-deactivating: once the typo is gone the guard no longer\n-- matches, so re-running setup will not re-apply the change or clobber any later\n-- intentional edit to that route.\n--\n-- NOTE: the CARDIFF ROUTE contains the token \"HIJJ\", which does not map to any\n-- real place. It is intentionally left untouched pending a human decision.\n\n-- BIRMINGHAM ROUTE: WOLVEHAMPTON -> WOLVERHAMPTON\nupdate public.collection_schedules\nset areas = ARRAY['WOLVERHAMPTON','COVENTRY','WARWICK','DUDLEY','WALSALL','RUGBY']::text[]\nwhere route = 'BIRMINGHAM ROUTE' and areas @> ARRAY['WOLVEHAMPTON']::text[];\n\n-- BOURNEMOUTH ROUTE: HAMPHIRE -> HAMPSHIRE, GUILFORD -> GUILDFORD\nupdate public.collection_schedules\nset areas = ARRAY['SOUTHAMPTON','OXFORD','HAMPSHIRE','READING','GUILDFORD','PORTSMOUTH']::text[]\nwhere route = 'BOURNEMOUTH ROUTE' and areas @> ARRAY['HAMPHIRE']::text[];\n\n-- BRIGHTON ROUTE: HIGH COMBE -> HIGH WYCOMBE, VRAWLEY -> CRAWLEY, CANTEBURY -> CANTERBURY\nupdate public.collection_schedules\nset areas = ARRAY['HIGH WYCOMBE','SLOUGH','CRAWLEY','LANCING','EASTBOURNE','CANTERBURY']::text[]\nwhere route = 'BRIGHTON ROUTE' and areas @> ARRAY['CANTEBURY']::text[];\n\n-- MANCHESTER ROUTE: SHREWBURY -> SHREWSBURY\nupdate public.collection_schedules\nset areas = ARRAY['LIVERPOOL','STOKE ON TRENT','BOLTON','WARRINGTON','OLDHAM','SHREWSBURY']::text[]\nwhere route = 'MANCHESTER ROUTE' and areas @> ARRAY['SHREWBURY']::text[];\n\n-- NOTTINGHAM ROUTE: LIECESTER -> LEICESTER, PETERSBOROUGH -> PETERBOROUGH,\n--                   MARKET HARB -> MARKET HARBOROUGH\nupdate public.collection_schedules\nset areas = ARRAY['LEICESTER','DERBY','PETERBOROUGH','CORBY','MARKET HARBOROUGH']::text[]\nwhere route = 'NOTTINGHAM ROUTE' and areas @> ARRAY['LIECESTER']::text[];\n\n-- BELFAST: Newtownwards -> Newtownards\nupdate public.collection_schedules\nset areas = ARRAY['Belfast','Bangor','Comber','Lisburn','Newry','Newtownards','Dunmurry','Lurgan','Portadown','Banbridge','Moy','Dungannon','Armagh']::text[]\nwhere route = 'BELFAST' and areas @> ARRAY['Newtownwards']::text[];\n\n-- CARDIFF ROUTE: remove the junk token \"HIJJ\". It maps to no real place and is\n-- absent from the curated source list (src/data/collectionSchedule.ts), so it is\n-- an accidental entry. Restore the route to its six real areas.\nupdate public.collection_schedules\nset areas = ARRAY['CARDIFF','GLOUCESTER','BRISTOL','SWINDON','BATH','SALISBURY']::text[]\nwhere route = 'CARDIFF ROUTE' and areas @> ARRAY['HIJJ']::text[];\n\n\n-- Booking → account linking, self-collection depots, and a geocode cache for\r\n-- the driver map.\r\n--\r\n-- NOTE: applied to the live DB via the staff-ops edge function's \"setup\"\r\n-- action (migration history is out of sync — never `db push`). This file is\r\n-- documentation of the applied DDL, and the source the embed script reads.\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Claim guest bookings onto a real account\r\n-- ---------------------------------------------------------------------------\r\n-- Every website booking was created with user_id = null, so signed-in\r\n-- customers saw an empty dashboard. New bookings now carry the user_id, and\r\n-- this function retro-attaches the historical guest bookings (and any future\r\n-- guest booking made before the customer registered) by matching the sender\r\n-- email captured on the shipment.\r\n--\r\n-- The email is read from auth.users for the caller — never accepted as an\r\n-- argument — and must be confirmed, so registering with somebody else's\r\n-- address cannot be used to harvest their shipments.\r\n\r\ncreate or replace function public.claim_guest_bookings()\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_email text;\r\n  v_confirmed timestamptz;\r\n  v_shipment_ids uuid[];\r\n  v_claimed integer := 0;\r\nbegin\r\n  if v_uid is null then\r\n    raise exception 'Sign in to claim your bookings';\r\n  end if;\r\n\r\n  select lower(trim(email)), email_confirmed_at\r\n    into v_email, v_confirmed\r\n    from auth.users where id = v_uid;\r\n\r\n  -- An unconfirmed address proves nothing about who owns it.\r\n  if v_email is null or v_email = '' or v_confirmed is null then\r\n    return jsonb_build_object('claimed', 0, 'reason', 'email_unconfirmed');\r\n  end if;\r\n\r\n  -- Collect first so payments and receipts can be moved in the same pass.\r\n  select coalesce(array_agg(id), '{}') into v_shipment_ids\r\n  from public.shipments\r\n  where user_id is null\r\n    and deleted_at is null\r\n    and lower(trim(coalesce(\r\n      metadata->'sender'->>'email',\r\n      metadata->'senderDetails'->>'email'\r\n    ))) = v_email;\r\n\r\n  if coalesce(array_length(v_shipment_ids, 1), 0) = 0 then\r\n    return jsonb_build_object('claimed', 0);\r\n  end if;\r\n\r\n  update public.shipments\r\n     set user_id = v_uid, updated_at = now()\r\n   where id = any(v_shipment_ids);\r\n  v_claimed := coalesce(array_length(v_shipment_ids, 1), 0);\r\n\r\n  update public.payments\r\n     set user_id = v_uid\r\n   where shipment_id = any(v_shipment_ids) and user_id is null;\r\n\r\n  update public.receipts\r\n     set user_id = v_uid\r\n   where shipment_id = any(v_shipment_ids) and user_id is null;\r\n\r\n  insert into public.audit_logs (user_id, action, entity_type, entity_id, details)\r\n  values (v_uid, 'CLAIM_GUEST_BOOKINGS', 'SHIPMENT', null,\r\n          jsonb_build_object('email', v_email, 'count', v_claimed));\r\n\r\n  return jsonb_build_object('claimed', v_claimed);\r\nend $$;\r\n\r\nrevoke all on function public.claim_guest_bookings() from public, anon;\r\ngrant execute on function public.claim_guest_bookings() to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. Self-collection depots\r\n-- ---------------------------------------------------------------------------\r\n-- Door-to-door delivery is unchanged and still carries its £25/€25 per-address\r\n-- fee. Self-collection is an additional, free option: the shipment is held at\r\n-- a depot for the receiver to collect.\r\n\r\ncreate table if not exists public.delivery_depots (\r\n  id uuid primary key default gen_random_uuid(),\r\n  name text not null,\r\n  city text not null,\r\n  address_line1 text not null,\r\n  address_line2 text,\r\n  province text,\r\n  country text not null default 'Zimbabwe',\r\n  phone text,\r\n  opening_hours text,\r\n  latitude double precision,\r\n  longitude double precision,\r\n  notes text,\r\n  active boolean not null default true,\r\n  sort_order integer not null default 0,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists delivery_depots_active_idx\r\n  on public.delivery_depots(active, sort_order);\r\n\r\nalter table public.delivery_depots enable row level security;\r\n\r\n-- Depot addresses are published information: customers must be able to read\r\n-- them while choosing self-collection, including before they sign in.\r\ndrop policy if exists \"Anyone can read active depots\" on public.delivery_depots;\r\ncreate policy \"Anyone can read active depots\" on public.delivery_depots\r\n  for select to anon, authenticated\r\n  using (active = true);\r\n\r\ndrop policy if exists \"Admins manage depots\" on public.delivery_depots;\r\ncreate policy \"Admins manage depots\" on public.delivery_depots\r\n  for all to authenticated\r\n  using (\r\n    exists (\r\n      select 1 from public.profiles\r\n      where id = auth.uid()\r\n        and (is_admin = true or lower(coalesce(role, '')) in ('admin', 'logistics'))\r\n    )\r\n  )\r\n  with check (\r\n    exists (\r\n      select 1 from public.profiles\r\n      where id = auth.uid()\r\n        and (is_admin = true or lower(coalesce(role, '')) in ('admin', 'logistics'))\r\n    )\r\n  );\r\n\r\n-- Bulawayo is the launch collection point. Address and hours are editable from\r\n-- the admin dashboard — this only seeds the row so booking has something to\r\n-- offer on day one.\r\ninsert into public.delivery_depots (name, city, address_line1, province, country, opening_hours, sort_order)\r\nselect 'Bulawayo Depot', 'Bulawayo', 'Address to be confirmed', 'Bulawayo', 'Zimbabwe',\r\n       'Mon–Fri 09:00–17:00, Sat 09:00–13:00', 1\r\nwhere not exists (\r\n  select 1 from public.delivery_depots where lower(city) = 'bulawayo'\r\n);\r\n\r\n-- Records the delivery choice on a booking the customer app just created.\r\n--\r\n-- `create_customer_booking` is long and load-bearing, and its pricing already\r\n-- charges £25/€25 per selected delivery address and nothing when none are\r\n-- selected — which is exactly right for self-collection. So rather than editing\r\n-- it, this small routine annotates the shipment afterwards with which option was\r\n-- chosen and from which depot. No pricing is involved.\r\ncreate or replace function public.set_booking_delivery_method(\r\n  p_shipment_id uuid,\r\n  p_method text,\r\n  p_depot_id uuid default null\r\n)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_depot public.delivery_depots%rowtype;\r\n  v_owner uuid;\r\nbegin\r\n  if v_uid is null then raise exception 'Sign in to update a booking'; end if;\r\n  if p_method not in ('door', 'self_collection') then\r\n    raise exception 'Unknown delivery method %', p_method;\r\n  end if;\r\n\r\n  -- Only the booking's owner (or staff) may change this.\r\n  select user_id into v_owner from public.shipments where id = p_shipment_id;\r\n  if v_owner is null and not public.is_operations_admin() then\r\n    raise exception 'Booking not found';\r\n  end if;\r\n  if v_owner is not null and v_owner <> v_uid and not public.is_operations_admin() then\r\n    raise exception 'Booking not found';\r\n  end if;\r\n\r\n  if p_depot_id is not null then\r\n    select * into v_depot from public.delivery_depots where id = p_depot_id and active;\r\n    if not found then raise exception 'That collection point is not available'; end if;\r\n  end if;\r\n\r\n  update public.shipments set\r\n    metadata = jsonb_set(\r\n      jsonb_set(\r\n        coalesce(metadata, '{}'::jsonb),\r\n        '{recipient,deliveryMethod}', to_jsonb(p_method), true),\r\n      '{recipient,depot}',\r\n      case when p_depot_id is null then 'null'::jsonb else jsonb_build_object(\r\n        'id', v_depot.id, 'name', v_depot.name, 'city', v_depot.city,\r\n        'address', trim(v_depot.address_line1 || coalesce(', ' || nullif(v_depot.address_line2, ''), '')),\r\n        'phone', v_depot.phone, 'openingHours', v_depot.opening_hours) end,\r\n      true),\r\n    updated_at = now()\r\n  where id = p_shipment_id;\r\n\r\n  return jsonb_build_object('ok', true, 'method', p_method, 'depotId', p_depot_id);\r\nend $$;\r\n\r\ngrant execute on function public.set_booking_delivery_method(uuid, text, uuid) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. Geocode cache for the driver map\r\n-- ---------------------------------------------------------------------------\r\n-- driver_run_stops has latitude/longitude columns that nothing ever populated,\r\n-- so the driver map had no pins to draw. Lookups are cached because the free\r\n-- geocoders (postcodes.io, Nominatim) are rate limited and their usage policy\r\n-- expects results to be reused rather than re-requested.\r\n\r\ncreate table if not exists public.geocode_cache (\r\n  lookup_key text primary key,\r\n  query text not null,\r\n  latitude double precision,\r\n  longitude double precision,\r\n  source text not null,\r\n  resolved boolean not null default false,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\nalter table public.geocode_cache enable row level security;\r\n\r\n-- Only the geocoding edge function (service role) touches this table; the\r\n-- service role bypasses RLS, so no client-facing policy is granted.\r\ndrop policy if exists \"Staff read geocode cache\" on public.geocode_cache;\r\ncreate policy \"Staff read geocode cache\" on public.geocode_cache\r\n  for select to authenticated\r\n  using (\r\n    exists (\r\n      select 1 from public.profiles\r\n      where id = auth.uid()\r\n        and (is_admin = true or lower(coalesce(role, '')) in ('admin', 'logistics', 'driver', 'dispatcher'))\r\n    )\r\n  );\r\n\r\n-- Depot coordinates double as delivery pins on the driver map.\r\ncreate index if not exists driver_run_stops_missing_coords_idx\r\n  on public.driver_run_stops(run_id)\r\n  where latitude is null or longitude is null;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Fix: admin_update_staff never synchronised is_admin with role\r\n-- ---------------------------------------------------------------------------\r\n-- Promoting somebody to 'admin' set profiles.role = 'admin' but left\r\n-- profiles.is_admin = false, and demoting an admin left is_admin = true. Many\r\n-- RLS policies test `is_admin = true or role in (...)`, so a promotion appeared\r\n-- to work while granting nothing, and a demotion removed nothing.\r\n\r\ncreate or replace function public.admin_update_staff(p_user_id uuid, p_patch jsonb)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare v_row public.profiles%rowtype; v_role text;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\r\n  if p_patch ? 'role' then\r\n    v_role := lower(p_patch->>'role');\r\n    if v_role not in ('admin', 'driver', 'finance', 'logistics', 'dispatcher', 'customer') then\r\n      raise exception 'Unknown role %', v_role;\r\n    end if;\r\n  end if;\r\n\r\n  update public.profiles set\r\n    full_name = coalesce(p_patch->>'fullName', full_name),\r\n    phone_number = coalesce(p_patch->>'phone', phone_number),\r\n    role = coalesce(v_role, role),\r\n    -- Keep the two representations of \"is an admin\" in agreement. Only touched\r\n    -- when the role is actually being changed.\r\n    is_admin = case when v_role is null then is_admin else v_role = 'admin' end,\r\n    driver_type = case when p_patch ? 'driverType'\r\n      then nullif(p_patch->>'driverType', '') else driver_type end,\r\n    vehicle_label = case when p_patch ? 'vehicle' then nullif(p_patch->>'vehicle', '') else vehicle_label end,\r\n    on_leave = coalesce((p_patch->>'onLeave')::boolean, on_leave),\r\n    staff_active = coalesce((p_patch->>'active')::boolean, staff_active)\r\n  where id = p_user_id\r\n  returning * into v_row;\r\n  if not found then raise exception 'Staff member not found'; end if;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'UPDATE_STAFF', 'PROFILE', p_user_id, p_patch);\r\n\r\n  return jsonb_build_object(\r\n    'id', v_row.id, 'role', v_row.role, 'isAdmin', v_row.is_admin,\r\n    'active', v_row.staff_active, 'onLeave', v_row.on_leave);\r\nend $$;\r\n\r\ngrant execute on function public.admin_update_staff(uuid, jsonb) to authenticated;\r\n\n\n-- Draft → approve workflow for collection schedules, and an AI invoice-scan\r\n-- audit trail.\r\n--\r\n-- NOTE: applied to the live DB via the staff-ops edge function's \"setup\"\r\n-- action (migration history is out of sync — never `db push`).\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Approval state on collection_schedules\r\n-- ---------------------------------------------------------------------------\r\n-- The website, both apps and the WhatsApp/AI bot all read collection_schedules\r\n-- directly, so anything written there is instantly public. Generating a proposed\r\n-- schedule therefore needs somewhere to sit that is NOT yet public.\r\n--\r\n-- `approved` defaults to TRUE so every schedule that already exists stays\r\n-- published exactly as it is — this migration must not blank the live site.\r\n-- Only rows created by generate_collection_schedules() start unapproved.\r\n\r\nalter table public.collection_schedules\r\n  add column if not exists approved boolean not null default true,\r\n  add column if not exists approved_at timestamptz,\r\n  add column if not exists approved_by uuid references auth.users(id) on delete set null,\r\n  add column if not exists generated_at timestamptz,\r\n  add column if not exists generated_from_id uuid;\r\n\r\ncreate index if not exists collection_schedules_approved_idx\r\n  on public.collection_schedules(approved);\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. Generate the next round of collection dates\r\n-- ---------------------------------------------------------------------------\r\n-- Collections run on a monthly cadence per route. For each route that currently\r\n-- has a published date, this proposes the next one by stepping the most recent\r\n-- date forward by `p_interval_days` (default 28, i.e. a four-week cycle), keeping\r\n-- the route's areas and country.\r\n--\r\n-- Proposals are inserted with approved = false, so nothing reaches customers\r\n-- until an admin approves. Re-running is safe: a route that already has an\r\n-- unapproved draft is skipped rather than duplicated.\r\n\r\ncreate or replace function public.generate_collection_schedules(\r\n  p_interval_days integer default 28,\r\n  p_from_date date default null\r\n)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_route record;\r\n  v_created integer := 0;\r\n  v_skipped integer := 0;\r\n  v_base date;\r\n  v_next date;\r\n  v_drafts jsonb := '[]'::jsonb;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\r\n  if p_interval_days < 1 or p_interval_days > 120 then\r\n    raise exception 'Interval must be between 1 and 120 days';\r\n  end if;\r\n\r\n  for v_route in\r\n    -- Latest approved row per route is the anchor for the next date.\r\n    select distinct on (route)\r\n      id, route, areas, country, pickup_date\r\n    from public.collection_schedules\r\n    where approved = true\r\n    order by route, coalesce(generated_at, created_at) desc\r\n  loop\r\n    -- Skip routes that already have a pending draft awaiting approval.\r\n    if exists (\r\n      select 1 from public.collection_schedules\r\n      where route = v_route.route and approved = false\r\n    ) then\r\n      v_skipped := v_skipped + 1;\r\n      continue;\r\n    end if;\r\n\r\n    -- pickup_date is free text. Live data is written in ordinal form\r\n    -- (\"August 5th, 2026\"), which Postgres cannot cast — the \"th\" makes it\r\n    -- invalid input. Strip the ordinal suffix first, otherwise every route\r\n    -- falls through to the fallback and they all generate the same date.\r\n    begin\r\n      v_base := coalesce(\r\n        p_from_date,\r\n        regexp_replace(v_route.pickup_date, '(\\d+)(st|nd|rd|th)', '\\1', 'gi')::date\r\n      );\r\n    exception when others then\r\n      v_base := coalesce(p_from_date, current_date);\r\n    end;\r\n\r\n    v_next := v_base + p_interval_days;\r\n    -- Never propose a date in the past.\r\n    while v_next < current_date loop\r\n      v_next := v_next + p_interval_days;\r\n    end loop;\r\n\r\n    insert into public.collection_schedules\r\n      (route, areas, country, pickup_date, approved, generated_at, generated_from_id)\r\n    values\r\n      (v_route.route, v_route.areas, v_route.country,\r\n       to_char(v_next, 'FMMonth FMDDth, YYYY'), false, now(), v_route.id);\r\n\r\n    v_created := v_created + 1;\r\n    v_drafts := v_drafts || jsonb_build_array(jsonb_build_object(\r\n      'route', v_route.route, 'pickupDate', to_char(v_next, 'FMMonth FMDDth, YYYY')));\r\n  end loop;\r\n\r\n  insert into public.audit_logs (user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'GENERATE_SCHEDULES', 'COLLECTION_SCHEDULE', null,\r\n          jsonb_build_object('created', v_created, 'skipped', v_skipped, 'intervalDays', p_interval_days));\r\n\r\n  return jsonb_build_object('created', v_created, 'skipped', v_skipped, 'drafts', v_drafts);\r\nend $$;\r\n\r\ngrant execute on function public.generate_collection_schedules(integer, date) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. Approve (publish) or discard drafts\r\n-- ---------------------------------------------------------------------------\r\n-- Approving is the moment a date becomes visible on the website, in both apps\r\n-- and to the AI bot, because they all read this table.\r\n\r\ncreate or replace function public.approve_collection_schedules(p_ids uuid[] default null)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare v_count integer;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\r\n\r\n  with promoted as (\r\n    update public.collection_schedules\r\n       set approved = true, approved_at = now(), approved_by = auth.uid(), updated_at = now()\r\n     where approved = false\r\n       and (p_ids is null or id = any(p_ids))\r\n    returning id, route, pickup_date, generated_from_id\r\n  ),\r\n  -- A newly approved date supersedes the row it was generated from, so the old\r\n  -- one is removed. Without this the site would list two dates per route.\r\n  superseded as (\r\n    delete from public.collection_schedules\r\n     where id in (select generated_from_id from promoted where generated_from_id is not null)\r\n    returning id\r\n  )\r\n  select count(*) into v_count from promoted;\r\n\r\n  insert into public.audit_logs (user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'APPROVE_SCHEDULES', 'COLLECTION_SCHEDULE', null,\r\n          jsonb_build_object('approved', v_count));\r\n\r\n  return jsonb_build_object('approved', v_count);\r\nend $$;\r\n\r\ngrant execute on function public.approve_collection_schedules(uuid[]) to authenticated;\r\n\r\ncreate or replace function public.discard_collection_schedule_drafts(p_ids uuid[] default null)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare v_count integer;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Admin access required'; end if;\r\n  with removed as (\r\n    delete from public.collection_schedules\r\n     where approved = false and (p_ids is null or id = any(p_ids))\r\n    returning id\r\n  )\r\n  select count(*) into v_count from removed;\r\n  return jsonb_build_object('discarded', v_count);\r\nend $$;\r\n\r\ngrant execute on function public.discard_collection_schedule_drafts(uuid[]) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Hide unapproved drafts from everything customer-facing\r\n-- ---------------------------------------------------------------------------\r\n-- Customers and the bot read this table with the anon/authenticated roles. A\r\n-- draft must not appear until approved, so the read policy is narrowed while\r\n-- admins keep full visibility.\r\n\r\nalter table public.collection_schedules enable row level security;\r\n\r\ndo $$\r\ndeclare v_policy record;\r\nbegin\r\n  for v_policy in\r\n    select policyname from pg_policies\r\n    where schemaname = 'public' and tablename = 'collection_schedules'\r\n      and cmd in ('SELECT', 'ALL')\r\n      and coalesce(btrim(qual), '') in ('true', '(true)')\r\n  loop\r\n    execute format('drop policy if exists %I on public.collection_schedules', v_policy.policyname);\r\n  end loop;\r\nend $$;\r\n\r\ndrop policy if exists \"Anyone reads approved schedules\" on public.collection_schedules;\r\ncreate policy \"Anyone reads approved schedules\" on public.collection_schedules\r\n  for select to anon, authenticated\r\n  using (approved = true);\r\n\r\ndrop policy if exists \"Admins read all schedules\" on public.collection_schedules;\r\ncreate policy \"Admins read all schedules\" on public.collection_schedules\r\n  for select to authenticated\r\n  using (public.is_operations_admin());\r\n\r\ndrop policy if exists \"Admins write schedules\" on public.collection_schedules;\r\ncreate policy \"Admins write schedules\" on public.collection_schedules\r\n  for all to authenticated\r\n  using (public.is_operations_admin())\r\n  with check (public.is_operations_admin());\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- E. AI invoice-scan audit trail\r\n-- ---------------------------------------------------------------------------\r\n-- Delivery notes can be prefilled by scanning an invoice. What the model read is\r\n-- recorded so a mis-keyed delivery note can be traced back to its source.\r\n\r\ncreate table if not exists public.invoice_scans (\r\n  id uuid primary key default gen_random_uuid(),\r\n  scanned_by uuid not null references auth.users(id) on delete restrict default auth.uid(),\r\n  shipment_id uuid references public.shipments(id) on delete set null,\r\n  storage_path text,\r\n  extracted jsonb not null default '{}'::jsonb,\r\n  model text,\r\n  confidence text,\r\n  accepted boolean not null default false,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\nalter table public.invoice_scans enable row level security;\r\n\r\n-- is_operations_admin() rather than is_staff_member(): the latter is defined in\r\n-- 20260808_restrict_public_shipment_reads.sql, which is applied separately and\r\n-- deliberately later, so depending on it here would make the order matter.\r\ndrop policy if exists \"Staff manage invoice scans\" on public.invoice_scans;\r\ncreate policy \"Staff manage invoice scans\" on public.invoice_scans\r\n  for all to authenticated\r\n  using (public.is_operations_admin())\r\n  with check (public.is_operations_admin());\r\n\n\n-- Every clocked-in driver sees the whole of today's active collection route.\r\n--\r\n-- Only one collection route runs per day, so per-driver stop assignment is\r\n-- unnecessary overhead: if the London route is active, every driver on shift\r\n-- needs the same list of addresses and can pick the nearest.\r\n--\r\n-- NOTE: applied to the live DB via the staff-ops edge function's \"setup\"\r\n-- action (migration history is out of sync — never `db push`).\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Read a free-text pickup_date as a real date\r\n-- ---------------------------------------------------------------------------\r\n-- Live data is written in ordinal form (\"August 5th, 2026\"), which Postgres\r\n-- cannot cast — the \"th\" makes it invalid input. Some rows are prose\r\n-- (\"To be confirmed\", \"Not set\"), so this must never raise.\r\n\r\ncreate or replace function public.parse_schedule_date(p_text text)\r\nreturns date\r\nlanguage plpgsql\r\nimmutable\r\nas $$\r\ndeclare v_clean text;\r\nbegin\r\n  if p_text is null or btrim(p_text) = '' then return null; end if;\r\n  v_clean := regexp_replace(p_text, '(\\d+)(st|nd|rd|th)', '\\1', 'gi');\r\n  begin\r\n    return v_clean::date;\r\n  exception when others then\r\n    return null;\r\n  end;\r\nend $$;\r\n\r\ngrant execute on function public.parse_schedule_date(text) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. Which route is running today\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.active_collection_routes(p_date date default null)\r\nreturns table (schedule_id uuid, route text, country text, pickup_date text)\r\nlanguage sql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\n  select s.id, s.route, s.country, s.pickup_date\r\n  from public.collection_schedules s\r\n  where coalesce(s.approved, true)\r\n    and public.parse_schedule_date(s.pickup_date) = coalesce(p_date, current_date);\r\n$$;\r\n\r\ngrant execute on function public.active_collection_routes(date) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. The collections a driver should see today\r\n-- ---------------------------------------------------------------------------\r\n-- Cached pickup coordinates, declared before the function that reads them so\r\n-- the column exists no matter how this file is split or re-run.\r\n\r\nalter table public.shipments\r\n  add column if not exists pickup_latitude double precision,\r\n  add column if not exists pickup_longitude double precision;\r\n\r\n-- Returns every shipment still awaiting collection on today's active route,\r\n-- regardless of whether anyone was assigned to it. A shipment is matched either\r\n-- by its linked schedule id or by the route name recorded at booking, because\r\n-- website bookings store the route as text and only sometimes link the schedule.\r\n--\r\n-- Coordinates are returned when known; the app resolves the rest from the\r\n-- postcode. Anything the driver needs to do the job is included, and nothing\r\n-- else: no pricing, no invoice data.\r\n\r\ncreate or replace function public.driver_route_collections(p_date date default null)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_is_staff boolean;\r\n  v_day date := coalesce(p_date, current_date);\r\n  v_routes jsonb;\r\n  v_stops jsonb;\r\nbegin\r\n  if v_uid is null then raise exception 'Sign in to view collections'; end if;\r\n\r\n  -- Drivers, dispatchers, logistics and admins may all see the day's route.\r\n  select exists (\r\n    select 1 from public.profiles\r\n    where id = v_uid\r\n      and (is_admin = true\r\n           or lower(coalesce(role, '')) in ('driver', 'dispatcher', 'logistics', 'admin'))\r\n  ) into v_is_staff;\r\n  if not v_is_staff then raise exception 'Driver or dispatch access required'; end if;\r\n\r\n  select coalesce(jsonb_agg(jsonb_build_object(\r\n           'scheduleId', r.schedule_id, 'route', r.route,\r\n           'country', r.country, 'pickupDate', r.pickup_date)), '[]'::jsonb)\r\n    into v_routes\r\n  from public.active_collection_routes(v_day) r;\r\n\r\n  select coalesce(jsonb_agg(x order by x->>'customerName'), '[]'::jsonb) into v_stops\r\n  from (\r\n    select jsonb_build_object(\r\n      'shipmentId', s.id,\r\n      'trackingNumber', s.tracking_number,\r\n      'customerReference', s.customer_reference,\r\n      'customerName', trim(coalesce(s.metadata->'sender'->>'firstName', '') || ' ' ||\r\n                           coalesce(s.metadata->'sender'->>'lastName', '')),\r\n      'phone', s.metadata->'sender'->>'phone',\r\n      'address', s.metadata->'sender'->>'address',\r\n      'city', coalesce(s.metadata->'sender'->>'city', ''),\r\n      -- Website bookings use 'postcode'; the app writes 'postalCode'.\r\n      'postcode', coalesce(s.metadata->'sender'->>'postcode', s.metadata->'sender'->>'postalCode', ''),\r\n      'route', s.metadata->'collection'->>'route',\r\n      'goodsDescription', left(coalesce(s.goods_description, ''), 400),\r\n      'collectionStatus', s.collection_status,\r\n      -- A planned stop's coordinates win; otherwise use the point cached on the\r\n      -- shipment by whichever driver resolved its postcode first.\r\n      'latitude', coalesce(st.latitude, s.pickup_latitude),\r\n      'longitude', coalesce(st.longitude, s.pickup_longitude),\r\n      'stopId', st.id\r\n    ) as x\r\n    from public.shipments s\r\n    -- A stop row may already exist (and carry coordinates) if a run was planned.\r\n    left join public.driver_run_stops st\r\n      on st.shipment_id = s.id and st.stop_type = 'collection'\r\n    where s.deleted_at is null\r\n      and coalesce(s.collection_status, 'Awaiting Collection') <> 'Collected'\r\n      and (\r\n        s.collection_schedule_id in (select schedule_id from public.active_collection_routes(v_day))\r\n        or upper(coalesce(s.metadata->'collection'->>'route', '')) in (\r\n             select upper(route) from public.active_collection_routes(v_day))\r\n        -- Route names are stored both with and without the \" ROUTE\" suffix.\r\n        or upper(coalesce(s.metadata->'collection'->>'route', '')) || ' ROUTE' in (\r\n             select upper(route) from public.active_collection_routes(v_day))\r\n        or upper(coalesce(s.metadata->'collection'->>'route', '')) in (\r\n             select upper(replace(route, ' ROUTE', '')) from public.active_collection_routes(v_day))\r\n      )\r\n  ) sub;\r\n\r\n  return jsonb_build_object('date', v_day, 'routes', v_routes, 'collections', v_stops);\r\nend $$;\r\n\r\ngrant execute on function public.driver_route_collections(date) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Cache resolved pickup coordinates on the shipment\r\n-- ---------------------------------------------------------------------------\r\n-- The app resolves a collection's postcode to a point once and stores it, so\r\n-- every driver on the route reuses the same lookup instead of each of them\r\n-- hitting the free geocoder for the same 60 addresses. (Columns are declared in\r\n-- section C, above the function that reads them.)\r\n\r\ncreate or replace function public.set_shipment_pickup_point(\r\n  p_shipment_id uuid,\r\n  p_latitude double precision,\r\n  p_longitude double precision\r\n)\r\nreturns void\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\nbegin\r\n  if auth.uid() is null then raise exception 'Sign in required'; end if;\r\n  if not exists (\r\n    select 1 from public.profiles\r\n    where id = auth.uid()\r\n      and (is_admin = true\r\n           or lower(coalesce(role, '')) in ('driver', 'dispatcher', 'logistics', 'admin'))\r\n  ) then\r\n    raise exception 'Driver or dispatch access required';\r\n  end if;\r\n  if p_latitude is null or p_longitude is null then return; end if;\r\n  -- Guard against a bad geocode writing nonsense onto the shipment.\r\n  if p_latitude < -90 or p_latitude > 90 or p_longitude < -180 or p_longitude > 180 then\r\n    raise exception 'Coordinates out of range';\r\n  end if;\r\n\r\n  update public.shipments\r\n     set pickup_latitude = p_latitude, pickup_longitude = p_longitude\r\n   where id = p_shipment_id;\r\nend $$;\r\n\r\ngrant execute on function public.set_shipment_pickup_point(uuid, double precision, double precision) to authenticated;\r\n\n\n-- Shared driver collection operations.\r\n--\r\n-- The route is visible to every clocked-in driver, but a shipment can only be\r\n-- worked by one driver at a time. Claims bridge that shared route to the\r\n-- existing driver_run_stops proof/invoice/handover workflow.\r\n\r\ncreate table if not exists public.route_collection_claims (\r\n  id uuid primary key default gen_random_uuid(),\r\n  shipment_id uuid not null unique references public.shipments(id) on delete cascade,\r\n  schedule_id uuid references public.collection_schedules(id) on delete set null,\r\n  driver_id uuid references auth.users(id) on delete set null,\r\n  stop_id uuid references public.driver_run_stops(id) on delete set null,\r\n  claim_date date not null default current_date,\r\n  status text not null default 'available'\r\n    check (status in ('available', 'claimed', 'en_route', 'arrived', 'completed', 'failed', 'released')),\r\n  claimed_at timestamptz,\r\n  en_route_at timestamptz,\r\n  arrived_at timestamptz,\r\n  completed_at timestamptz,\r\n  released_at timestamptz,\r\n  issue_reason text,\r\n  issue_note text,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists route_collection_claims_date_status_idx\r\n  on public.route_collection_claims(claim_date, status);\r\ncreate index if not exists route_collection_claims_driver_idx\r\n  on public.route_collection_claims(driver_id, claim_date);\r\n\r\nalter table public.route_collection_claims enable row level security;\r\n\r\ndrop policy if exists \"Operations staff view route claims\" on public.route_collection_claims;\r\ncreate policy \"Operations staff view route claims\" on public.route_collection_claims\r\n  for select to authenticated using (\r\n    exists (\r\n      select 1 from public.profiles p where p.id = auth.uid()\r\n        and (p.is_admin = true or lower(coalesce(p.role, '')) in ('admin', 'driver', 'dispatcher', 'logistics', 'finance'))\r\n    )\r\n  );\r\n\r\ndrop policy if exists \"Admins manage route claims\" on public.route_collection_claims;\r\ncreate policy \"Admins manage route claims\" on public.route_collection_claims\r\n  for all to authenticated\r\n  using (exists (select 1 from public.profiles p where p.id = auth.uid() and (p.is_admin = true or lower(coalesce(p.role, '')) in ('admin', 'dispatcher', 'logistics'))))\r\n  with check (exists (select 1 from public.profiles p where p.id = auth.uid() and (p.is_admin = true or lower(coalesce(p.role, '')) in ('admin', 'dispatcher', 'logistics'))));\r\n\r\ncreate or replace function public.claim_route_collection(p_shipment_id uuid)\r\nreturns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_ship public.shipments%rowtype;\r\n  v_claim public.route_collection_claims%rowtype;\r\n  v_run public.driver_runs%rowtype;\r\n  v_stop public.driver_run_stops%rowtype;\r\n  v_order integer;\r\n  v_route text;\r\n  v_address text;\r\n  v_name text;\r\nbegin\r\n  if v_uid is null then raise exception 'Sign in required'; end if;\r\n  if not exists (\r\n    select 1 from public.profiles p where p.id = v_uid\r\n      and coalesce(p.staff_active, true)\r\n      and (p.is_admin = true or lower(coalesce(p.role, '')) in ('driver', 'admin', 'dispatcher', 'logistics'))\r\n  ) then raise exception 'Active driver access required'; end if;\r\n\r\n  if not exists (\r\n    select 1 from public.driver_attendance a\r\n    where a.driver_id = v_uid and a.work_date = current_date and a.clocked_out_at is null\r\n  ) and not exists (\r\n    select 1 from public.profiles p where p.id = v_uid\r\n      and (p.is_admin = true or lower(coalesce(p.role, '')) in ('admin', 'dispatcher', 'logistics'))\r\n  ) then raise exception 'Clock in before claiming a collection'; end if;\r\n\r\n  select * into v_ship from public.shipments where id = p_shipment_id and deleted_at is null for update;\r\n  if not found then raise exception 'Shipment not found'; end if;\r\n  if coalesce(v_ship.collection_status, 'Awaiting Collection') = 'Collected' then\r\n    raise exception 'This shipment has already been collected';\r\n  end if;\r\n  if not (\r\n    v_ship.collection_schedule_id in (select schedule_id from public.active_collection_routes(current_date))\r\n    or upper(coalesce(v_ship.metadata->'collection'->>'route', '')) in (select upper(route) from public.active_collection_routes(current_date))\r\n    or upper(coalesce(v_ship.metadata->'collection'->>'route', '')) || ' ROUTE' in (select upper(route) from public.active_collection_routes(current_date))\r\n    or upper(coalesce(v_ship.metadata->'collection'->>'route', '')) in (select upper(replace(route, ' ROUTE', '')) from public.active_collection_routes(current_date))\r\n  ) then raise exception 'This shipment is not on today''s active collection route'; end if;\r\n\r\n  select * into v_claim from public.route_collection_claims where shipment_id = p_shipment_id for update;\r\n  if found and v_claim.status in ('claimed', 'en_route', 'arrived') and v_claim.driver_id <> v_uid then\r\n    select coalesce(p.full_name, 'Another driver') into v_name from public.profiles p where p.id = v_claim.driver_id;\r\n    raise exception '% is already working this collection', coalesce(v_name, 'Another driver');\r\n  end if;\r\n  if found and v_claim.driver_id = v_uid and v_claim.status in ('claimed', 'en_route', 'arrived') and v_claim.stop_id is not null then\r\n    return jsonb_build_object('claimId', v_claim.id, 'stopId', v_claim.stop_id, 'shipmentId', p_shipment_id, 'status', v_claim.status);\r\n  end if;\r\n\r\n  v_route := coalesce(v_ship.metadata->'collection'->>'route', 'Collection route');\r\n  v_address := concat_ws(', ', nullif(v_ship.metadata->'sender'->>'address', ''), nullif(v_ship.metadata->'sender'->>'city', ''),\r\n    nullif(coalesce(v_ship.metadata->'sender'->>'postcode', v_ship.metadata->'sender'->>'postalCode'), ''));\r\n\r\n  insert into public.driver_runs(driver_id, run_date, status, run_type, route_name, started_at)\r\n  values (v_uid, current_date, 'active', 'pickup', v_route, now())\r\n  on conflict(driver_id, run_date) do update set\r\n    status = 'active', run_type = 'pickup', route_name = coalesce(public.driver_runs.route_name, excluded.route_name),\r\n    started_at = coalesce(public.driver_runs.started_at, now()), completed_at = null, updated_at = now()\r\n  returning * into v_run;\r\n\r\n  select * into v_stop from public.driver_run_stops\r\n   where run_id = v_run.id and shipment_id = p_shipment_id limit 1 for update;\r\n  if found then\r\n    update public.driver_run_stops set status = 'planned', failure_reason = null, failure_note = null,\r\n      failed_at = null, en_route_at = null, arrived_at = null, completed_at = null, updated_at = now()\r\n    where id = v_stop.id returning * into v_stop;\r\n  else\r\n    select coalesce(max(stop_order), 0) + 1 into v_order from public.driver_run_stops where run_id = v_run.id;\r\n    insert into public.driver_run_stops(run_id, shipment_id, stop_order, stop_type, status, address,\r\n      latitude, longitude)\r\n    values (v_run.id, p_shipment_id, v_order, 'collection', 'planned', v_address,\r\n      v_ship.pickup_latitude, v_ship.pickup_longitude)\r\n    returning * into v_stop;\r\n  end if;\r\n\r\n  insert into public.route_collection_claims(shipment_id, schedule_id, driver_id, stop_id, claim_date, status, claimed_at, updated_at)\r\n  values (p_shipment_id, v_ship.collection_schedule_id, v_uid, v_stop.id, current_date, 'claimed', now(), now())\r\n  on conflict(shipment_id) do update set schedule_id = excluded.schedule_id, driver_id = excluded.driver_id,\r\n    stop_id = excluded.stop_id, claim_date = excluded.claim_date, status = 'claimed', claimed_at = now(),\r\n    en_route_at = null, arrived_at = null, completed_at = null, released_at = null,\r\n    issue_reason = null, issue_note = null, updated_at = now()\r\n  returning * into v_claim;\r\n\r\n  update public.shipments set assigned_driver_id = v_uid, driver_status = 'claimed', updated_at = now(),\r\n    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('driverUpdate', jsonb_build_object(\r\n      'status', 'claimed', 'driverId', v_uid, 'stopId', v_stop.id, 'updatedAt', now()))\r\n  where id = p_shipment_id;\r\n\r\n  insert into public.shipment_events(shipment_id, event_type, previous_status, new_status, actor_id, details)\r\n  values (p_shipment_id, 'collection_claimed', v_ship.driver_status, 'claimed', v_uid,\r\n    jsonb_build_object('claimId', v_claim.id, 'runId', v_run.id, 'stopId', v_stop.id));\r\n\r\n  return jsonb_build_object('claimId', v_claim.id, 'stopId', v_stop.id, 'shipmentId', p_shipment_id, 'status', 'claimed');\r\nend;\r\n$$;\r\n\r\ncreate or replace function public.release_route_collection(p_shipment_id uuid, p_reason text default null)\r\nreturns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_claim public.route_collection_claims%rowtype;\r\nbegin\r\n  select * into v_claim from public.route_collection_claims where shipment_id = p_shipment_id for update;\r\n  if not found then raise exception 'Collection claim not found'; end if;\r\n  if v_claim.driver_id <> auth.uid() and not exists (\r\n    select 1 from public.profiles p where p.id = auth.uid() and (p.is_admin = true or lower(coalesce(p.role, '')) in ('admin', 'dispatcher', 'logistics'))\r\n  ) then raise exception 'Only the assigned driver or dispatch can release this collection'; end if;\r\n  if v_claim.status not in ('claimed', 'en_route') then raise exception 'This collection can no longer be released'; end if;\r\n\r\n  update public.route_collection_claims set status = 'released', released_at = now(), issue_reason = p_reason, updated_at = now()\r\n    where id = v_claim.id;\r\n  update public.driver_run_stops set status = 'failed', failure_reason = 'released', failure_note = p_reason,\r\n    failed_at = now(), updated_at = now() where id = v_claim.stop_id;\r\n  update public.shipments set assigned_driver_id = null, driver_status = 'available', updated_at = now() where id = p_shipment_id;\r\n  insert into public.shipment_events(shipment_id, event_type, previous_status, new_status, actor_id, details)\r\n    values (p_shipment_id, 'collection_released', v_claim.status, 'released', auth.uid(), jsonb_build_object('reason', p_reason));\r\n  return jsonb_build_object('shipmentId', p_shipment_id, 'status', 'released');\r\nend $$;\r\n\r\ncreate or replace function public.sync_route_collection_claim()\r\nreturns trigger language plpgsql security definer set search_path = public as $$\r\ndeclare v_status text;\r\nbegin\r\n  if new.stop_type <> 'collection' then return new; end if;\r\n  v_status := case new.status when 'planned' then 'claimed' else new.status end;\r\n  update public.route_collection_claims set status = v_status,\r\n    en_route_at = case when v_status = 'en_route' then coalesce(en_route_at, now()) else en_route_at end,\r\n    arrived_at = case when v_status = 'arrived' then coalesce(arrived_at, now()) else arrived_at end,\r\n    completed_at = case when v_status = 'completed' then coalesce(completed_at, now()) else completed_at end,\r\n    issue_reason = case when v_status = 'failed' then new.failure_reason else issue_reason end,\r\n    issue_note = case when v_status = 'failed' then new.failure_note else issue_note end,\r\n    updated_at = now()\r\n  where stop_id = new.id and status <> 'released';\r\n  return new;\r\nend $$;\r\n\r\ndrop trigger if exists sync_route_collection_claim_after_stop on public.driver_run_stops;\r\ncreate trigger sync_route_collection_claim_after_stop after update of status on public.driver_run_stops\r\nfor each row execute function public.sync_route_collection_claim();\r\n\r\ngrant execute on function public.claim_route_collection(uuid) to authenticated;\r\ngrant execute on function public.release_route_collection(uuid, text) to authenticated;\r\n\r\n-- Extend the shared route payload with the claim owner and lifecycle. The app\r\n-- can now distinguish available work, the current driver's work, and work\r\n-- already being handled by a colleague.\r\ncreate or replace function public.driver_route_collections(p_date date default null)\r\nreturns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_uid uuid := auth.uid(); v_day date := coalesce(p_date,current_date); v_routes jsonb; v_stops jsonb;\r\nbegin\r\n  if v_uid is null then raise exception 'Sign in to view collections'; end if;\r\n  if not exists (select 1 from public.profiles p where p.id=v_uid and\r\n    (p.is_admin=true or lower(coalesce(p.role,'')) in ('driver','dispatcher','logistics','admin','finance')))\r\n  then raise exception 'Driver or operations access required'; end if;\r\n\r\n  select coalesce(jsonb_agg(jsonb_build_object('scheduleId',r.schedule_id,'route',r.route,\r\n    'country',r.country,'pickupDate',r.pickup_date)),'[]'::jsonb) into v_routes\r\n  from public.active_collection_routes(v_day) r;\r\n\r\n  select coalesce(jsonb_agg(x order by\r\n    case x->>'claimStatus' when 'arrived' then 0 when 'en_route' then 1 when 'claimed' then 2 else 3 end,\r\n    x->>'customerName'),'[]'::jsonb) into v_stops\r\n  from (\r\n    select jsonb_build_object(\r\n      'shipmentId',s.id,'trackingNumber',s.tracking_number,'customerReference',s.customer_reference,\r\n      'customerName',trim(coalesce(s.metadata->'sender'->>'firstName','')||' '||coalesce(s.metadata->'sender'->>'lastName','')),\r\n      'phone',s.metadata->'sender'->>'phone','address',s.metadata->'sender'->>'address',\r\n      'city',coalesce(s.metadata->'sender'->>'city',''),\r\n      'postcode',coalesce(s.metadata->'sender'->>'postcode',s.metadata->'sender'->>'postalCode',''),\r\n      'route',s.metadata->'collection'->>'route','goodsDescription',left(coalesce(s.goods_description,''),400),\r\n      'collectionStatus',s.collection_status,'latitude',coalesce(st.latitude,s.pickup_latitude),\r\n      'longitude',coalesce(st.longitude,s.pickup_longitude),'stopId',coalesce(c.stop_id,st.id),\r\n      'claimId',c.id,'claimStatus',coalesce(c.status,'available'),'claimedBy',c.driver_id,\r\n      'claimedByName',p.full_name,'claimedAt',c.claimed_at\r\n    ) x\r\n    from public.shipments s\r\n    left join public.route_collection_claims c on c.shipment_id=s.id\r\n    left join public.driver_run_stops st on st.id=c.stop_id\r\n    left join public.profiles p on p.id=c.driver_id\r\n    where s.deleted_at is null\r\n      and (s.collection_schedule_id in (select schedule_id from public.active_collection_routes(v_day))\r\n        or upper(coalesce(s.metadata->'collection'->>'route','')) in (select upper(route) from public.active_collection_routes(v_day))\r\n        or upper(coalesce(s.metadata->'collection'->>'route',''))||' ROUTE' in (select upper(route) from public.active_collection_routes(v_day))\r\n        or upper(coalesce(s.metadata->'collection'->>'route','')) in (select upper(replace(route,' ROUTE','')) from public.active_collection_routes(v_day)))\r\n  ) q;\r\n  return jsonb_build_object('date',v_day,'routes',v_routes,'collections',v_stops);\r\nend $$;\r\ngrant execute on function public.driver_route_collections(date) to authenticated;\r\n\r\n-- Dispatch messages: recipient_id is used for direct messages; a null recipient\r\n-- with audience_role='driver' is a route-wide announcement.\r\ncreate table if not exists public.staff_messages (\r\n  id uuid primary key default gen_random_uuid(),\r\n  sender_id uuid not null references auth.users(id) on delete cascade default auth.uid(),\r\n  recipient_id uuid references auth.users(id) on delete cascade,\r\n  audience_role text not null default 'driver' check (audience_role in ('driver', 'dispatch')),\r\n  shipment_id uuid references public.shipments(id) on delete set null,\r\n  subject text,\r\n  body text not null check (char_length(body) between 1 and 2000),\r\n  priority text not null default 'normal' check (priority in ('normal', 'urgent')),\r\n  read_at timestamptz,\r\n  created_at timestamptz not null default now()\r\n);\r\ncreate index if not exists staff_messages_recipient_created_idx on public.staff_messages(recipient_id, created_at desc);\r\nalter table public.staff_messages enable row level security;\r\n\r\ndrop policy if exists \"Staff read relevant messages\" on public.staff_messages;\r\ncreate policy \"Staff read relevant messages\" on public.staff_messages for select to authenticated using (\r\n  sender_id = auth.uid() or recipient_id = auth.uid()\r\n  or (recipient_id is null and audience_role = 'driver' and exists (select 1 from public.profiles p where p.id=auth.uid() and lower(coalesce(p.role,''))='driver'))\r\n  or exists (select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin=true or lower(coalesce(p.role,'')) in ('admin','dispatcher','logistics')))\r\n);\r\ndrop policy if exists \"Staff send messages\" on public.staff_messages;\r\ncreate policy \"Staff send messages\" on public.staff_messages for insert to authenticated with check (\r\n  sender_id = auth.uid() and exists (select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin=true or lower(coalesce(p.role,'')) in ('admin','driver','dispatcher','logistics')))\r\n);\r\ndrop policy if exists \"Recipients mark messages read\" on public.staff_messages;\r\ncreate policy \"Recipients mark messages read\" on public.staff_messages for update to authenticated\r\n  using (recipient_id = auth.uid()) with check (recipient_id = auth.uid());\r\n\r\ncreate or replace function public.driver_performance_summary(p_driver_id uuid default null, p_days integer default 30)\r\nreturns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_driver uuid := coalesce(p_driver_id, auth.uid()); v_result jsonb;\r\nbegin\r\n  if v_driver <> auth.uid() and not exists (\r\n    select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin=true or lower(coalesce(p.role,'')) in ('admin','dispatcher','logistics'))\r\n  ) then raise exception 'Performance access denied'; end if;\r\n  select jsonb_build_object(\r\n    'periodDays', greatest(1, least(coalesce(p_days,30),365)),\r\n    'claimed', count(*) filter (where c.claimed_at is not null),\r\n    'completed', count(*) filter (where c.status='completed'),\r\n    'issues', count(*) filter (where c.status='failed'),\r\n    'active', count(*) filter (where c.status in ('claimed','en_route','arrived')),\r\n    'successRate', case when count(*) filter (where c.status in ('completed','failed')) = 0 then 0 else\r\n      round(100.0 * count(*) filter (where c.status='completed') / count(*) filter (where c.status in ('completed','failed'))) end,\r\n    'averageMinutes', coalesce(round(avg(extract(epoch from (c.completed_at-c.claimed_at))/60) filter (where c.completed_at is not null)),0),\r\n    'daysWorked', (select count(*) from public.driver_attendance a where a.driver_id=v_driver and a.work_date >= current_date-greatest(1,least(coalesce(p_days,30),365)))\r\n  ) into v_result\r\n  from public.route_collection_claims c\r\n  where c.driver_id=v_driver and c.claim_date >= current_date-greatest(1,least(coalesce(p_days,30),365));\r\n  return v_result;\r\nend $$;\r\ngrant execute on function public.driver_performance_summary(uuid, integer) to authenticated;\r\n\r\ndo $$ begin alter publication supabase_realtime add table public.route_collection_claims; exception when duplicate_object then null; end $$;\r\ndo $$ begin alter publication supabase_realtime add table public.staff_messages; exception when duplicate_object then null; end $$;\r\n\n\n-- Production-pilot security hardening.\r\n--\r\n-- Keep customer, driver, operations and finance access separate; prevent\r\n-- self-service profile edits from becoming privilege escalation; and make\r\n-- sensitive finance changes auditable even if they originate outside the UI.\r\n\r\n-- Remove legacy policies that exposed whole tables to anonymous tracking.\r\n-- Public tracking now goes through get_shipment_tracking_info(), which returns\r\n-- a deliberately limited status payload.\r\ndrop policy if exists \"Allow tracking by tracking number\" on public.shipments;\r\ndrop policy if exists \"Allow public select from shipments\" on public.shipments;\r\ndrop policy if exists \"Allow public select from payments\" on public.payments;\r\ndrop policy if exists \"Allow public select from receipts\" on public.receipts;\r\n\r\ncreate or replace function public.is_full_admin()\r\nreturns boolean\r\nlanguage sql\r\nstable\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\n  select exists (\r\n    select 1 from public.profiles\r\n    where id = auth.uid()\r\n      and (is_admin = true or lower(coalesce(role, '')) = 'admin')\r\n  );\r\n$$;\r\nrevoke all on function public.is_full_admin() from public, anon;\r\ngrant execute on function public.is_full_admin() to authenticated;\r\n\r\n-- A customer may edit their own contact details, but never their staff role or\r\n-- operational state. Admin/service-role updates continue to work.\r\ncreate or replace function public.protect_profile_privileges()\r\nreturns trigger\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\nbegin\r\n  if auth.uid() is not null and not public.is_full_admin() then\r\n    new.role := old.role;\r\n    new.is_admin := old.is_admin;\r\n    new.staff_active := old.staff_active;\r\n    new.on_leave := old.on_leave;\r\n    new.driver_type := old.driver_type;\r\n  end if;\r\n  return new;\r\nend;\r\n$$;\r\n\r\ndrop trigger if exists protect_profile_privileges_before_update on public.profiles;\r\ncreate trigger protect_profile_privileges_before_update\r\nbefore update on public.profiles\r\nfor each row execute function public.protect_profile_privileges();\r\n\r\n-- Drivers only read shipments explicitly assigned to them. Shared-route\r\n-- discovery remains available through driver_route_collections(), which\r\n-- returns a deliberately limited payload.\r\ndrop policy if exists \"Customers read own shipments\" on public.shipments;\r\ncreate policy \"Customers read own shipments\" on public.shipments\r\n  for select to authenticated\r\n  using (\r\n    user_id = auth.uid()\r\n    or assigned_driver_id = auth.uid()\r\n    or public.is_operations_admin()\r\n    or public.is_finance_staff()\r\n  );\r\n\r\n-- Payment and receipt records are customer/finance data, not general staff\r\n-- data. Admins remain included through is_finance_staff().\r\ndrop policy if exists \"Customers read own payments\" on public.payments;\r\ncreate policy \"Customers read own payments\" on public.payments\r\n  for select to authenticated\r\n  using (\r\n    user_id = auth.uid()\r\n    or public.is_finance_staff()\r\n    or exists (\r\n      select 1 from public.shipments s\r\n      where s.id = shipment_id and s.user_id = auth.uid()\r\n    )\r\n  );\r\n\r\ndrop policy if exists \"Customers read own receipts\" on public.receipts;\r\ncreate policy \"Customers read own receipts\" on public.receipts\r\n  for select to authenticated\r\n  using (\r\n    user_id = auth.uid()\r\n    or public.is_finance_staff()\r\n    or exists (\r\n      select 1 from public.shipments s\r\n      where s.id = shipment_id and s.user_id = auth.uid()\r\n    )\r\n  );\r\n\r\ndrop policy if exists \"Customers view own payment proofs\" on public.payment_proofs;\r\ncreate policy \"Customers view own payment proofs\" on public.payment_proofs\r\n  for select to authenticated\r\n  using (user_id = auth.uid() or public.is_finance_staff());\r\n\r\n-- Proof decisions must use review_payment_proof(), which creates the payment,\r\n-- audit entry and customer notification atomically.\r\ndrop policy if exists \"Finance reviews payment proofs\" on public.payment_proofs;\r\n\r\ndrop policy if exists \"Customers and finance read payment proof\" on storage.objects;\r\ncreate policy \"Customers and finance read payment proof\" on storage.objects\r\n  for select to authenticated\r\n  using (\r\n    bucket_id = 'payment-proofs'\r\n    and ((storage.foldername(name))[1] = auth.uid()::text or public.is_finance_staff())\r\n  );\r\n\r\n-- Finance can prepare recorded expenses. Only operations admins can approve or\r\n-- reject them through approve_finance_expense().\r\ndrop policy if exists \"Finance manages expenses\" on public.finance_expenses;\r\ndrop policy if exists \"Finance views expenses\" on public.finance_expenses;\r\ndrop policy if exists \"Finance creates recorded expenses\" on public.finance_expenses;\r\ndrop policy if exists \"Finance edits recorded expenses\" on public.finance_expenses;\r\ndrop policy if exists \"Finance deletes recorded expenses\" on public.finance_expenses;\r\ndrop policy if exists \"Admins manage expenses\" on public.finance_expenses;\r\n\r\ncreate policy \"Finance views expenses\" on public.finance_expenses\r\n  for select to authenticated using (public.is_finance_staff());\r\ncreate policy \"Finance creates recorded expenses\" on public.finance_expenses\r\n  for insert to authenticated\r\n  with check (public.is_finance_staff() and status = 'recorded' and approved_by is null);\r\ncreate policy \"Finance edits recorded expenses\" on public.finance_expenses\r\n  for update to authenticated\r\n  using (public.is_finance_staff() and status = 'recorded')\r\n  with check (public.is_finance_staff() and status = 'recorded' and approved_by is null);\r\ncreate policy \"Finance deletes recorded expenses\" on public.finance_expenses\r\n  for delete to authenticated\r\n  using (public.is_finance_staff() and status = 'recorded');\r\ncreate policy \"Admins manage expenses\" on public.finance_expenses\r\n  for all to authenticated\r\n  using (public.is_full_admin())\r\n  with check (public.is_full_admin());\r\n\r\ncreate or replace function public.approve_finance_expense(\r\n  p_expense_id uuid,\r\n  p_approved boolean,\r\n  p_notes text default null\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare v_expense public.finance_expenses%rowtype;\r\nbegin\r\n  if not public.is_full_admin() then raise exception 'Full admin approval required'; end if;\r\n  update public.finance_expenses set\r\n    status = case when p_approved then 'approved' else 'rejected' end,\r\n    approved_by = auth.uid(), updated_at = now()\r\n  where id = p_expense_id and status = 'recorded'\r\n  returning * into v_expense;\r\n  if not found then raise exception 'Recorded expense not found'; end if;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), case when p_approved then 'APPROVE' else 'REJECT' end,\r\n    'EXPENSE', p_expense_id,\r\n    jsonb_build_object('amount', v_expense.amount, 'currency', v_expense.currency, 'notes', p_notes));\r\n  return to_jsonb(v_expense);\r\nend;\r\n$$;\r\nrevoke all on function public.approve_finance_expense(uuid, boolean, text) from public, anon;\r\ngrant execute on function public.approve_finance_expense(uuid, boolean, text) to authenticated;\r\n\r\n-- Finance does not need the operational claim table itself. It receives the\r\n-- linked, limited invoice summaries through finance RPCs.\r\ndrop policy if exists \"Operations staff view route claims\" on public.route_collection_claims;\r\ncreate policy \"Operations staff view route claims\" on public.route_collection_claims\r\n  for select to authenticated using (\r\n    exists (\r\n      select 1 from public.profiles p where p.id = auth.uid()\r\n        and (p.is_admin = true or lower(coalesce(p.role, '')) in ('admin', 'driver', 'dispatcher', 'logistics'))\r\n    )\r\n  );\r\n\r\n-- Record receipt separately from reconciliation. This avoids a single tap\r\n-- claiming both that money arrived and that it was independently matched.\r\ncreate or replace function public.mark_payment_received(\r\n  p_payment_id uuid,\r\n  p_notes text default null\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare v_payment public.payments%rowtype;\r\nbegin\r\n  if not public.is_finance_staff() then raise exception 'Finance access required'; end if;\r\n\r\n  select * into v_payment from public.payments where id = p_payment_id for update;\r\n  if not found then raise exception 'Payment not found'; end if;\r\n  if coalesce(v_payment.amount, 0) <= 0 then raise exception 'Payment amount must be greater than zero'; end if;\r\n\r\n  update public.payments set\r\n    payment_status = 'paid',\r\n    finance_notes = coalesce(nullif(trim(p_notes), ''), finance_notes),\r\n    updated_at = now()\r\n  where id = p_payment_id\r\n  returning * into v_payment;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'MARK_RECEIVED', 'PAYMENT', p_payment_id,\r\n    jsonb_build_object('amount', v_payment.amount, 'currency', v_payment.currency,\r\n      'reference', v_payment.transaction_id, 'notes', p_notes));\r\n\r\n  return jsonb_build_object('paymentId', v_payment.id, 'status', v_payment.payment_status,\r\n    'reconciled', v_payment.reconciled_at is not null);\r\nend;\r\n$$;\r\n\r\nrevoke all on function public.mark_payment_received(uuid, text) from public, anon;\r\ngrant execute on function public.mark_payment_received(uuid, text) to authenticated;\r\n\r\n-- Reconciliation is only valid after receipt has been recorded.\r\ncreate or replace function public.set_payment_reconciled(\r\n  p_payment_id uuid,\r\n  p_reconciled boolean,\r\n  p_notes text default null\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare v_payment public.payments%rowtype;\r\nbegin\r\n  if not public.is_finance_staff() then raise exception 'Finance access required'; end if;\r\n\r\n  select * into v_payment from public.payments where id = p_payment_id for update;\r\n  if not found then raise exception 'Payment not found'; end if;\r\n  if p_reconciled and lower(coalesce(v_payment.payment_status, '')) not in ('completed', 'paid', 'success', 'succeeded') then\r\n    raise exception 'Record the payment as received before reconciliation';\r\n  end if;\r\n\r\n  update public.payments set\r\n    reconciled_at = case when p_reconciled then now() else null end,\r\n    reconciled_by = case when p_reconciled then auth.uid() else null end,\r\n    finance_notes = coalesce(nullif(trim(p_notes), ''), finance_notes)\r\n  where id = p_payment_id\r\n  returning * into v_payment;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), case when p_reconciled then 'RECONCILE' else 'UNRECONCILE' end,\r\n    'PAYMENT', p_payment_id, jsonb_build_object('reconciled', p_reconciled,\r\n      'notes', p_notes, 'amount', v_payment.amount, 'currency', v_payment.currency));\r\n\r\n  return jsonb_build_object('paymentId', v_payment.id,\r\n    'reconciled', v_payment.reconciled_at is not null,\r\n    'reconciledAt', v_payment.reconciled_at);\r\nend;\r\n$$;\r\n\r\nrevoke all on function public.set_payment_reconciled(uuid, boolean, text) from public, anon;\r\ngrant execute on function public.set_payment_reconciled(uuid, boolean, text) to authenticated;\r\n\r\n-- Backstop audit trail for sensitive direct table changes. RPC-level audit\r\n-- entries remain more descriptive; these records catch console/API writes too.\r\ncreate or replace function public.audit_sensitive_mutation()\r\nreturns trigger\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_old jsonb := case when tg_op = 'INSERT' then '{}'::jsonb else to_jsonb(old) end;\r\n  v_new jsonb := case when tg_op = 'DELETE' then '{}'::jsonb else to_jsonb(new) end;\r\n  v_id uuid := coalesce(nullif(v_new->>'id', '')::uuid, nullif(v_old->>'id', '')::uuid);\r\n  v_details jsonb;\r\nbegin\r\n  if tg_table_name = 'profiles' then\r\n    v_details := jsonb_build_object(\r\n      'oldRole', v_old->>'role', 'newRole', v_new->>'role',\r\n      'oldAdmin', v_old->>'is_admin', 'newAdmin', v_new->>'is_admin',\r\n      'oldActive', v_old->>'staff_active', 'newActive', v_new->>'staff_active');\r\n  elsif tg_table_name = 'payments' then\r\n    v_details := jsonb_build_object(\r\n      'oldStatus', v_old->>'payment_status', 'newStatus', v_new->>'payment_status',\r\n      'oldAmount', v_old->>'amount', 'newAmount', v_new->>'amount',\r\n      'currency', coalesce(v_new->>'currency', v_old->>'currency'),\r\n      'oldReconciledAt', v_old->>'reconciled_at', 'newReconciledAt', v_new->>'reconciled_at');\r\n  elsif tg_table_name = 'finance_expenses' then\r\n    v_details := jsonb_build_object(\r\n      'oldStatus', v_old->>'status', 'newStatus', v_new->>'status',\r\n      'oldAmount', v_old->>'amount', 'newAmount', v_new->>'amount',\r\n      'category', coalesce(v_new->>'category', v_old->>'category'));\r\n  else\r\n    v_details := jsonb_build_object(\r\n      'oldStatus', v_old->>'status', 'newStatus', v_new->>'status',\r\n      'amount', coalesce(v_new->>'amount', v_old->>'amount'),\r\n      'currency', coalesce(v_new->>'currency', v_old->>'currency'));\r\n  end if;\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'DB_' || tg_op, upper(tg_table_name), v_id, v_details);\r\n  if tg_op = 'DELETE' then return old; end if;\r\n  return new;\r\nend;\r\n$$;\r\n\r\ndrop trigger if exists audit_payments_mutation on public.payments;\r\ncreate trigger audit_payments_mutation after insert or update or delete on public.payments\r\nfor each row execute function public.audit_sensitive_mutation();\r\ndrop trigger if exists audit_finance_expenses_mutation on public.finance_expenses;\r\ncreate trigger audit_finance_expenses_mutation after insert or update or delete on public.finance_expenses\r\nfor each row execute function public.audit_sensitive_mutation();\r\ndrop trigger if exists audit_payment_proofs_mutation on public.payment_proofs;\r\ncreate trigger audit_payment_proofs_mutation after insert or update or delete on public.payment_proofs\r\nfor each row execute function public.audit_sensitive_mutation();\r\ndrop trigger if exists audit_profiles_privilege_mutation on public.profiles;\r\ncreate trigger audit_profiles_privilege_mutation\r\nafter update of role, is_admin, staff_active, on_leave, driver_type on public.profiles\r\nfor each row execute function public.audit_sensitive_mutation();\r\n\n\n-- One current location per driver for the shared collections map.\r\n-- This is deliberately not a tracking history: every update replaces the\r\n-- previous point, limiting the amount of sensitive location data retained.\r\n\r\ncreate table if not exists public.driver_live_locations (\r\n  driver_id uuid primary key references public.profiles(id) on delete cascade,\r\n  latitude double precision not null check (latitude between -90 and 90),\r\n  longitude double precision not null check (longitude between -180 and 180),\r\n  accuracy_m double precision null check (accuracy_m is null or accuracy_m >= 0),\r\n  recorded_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\nalter table public.driver_live_locations enable row level security;\r\n\r\ndrop policy if exists \"Drivers read own live location\" on public.driver_live_locations;\r\ncreate policy \"Drivers read own live location\" on public.driver_live_locations\r\n  for select to authenticated\r\n  using (driver_id = auth.uid());\r\n\r\ndrop policy if exists \"Operations read driver live locations\" on public.driver_live_locations;\r\ncreate policy \"Operations read driver live locations\" on public.driver_live_locations\r\n  for select to authenticated\r\n  using (public.is_operations_admin());\r\n\r\ncreate or replace function public.update_driver_live_location(\r\n  p_latitude double precision,\r\n  p_longitude double precision,\r\n  p_accuracy_m double precision default null\r\n) returns jsonb\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\ndeclare\r\n  v_allowed boolean := false;\r\n  v_row public.driver_live_locations%rowtype;\r\nbegin\r\n  if auth.uid() is null then raise exception 'Authentication required'; end if;\r\n  if p_latitude is null or p_latitude < -90 or p_latitude > 90\r\n    or p_longitude is null or p_longitude < -180 or p_longitude > 180 then\r\n    raise exception 'Invalid location coordinates';\r\n  end if;\r\n  if p_accuracy_m is not null and (p_accuracy_m < 0 or p_accuracy_m > 10000) then\r\n    raise exception 'Invalid location accuracy';\r\n  end if;\r\n\r\n  select exists (\r\n    select 1 from public.profiles p\r\n    where p.id = auth.uid()\r\n      and p.staff_active is distinct from false\r\n      and (p.is_admin = true or lower(coalesce(p.role, '')) in ('admin', 'driver', 'dispatcher', 'logistics'))\r\n  ) into v_allowed;\r\n  if not v_allowed then raise exception 'Driver or operations access required'; end if;\r\n\r\n  insert into public.driver_live_locations(driver_id, latitude, longitude, accuracy_m, recorded_at, updated_at)\r\n  values (auth.uid(), p_latitude, p_longitude, p_accuracy_m, now(), now())\r\n  on conflict (driver_id) do update set\r\n    latitude = excluded.latitude,\r\n    longitude = excluded.longitude,\r\n    accuracy_m = excluded.accuracy_m,\r\n    recorded_at = excluded.recorded_at,\r\n    updated_at = excluded.updated_at\r\n  returning * into v_row;\r\n\r\n  return jsonb_build_object(\r\n    'driverId', v_row.driver_id,\r\n    'latitude', v_row.latitude,\r\n    'longitude', v_row.longitude,\r\n    'accuracyM', v_row.accuracy_m,\r\n    'recordedAt', v_row.recorded_at\r\n  );\r\nend;\r\n$$;\r\n\r\nrevoke all on function public.update_driver_live_location(double precision, double precision, double precision) from public, anon;\r\ngrant execute on function public.update_driver_live_location(double precision, double precision, double precision) to authenticated;\r\n\r\ngrant select on public.driver_live_locations to authenticated;\r\n\r\ndo $$\r\nbegin\r\n  alter publication supabase_realtime add table public.driver_live_locations;\r\nexception when duplicate_object then\r\n  null;\r\nend;\r\n$$;\r\n\n\n-- Quote requests previously tried to notify a synthetic all-zero UUID. The\r\n-- notifications table references auth.users, so that made every quote insert\r\n-- fail inside the AFTER INSERT trigger. Notify each real admin profile instead.\r\ncreate or replace function public.notify_new_custom_quote() returns trigger\r\nlanguage plpgsql\r\nsecurity definer\r\nset search_path = public\r\nas $$\r\nbegin\r\n  insert into public.notifications(user_id, title, message, type, related_id, is_read)\r\n  select p.id,\r\n         'New quote request',\r\n         coalesce(left(new.description, 120), 'A customer') || ' — respond in Custom Quotes.',\r\n         'quote_request',\r\n         new.id,\r\n         false\r\n  from public.profiles p\r\n  where p.is_admin = true or lower(coalesce(p.role, '')) = 'admin';\r\n\r\n  if new.user_id is not null then\r\n    insert into public.notifications(user_id, title, message, type, related_id)\r\n    values (\r\n      new.user_id,\r\n      'Quote request received',\r\n      'Our team is pricing your request and will reply shortly.',\r\n      'quote',\r\n      new.id\r\n    );\r\n  end if;\r\n\r\n  return new;\r\nend\r\n$$;\r\n\r\ndrop trigger if exists custom_quote_admin_notification on public.custom_quotes;\r\ncreate trigger custom_quote_admin_notification\r\nafter insert on public.custom_quotes\r\nfor each row execute function public.notify_new_custom_quote();\r\n\n\n-- Delivery driver operations.\r\n--\r\n-- Pickup drivers work a shared collection route (route_collection_claims) and\r\n-- that half of the journey is already built. This migration adds the other\r\n-- half: the delivery driver.\r\n--\r\n-- A delivery driver does not get handed a route. At the depot they build the\r\n-- load themselves, one consignment at a time. For each one they type the\r\n-- customer reference and the code stamped on the metal coded seal fitted at\r\n-- collection; the lookup returns what that customer is shipping so the driver\r\n-- can verify the goods in front of them before the item joins the load.\r\n--\r\n-- Every loaded consignment raises a draft delivery note. An admin has to verify\r\n-- each note before the run can start, so a delivery driver never leaves the\r\n-- depot with a document the office has not checked — and can download only the\r\n-- notes that were verified.\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- A. Delivery notes gain an admin verification gate\r\n-- ---------------------------------------------------------------------------\r\n\r\nalter table public.delivery_notes\r\n  add column if not exists verification_status text not null default 'pending',\r\n  add column if not exists verified_by uuid references auth.users(id) on delete set null,\r\n  add column if not exists verified_at timestamptz,\r\n  add column if not exists verification_notes text,\r\n  add column if not exists seal_codes text[] not null default '{}',\r\n  add column if not exists seal_status text,\r\n  add column if not exists discrepancy_note text,\r\n  add column if not exists loaded_at timestamptz;\r\n\r\nalter table public.delivery_notes drop constraint if exists delivery_notes_verification_status_check;\r\nalter table public.delivery_notes add constraint delivery_notes_verification_status_check\r\n  check (verification_status in ('pending', 'verified', 'rejected'));\r\n\r\ncreate index if not exists delivery_notes_verification_idx\r\n  on public.delivery_notes(verification_status, created_at desc);\r\n\r\n-- Notes for deliveries that already happened pre-date the gate. Verifying them\r\n-- now would be theatre, so they are marked verified rather than blocking a\r\n-- driver from downloading a document for a completed job. Anything an admin has\r\n-- since rejected keeps its rejection.\r\nupdate public.delivery_notes\r\n   set verification_status = 'verified',\r\n       verified_at = coalesce(verified_at, updated_at)\r\n where delivered_at is not null\r\n   and verification_status = 'pending';\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- B. The load: what a delivery driver put on the vehicle, and how it verified\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate table if not exists public.delivery_load_items (\r\n  id uuid primary key default gen_random_uuid(),\r\n  run_id uuid not null references public.driver_runs(id) on delete cascade,\r\n  stop_id uuid not null references public.driver_run_stops(id) on delete cascade,\r\n  shipment_id uuid not null references public.shipments(id) on delete cascade,\r\n  driver_id uuid not null references auth.users(id) on delete restrict,\r\n  load_date date not null default current_date,\r\n  -- Exactly what the driver typed, kept verbatim: the reference they matched on\r\n  -- and the code they read off the seal. Both are evidence if a load is queried.\r\n  entered_reference text not null,\r\n  entered_seal_code text,\r\n  seal_status text not null default 'none_on_record'\r\n    check (seal_status in ('matched', 'mismatch', 'none_on_record')),\r\n  recorded_seal_codes text[] not null default '{}',\r\n  discrepancy_note text,\r\n  photo_path text,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now(),\r\n  unique (stop_id)\r\n);\r\n\r\ncreate index if not exists delivery_load_items_driver_date_idx\r\n  on public.delivery_load_items(driver_id, load_date desc);\r\ncreate index if not exists delivery_load_items_run_idx\r\n  on public.delivery_load_items(run_id);\r\n\r\nalter table public.delivery_load_items enable row level security;\r\n\r\ndrop policy if exists \"Staff view delivery load\" on public.delivery_load_items;\r\ncreate policy \"Staff view delivery load\" on public.delivery_load_items\r\n  for select to authenticated\r\n  using (driver_id = auth.uid() or public.is_operations_admin() or public.is_finance_staff());\r\n\r\ndrop policy if exists \"Admins manage delivery load\" on public.delivery_load_items;\r\ncreate policy \"Admins manage delivery load\" on public.delivery_load_items\r\n  for all to authenticated\r\n  using (public.is_operations_admin()) with check (public.is_operations_admin());\r\n\r\n-- Loading photos ride the same proofs pipeline (and 48-hour retention).\r\nalter table public.driver_proofs drop constraint if exists driver_proofs_proof_type_check;\r\nalter table public.driver_proofs add constraint driver_proofs_proof_type_check\r\n  check (proof_type in ('pickup_departure', 'depot_arrival', 'depot_departure',\r\n                        'delivery_arrival', 'exception', 'seal', 'goods', 'delivery_load'));\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- C. Who may work deliveries\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.is_delivery_driver() returns boolean\r\nlanguage sql stable security definer set search_path = public as $$\r\n  select exists (\r\n    select 1 from public.profiles p\r\n    where p.id = auth.uid()\r\n      and coalesce(p.staff_active, true)\r\n      and (\r\n        p.is_admin = true\r\n        or lower(coalesce(p.role, '')) in ('admin', 'dispatcher', 'logistics')\r\n        or (lower(coalesce(p.role, '')) = 'driver'\r\n            and coalesce(p.driver_type, 'both') in ('delivery', 'both'))\r\n      )\r\n  )\r\n$$;\r\ngrant execute on function public.is_delivery_driver() to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- D. Find the consignment from the customer reference (+ seal code)\r\n-- ---------------------------------------------------------------------------\r\n\r\n-- Seal codes are read off stamped metal in poor light, so compare them the way\r\n-- a human would: ignore case, spaces and punctuation.\r\ncreate or replace function public.normalise_seal_code(p_code text) returns text\r\nlanguage sql immutable as $$\r\n  select upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'))\r\n$$;\r\n\r\ncreate or replace function public.lookup_delivery_shipment(\r\n  p_reference text,\r\n  p_seal_code text default null\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_ref text := upper(trim(coalesce(p_reference, '')));\r\n  v_ship public.shipments%rowtype;\r\n  v_seal public.shipment_seals%rowtype;\r\n  v_note public.delivery_notes%rowtype;\r\n  v_item public.delivery_load_items%rowtype;\r\n  v_holder text;\r\n  v_recorded text[];\r\n  v_seal_status text;\r\n  v_entered text := public.normalise_seal_code(p_seal_code);\r\nbegin\r\n  if not public.is_delivery_driver() then raise exception 'Delivery driver access required'; end if;\r\n  if length(v_ref) < 3 then raise exception 'Enter the customer reference from the delivery note or label'; end if;\r\n\r\n  select * into v_ship from public.shipments\r\n   where deleted_at is null\r\n     and (upper(coalesce(customer_reference, '')) = v_ref\r\n       or upper(coalesce(tracking_number, '')) = v_ref)\r\n   order by created_at desc limit 1;\r\n\r\n  if not found then\r\n    -- Fall back to a prefix match so a partially rubbed-off label still lands.\r\n    select * into v_ship from public.shipments\r\n     where deleted_at is null\r\n       and (upper(coalesce(customer_reference, '')) like v_ref || '%'\r\n         or upper(coalesce(tracking_number, '')) like '%' || v_ref)\r\n     order by created_at desc limit 1;\r\n  end if;\r\n  if not found then raise exception 'No consignment found for reference %', v_ref; end if;\r\n\r\n  select * into v_seal from public.shipment_seals where shipment_id = v_ship.id;\r\n  select * into v_note from public.delivery_notes where shipment_id = v_ship.id\r\n   order by created_at desc limit 1;\r\n  select * into v_item from public.delivery_load_items where shipment_id = v_ship.id\r\n   order by created_at desc limit 1;\r\n\r\n  v_recorded := coalesce(v_seal.seal_codes, '{}');\r\n  if coalesce(v_seal.seals_used, false) and coalesce(array_length(v_recorded, 1), 0) > 0 then\r\n    if v_entered = '' then\r\n      v_seal_status := 'not_entered';\r\n    elsif exists (select 1 from unnest(v_recorded) c where public.normalise_seal_code(c) = v_entered) then\r\n      v_seal_status := 'matched';\r\n    else\r\n      v_seal_status := 'mismatch';\r\n    end if;\r\n  else\r\n    v_seal_status := 'none_on_record';\r\n  end if;\r\n\r\n  if v_item.id is not null then\r\n    select coalesce(p.full_name, 'Another driver') into v_holder\r\n      from public.profiles p where p.id = v_item.driver_id;\r\n  end if;\r\n\r\n  return jsonb_build_object(\r\n    'shipmentId', v_ship.id,\r\n    'customerReference', v_ship.customer_reference,\r\n    'trackingNumber', v_ship.tracking_number,\r\n    'status', v_ship.status,\r\n    'deliveryNoteStatus', v_ship.delivery_note_status,\r\n    'senderName', trim(coalesce(v_ship.metadata->'sender'->>'name',\r\n      concat_ws(' ', v_ship.metadata->'sender'->>'firstName', v_ship.metadata->'sender'->>'lastName'))),\r\n    'receiverName', coalesce(v_ship.metadata->'recipient'->>'name',\r\n      v_ship.metadata->'recipientDetails'->>'name', ''),\r\n    'receiverPhone', coalesce(v_ship.metadata->'recipient'->>'phone',\r\n      v_ship.metadata->'recipientDetails'->>'phone', ''),\r\n    'deliveryAddress', coalesce(nullif(concat_ws(', ',\r\n      nullif(coalesce(v_ship.metadata->'recipient'->>'address', v_ship.metadata->'recipientDetails'->>'address'), ''),\r\n      nullif(coalesce(v_ship.metadata->'recipient'->>'city', v_ship.metadata->'recipientDetails'->>'city'), '')), ''),\r\n      v_ship.destination, ''),\r\n    -- What this customer is shipping: the declared description, the driver's\r\n    -- collection correction, and the priced lines from the booking. This is the\r\n    -- list the driver checks the physical goods against.\r\n    'goodsDescription', left(coalesce(v_ship.goods_description, v_ship.metadata->'shipment'->>'description', ''), 600),\r\n    'driverCorrection', v_ship.driver_description_correction,\r\n    'items', coalesce(v_ship.metadata->'invoice'->'items', '[]'::jsonb),\r\n    'sealsRequested', coalesce(v_ship.seals_requested, 0),\r\n    'sealsUsed', coalesce(v_seal.seals_used, false),\r\n    'recordedSealCodes', to_jsonb(v_recorded),\r\n    'sealCondition', v_seal.condition,\r\n    'sealNotes', v_seal.notes,\r\n    'sealStatus', v_seal_status,\r\n    'alreadyLoaded', v_item.id is not null,\r\n    'loadedByName', v_holder,\r\n    'loadedByMe', coalesce(v_item.driver_id = auth.uid(), false),\r\n    'deliveryNote', case when v_note.id is null then null else jsonb_build_object(\r\n      'id', v_note.id, 'noteNumber', v_note.note_number, 'status', v_note.status,\r\n      'verificationStatus', v_note.verification_status, 'verificationNotes', v_note.verification_notes) end\r\n  );\r\nend $$;\r\ngrant execute on function public.lookup_delivery_shipment(text, text) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- E. Put a consignment on the vehicle\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.add_delivery_load_item(\r\n  p_shipment_id uuid,\r\n  p_entered_reference text,\r\n  p_seal_code text default null,\r\n  p_discrepancy_note text default null,\r\n  p_photo_path text default null\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_ship public.shipments%rowtype;\r\n  v_seal public.shipment_seals%rowtype;\r\n  v_run public.driver_runs%rowtype;\r\n  v_stop public.driver_run_stops%rowtype;\r\n  v_item public.delivery_load_items%rowtype;\r\n  v_note public.delivery_notes%rowtype;\r\n  v_recorded text[];\r\n  v_entered text := public.normalise_seal_code(p_seal_code);\r\n  v_seal_status text;\r\n  v_discrepancy text := nullif(trim(coalesce(p_discrepancy_note, '')), '');\r\n  v_order integer;\r\n  v_address text;\r\n  v_number text;\r\nbegin\r\n  if v_uid is null then raise exception 'Sign in required'; end if;\r\n  if not public.is_delivery_driver() then raise exception 'Delivery driver access required'; end if;\r\n\r\n  if not exists (\r\n    select 1 from public.driver_attendance a\r\n     where a.driver_id = v_uid and a.work_date = current_date and a.clocked_out_at is null\r\n  ) and not public.is_operations_admin() then\r\n    raise exception 'Clock in before loading the vehicle';\r\n  end if;\r\n\r\n  select * into v_ship from public.shipments where id = p_shipment_id and deleted_at is null for update;\r\n  if not found then raise exception 'Consignment not found'; end if;\r\n  if lower(coalesce(v_ship.status, '')) = 'delivered' then\r\n    raise exception 'This consignment has already been delivered';\r\n  end if;\r\n  if lower(coalesce(v_ship.status, '')) = 'cancelled' then\r\n    raise exception 'This consignment was cancelled — do not load it';\r\n  end if;\r\n\r\n  -- Seal check. A mismatch is never silently accepted: the driver has to look at\r\n  -- what the customer reference says is being shipped and record what they found\r\n  -- before the item can travel, and that note goes to admin with the note.\r\n  select * into v_seal from public.shipment_seals where shipment_id = v_ship.id;\r\n  v_recorded := coalesce(v_seal.seal_codes, '{}');\r\n  if coalesce(v_seal.seals_used, false) and coalesce(array_length(v_recorded, 1), 0) > 0 then\r\n    if v_entered = '' then\r\n      raise exception 'This consignment was sealed at collection — enter the code stamped on the seal';\r\n    elsif exists (select 1 from unnest(v_recorded) c where public.normalise_seal_code(c) = v_entered) then\r\n      v_seal_status := 'matched';\r\n    else\r\n      v_seal_status := 'mismatch';\r\n      if v_discrepancy is null then\r\n        raise exception 'Seal % does not match the seal recorded at collection (%). Check the goods against what this customer reference says is being shipped, then record what you found to load it.',\r\n          trim(p_seal_code), array_to_string(v_recorded, ', ');\r\n      end if;\r\n    end if;\r\n  else\r\n    v_seal_status := 'none_on_record';\r\n    if v_entered <> '' then\r\n      v_discrepancy := trim(concat_ws(' ',\r\n        'Seal ' || trim(p_seal_code) || ' found on the goods but no seal was recorded at collection.',\r\n        v_discrepancy));\r\n    end if;\r\n  end if;\r\n\r\n  -- Today's delivery run. One run per driver per day, so a driver cannot be\r\n  -- half on a collection route and half on a delivery route.\r\n  select * into v_run from public.driver_runs\r\n   where driver_id = v_uid and run_date = current_date for update;\r\n  if found and v_run.run_type <> 'delivery' then\r\n    raise exception 'You already have a % route today — deliveries need their own day', v_run.run_type;\r\n  end if;\r\n  if found and v_run.status = 'completed' then\r\n    raise exception 'Today''s delivery run is already closed';\r\n  end if;\r\n  if not found then\r\n    insert into public.driver_runs(driver_id, run_date, status, run_type, route_name)\r\n    values (v_uid, current_date, 'planned', 'delivery', 'Delivery route')\r\n    returning * into v_run;\r\n  end if;\r\n\r\n  v_address := coalesce(\r\n    nullif(concat_ws(', ',\r\n      nullif(coalesce(v_ship.metadata->'recipient'->>'address', v_ship.metadata->'recipientDetails'->>'address'), ''),\r\n      nullif(coalesce(v_ship.metadata->'recipient'->>'city', v_ship.metadata->'recipientDetails'->>'city'), '')), ''),\r\n    v_ship.destination);\r\n\r\n  select * into v_stop from public.driver_run_stops\r\n   where shipment_id = v_ship.id and stop_type = 'delivery' and status <> 'failed' limit 1 for update;\r\n  if found then\r\n    if v_stop.run_id <> v_run.id then\r\n      raise exception 'This consignment is already loaded on another delivery run';\r\n    end if;\r\n    update public.driver_run_stops set address = coalesce(v_stop.address, v_address), updated_at = now()\r\n     where id = v_stop.id returning * into v_stop;\r\n  else\r\n    select coalesce(max(stop_order), 0) + 1 into v_order from public.driver_run_stops where run_id = v_run.id;\r\n    insert into public.driver_run_stops(run_id, shipment_id, stop_order, stop_type, status, address)\r\n    values (v_run.id, v_ship.id, v_order, 'delivery', 'planned', v_address)\r\n    returning * into v_stop;\r\n  end if;\r\n\r\n  insert into public.delivery_load_items(run_id, stop_id, shipment_id, driver_id, load_date,\r\n    entered_reference, entered_seal_code, seal_status, recorded_seal_codes, discrepancy_note, photo_path)\r\n  values (v_run.id, v_stop.id, v_ship.id, v_uid, current_date,\r\n    trim(coalesce(p_entered_reference, coalesce(v_ship.customer_reference, ''))),\r\n    nullif(trim(coalesce(p_seal_code, '')), ''), v_seal_status, v_recorded, v_discrepancy, p_photo_path)\r\n  on conflict (stop_id) do update set\r\n    entered_reference = excluded.entered_reference,\r\n    entered_seal_code = excluded.entered_seal_code,\r\n    seal_status = excluded.seal_status,\r\n    recorded_seal_codes = excluded.recorded_seal_codes,\r\n    discrepancy_note = coalesce(excluded.discrepancy_note, delivery_load_items.discrepancy_note),\r\n    photo_path = coalesce(excluded.photo_path, delivery_load_items.photo_path),\r\n    updated_at = now()\r\n  returning * into v_item;\r\n\r\n  -- Raise the delivery note in draft so admin has something to verify. A note\r\n  -- that was already verified keeps that verification; a rejected one goes back\r\n  -- to pending because the driver has just re-presented the goods.\r\n  v_number := 'DN-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(v_stop.id::text, '-', ''), 1, 6));\r\n  insert into public.delivery_notes(shipment_id, stop_id, driver_id, note_number, recipient_name,\r\n    delivery_address, status, verification_status, seal_codes, seal_status, discrepancy_note, loaded_at)\r\n  values (v_ship.id, v_stop.id, v_uid, v_number,\r\n    coalesce(v_ship.metadata->'recipient'->>'name', v_ship.metadata->'recipientDetails'->>'name'),\r\n    v_address, 'draft', 'pending',\r\n    case when v_item.entered_seal_code is null then v_recorded else array[v_item.entered_seal_code] end,\r\n    v_seal_status, v_discrepancy, now())\r\n  on conflict (stop_id) do update set\r\n    driver_id = v_uid,\r\n    recipient_name = coalesce(delivery_notes.recipient_name, excluded.recipient_name),\r\n    delivery_address = coalesce(delivery_notes.delivery_address, excluded.delivery_address),\r\n    seal_codes = excluded.seal_codes,\r\n    seal_status = excluded.seal_status,\r\n    discrepancy_note = coalesce(excluded.discrepancy_note, delivery_notes.discrepancy_note),\r\n    loaded_at = coalesce(delivery_notes.loaded_at, now()),\r\n    verification_status = case when delivery_notes.verification_status = 'verified'\r\n      then 'verified' else 'pending' end,\r\n    updated_at = now()\r\n  returning * into v_note;\r\n\r\n  update public.shipments set assigned_driver_id = v_uid, driver_status = 'loaded',\r\n    delivery_note_status = case when coalesce(delivery_note_status, 'Draft') = 'Completed'\r\n      then delivery_note_status else 'Awaiting Verification' end,\r\n    updated_at = now()\r\n   where id = v_ship.id;\r\n\r\n  insert into public.shipment_events(shipment_id, event_type, previous_status, new_status, actor_id, details)\r\n  values (v_ship.id, 'delivery_loaded', v_ship.driver_status, 'loaded', v_uid,\r\n    jsonb_build_object('runId', v_run.id, 'stopId', v_stop.id, 'sealStatus', v_seal_status,\r\n      'enteredSeal', v_item.entered_seal_code, 'deliveryNote', v_note.note_number));\r\n\r\n  -- Tell dispatch there is something to verify. Without this the driver would be\r\n  -- sitting in a loaded vehicle waiting on an admin who does not know. Correcting\r\n  -- an entry re-sends only after twelve hours, so fixing a typo is not a ping.\r\n  if v_note.verification_status = 'pending' and not exists (\r\n    select 1 from public.staff_messages m\r\n     where m.shipment_id = v_ship.id and m.audience_role = 'dispatch'\r\n       and m.subject = 'Delivery note to verify' and m.created_at > now() - interval '12 hours'\r\n  ) then\r\n    insert into public.staff_messages(sender_id, recipient_id, audience_role, shipment_id, subject, body, priority)\r\n    values (v_uid, null, 'dispatch', v_ship.id, 'Delivery note to verify',\r\n      v_note.note_number || ' (' || coalesce(v_ship.customer_reference, v_ship.tracking_number, 'consignment')\r\n        || ') is loaded for delivery'\r\n        || case when v_seal_status = 'mismatch' then ' WITH A SEAL DISCREPANCY — ' || coalesce(v_discrepancy, 'see the note') else '' end\r\n        || '. It needs verifying before the run can start.',\r\n      case when v_seal_status = 'mismatch' then 'urgent' else 'normal' end);\r\n  end if;\r\n\r\n  return jsonb_build_object('runId', v_run.id, 'stopId', v_stop.id, 'shipmentId', v_ship.id,\r\n    'sealStatus', v_seal_status, 'discrepancy', v_discrepancy,\r\n    'deliveryNote', jsonb_build_object('id', v_note.id, 'noteNumber', v_note.note_number,\r\n      'verificationStatus', v_note.verification_status));\r\nend $$;\r\ngrant execute on function public.add_delivery_load_item(uuid, text, text, text, text) to authenticated;\r\n\r\ncreate or replace function public.remove_delivery_load_item(p_stop_id uuid, p_reason text default null)\r\nreturns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare v_item public.delivery_load_items%rowtype; v_stop public.driver_run_stops%rowtype;\r\nbegin\r\n  select * into v_item from public.delivery_load_items where stop_id = p_stop_id for update;\r\n  if not found then raise exception 'This consignment is not on your load'; end if;\r\n  if v_item.driver_id <> auth.uid() and not public.is_operations_admin() then\r\n    raise exception 'Only the loading driver or dispatch can take this off the vehicle';\r\n  end if;\r\n  select * into v_stop from public.driver_run_stops where id = p_stop_id;\r\n  if v_stop.status not in ('planned', 'en_route') then\r\n    raise exception 'This delivery is already under way and cannot be unloaded here';\r\n  end if;\r\n\r\n  delete from public.delivery_load_items where stop_id = p_stop_id;\r\n\r\n  -- A note the office has already verified is a record, not a draft. It is\r\n  -- voided rather than deleted, and because delivery_notes.stop_id is ON DELETE\r\n  -- RESTRICT the stop has to stay too — it is failed instead, which also frees\r\n  -- the one-active-handover index so the goods can be reloaded another day.\r\n  if exists (select 1 from public.delivery_notes where stop_id = p_stop_id and verification_status = 'verified') then\r\n    update public.delivery_notes set status = 'void', updated_at = now() where stop_id = p_stop_id;\r\n    update public.driver_run_stops set status = 'failed', failure_reason = 'unloaded',\r\n      failure_note = coalesce(p_reason, 'Taken off the vehicle'), failed_at = now(), updated_at = now()\r\n     where id = p_stop_id;\r\n  else\r\n    delete from public.delivery_notes where stop_id = p_stop_id;\r\n    delete from public.driver_run_stops where id = p_stop_id;\r\n  end if;\r\n\r\n  update public.shipments set assigned_driver_id = null, driver_status = 'available', updated_at = now()\r\n   where id = v_item.shipment_id;\r\n  insert into public.shipment_events(shipment_id, event_type, previous_status, new_status, actor_id, details)\r\n  values (v_item.shipment_id, 'delivery_unloaded', 'loaded', 'available', auth.uid(),\r\n    jsonb_build_object('reason', p_reason, 'stopId', p_stop_id));\r\n\r\n  return jsonb_build_object('shipmentId', v_item.shipment_id, 'removed', true);\r\nend $$;\r\ngrant execute on function public.remove_delivery_load_item(uuid, text) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- F. The driver's own load for a day\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.driver_delivery_load(p_date date default null)\r\nreturns jsonb language plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_uid uuid := auth.uid();\r\n  v_day date := coalesce(p_date, current_date);\r\n  v_run public.driver_runs%rowtype;\r\n  v_items jsonb;\r\nbegin\r\n  if v_uid is null then raise exception 'Sign in required'; end if;\r\n  if not public.is_delivery_driver() then raise exception 'Delivery driver access required'; end if;\r\n\r\n  select * into v_run from public.driver_runs\r\n   where driver_id = v_uid and run_date = v_day and run_type = 'delivery'\r\n   order by created_at desc limit 1;\r\n\r\n  if v_run.id is null then\r\n    return jsonb_build_object('date', v_day, 'run', null, 'items', '[]'::jsonb);\r\n  end if;\r\n\r\n  select coalesce(jsonb_agg(x order by x->>'stopOrder'), '[]'::jsonb) into v_items from (\r\n    select jsonb_build_object(\r\n      'stopId', st.id, 'stopOrder', lpad(st.stop_order::text, 4, '0'), 'stopStatus', st.status,\r\n      'shipmentId', s.id, 'customerReference', s.customer_reference, 'trackingNumber', s.tracking_number,\r\n      'receiverName', coalesce(n.recipient_name, s.metadata->'recipient'->>'name',\r\n        s.metadata->'recipientDetails'->>'name', ''),\r\n      'receiverPhone', coalesce(s.metadata->'recipient'->>'phone',\r\n        s.metadata->'recipientDetails'->>'phone', ''),\r\n      'address', coalesce(st.address, s.destination, ''),\r\n      'latitude', st.latitude, 'longitude', st.longitude,\r\n      'goodsDescription', left(coalesce(s.goods_description, ''), 400),\r\n      'enteredSealCode', li.entered_seal_code, 'sealStatus', li.seal_status,\r\n      'recordedSealCodes', to_jsonb(li.recorded_seal_codes),\r\n      'discrepancyNote', li.discrepancy_note, 'photoPath', li.photo_path,\r\n      'loadedAt', li.created_at,\r\n      'noteId', n.id, 'noteNumber', n.note_number, 'noteStatus', n.status,\r\n      'verificationStatus', coalesce(n.verification_status, 'pending'),\r\n      'verificationNotes', n.verification_notes\r\n    ) x\r\n    from public.delivery_load_items li\r\n    join public.driver_run_stops st on st.id = li.stop_id\r\n    join public.shipments s on s.id = li.shipment_id\r\n    left join public.delivery_notes n on n.stop_id = li.stop_id\r\n    where li.run_id = v_run.id\r\n  ) q;\r\n\r\n  return jsonb_build_object('date', v_day, 'run', to_jsonb(v_run), 'items', v_items);\r\nend $$;\r\ngrant execute on function public.driver_delivery_load(date) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- G. Admin verification\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.verify_delivery_note(\r\n  p_note_id uuid,\r\n  p_approved boolean,\r\n  p_notes text default null\r\n) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare v_note public.delivery_notes%rowtype;\r\nbegin\r\n  if not public.is_operations_admin() then raise exception 'Admin access required to verify a delivery note'; end if;\r\n\r\n  update public.delivery_notes set\r\n    verification_status = case when p_approved then 'verified' else 'rejected' end,\r\n    verification_notes = nullif(trim(coalesce(p_notes, '')), ''),\r\n    verified_by = auth.uid(), verified_at = now(),\r\n    status = case when p_approved then status else 'exception' end,\r\n    updated_at = now()\r\n  where id = p_note_id returning * into v_note;\r\n  if not found then raise exception 'Delivery note not found'; end if;\r\n\r\n  update public.shipments set\r\n    delivery_note_status = case when p_approved then 'Verified' else 'Rejected' end,\r\n    updated_at = now()\r\n   where id = v_note.shipment_id and coalesce(delivery_note_status, '') <> 'Completed';\r\n\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), case when p_approved then 'VERIFY' else 'REJECT' end, 'DELIVERY_NOTE', v_note.id,\r\n    jsonb_build_object('noteNumber', v_note.note_number, 'notes', p_notes));\r\n\r\n  insert into public.staff_messages(sender_id, recipient_id, audience_role, shipment_id, subject, body, priority)\r\n  values (auth.uid(), v_note.driver_id, 'driver', v_note.shipment_id,\r\n    case when p_approved then 'Delivery note verified' else 'Delivery note rejected' end,\r\n    v_note.note_number || (case when p_approved\r\n      then ' has been verified — you can download it and deliver this consignment.'\r\n      else ' was rejected. ' || coalesce(nullif(trim(coalesce(p_notes, '')), ''), 'Check the goods and seal against the booking.') end),\r\n    case when p_approved then 'normal' else 'urgent' end);\r\n\r\n  return to_jsonb(v_note);\r\nend $$;\r\ngrant execute on function public.verify_delivery_note(uuid, boolean, text) to authenticated;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- H. A delivery run cannot start until every note on it is verified\r\n-- ---------------------------------------------------------------------------\r\n\r\ncreate or replace function public.start_driver_run(p_run_id uuid) returns jsonb\r\nlanguage plpgsql security definer set search_path = public as $$\r\ndeclare\r\n  v_run public.driver_runs%rowtype;\r\n  v_type text;\r\n  v_unverified integer;\r\n  v_rejected integer;\r\nbegin\r\n  select * into v_run from public.driver_runs where id = p_run_id for update;\r\n  if not found or v_run.driver_id <> auth.uid() then raise exception 'Run is not assigned to you'; end if;\r\n  if not exists (select 1 from public.driver_attendance\r\n    where driver_id = auth.uid() and work_date = current_date and clocked_out_at is null)\r\n  then raise exception 'Clock in before starting your route'; end if;\r\n  select driver_type into v_type from public.profiles where id = auth.uid();\r\n  if coalesce(v_type, 'both') <> 'both' and v_type <> v_run.run_type then\r\n    raise exception 'This route does not match your driver specialism';\r\n  end if;\r\n  if v_run.run_date <> current_date then raise exception 'Only today''s route can be started'; end if;\r\n\r\n  if v_run.run_type = 'delivery' then\r\n    if not exists (select 1 from public.driver_run_stops where run_id = v_run.id and stop_type = 'delivery') then\r\n      raise exception 'Load the vehicle before starting the delivery run';\r\n    end if;\r\n    select count(*) filter (where coalesce(n.verification_status, 'pending') = 'pending'),\r\n           count(*) filter (where n.verification_status = 'rejected')\r\n      into v_unverified, v_rejected\r\n      from public.driver_run_stops st\r\n      left join public.delivery_notes n on n.stop_id = st.id\r\n     where st.run_id = v_run.id and st.stop_type = 'delivery' and st.status <> 'failed';\r\n    if coalesce(v_rejected, 0) > 0 then\r\n      raise exception '% delivery note(s) were rejected by admin — take those consignments off the vehicle first', v_rejected;\r\n    end if;\r\n    if coalesce(v_unverified, 0) > 0 then\r\n      raise exception '% delivery note(s) are still waiting for admin verification', v_unverified;\r\n    end if;\r\n    update public.shipments s set status = 'Out for Delivery', updated_at = now()\r\n      from public.driver_run_stops st\r\n     where st.run_id = v_run.id and st.stop_type = 'delivery' and st.status <> 'failed'\r\n       and s.id = st.shipment_id and lower(coalesce(s.status, '')) <> 'delivered';\r\n  end if;\r\n\r\n  update public.driver_runs set status = 'active', started_at = coalesce(started_at, now()), updated_at = now()\r\n   where id = p_run_id returning * into v_run;\r\n  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)\r\n  values (auth.uid(), 'START_RUN', 'DRIVER_RUN', v_run.id,\r\n    jsonb_build_object('route', v_run.route_name, 'runType', v_run.run_type));\r\n  return to_jsonb(v_run);\r\nend $$;\r\ngrant execute on function public.start_driver_run(uuid) to authenticated;\r\n\r\ndo $$ begin alter publication supabase_realtime add table public.delivery_notes; exception when duplicate_object then null; end $$;\r\ndo $$ begin alter publication supabase_realtime add table public.delivery_load_items; exception when duplicate_object then null; end $$;\r\n\n\n-- Delivery note register: the ledger of every office delivery note issued from\r\n-- a source invoice.\r\n--\r\n-- This replaces a hand-kept list that had to be pasted into a prompt each\r\n-- session. It exists so the generator can answer two questions before it writes\r\n-- a file: has this exact note already been issued, and is this invoice number\r\n-- already carrying a different load?\r\n--\r\n-- Deliberately NOT the same thing as public.delivery_notes, which is the\r\n-- driver's proof-of-delivery record for a run stop. This table is the printed\r\n-- office document; that one is what happened at the door.\r\n--\r\n-- Applied to the live DB via the staff-ops edge function's \"setup\" action.\r\n\r\ncreate table if not exists public.delivery_note_records (\r\n  id uuid primary key default gen_random_uuid(),\r\n\r\n  -- REF as printed on the note: 3 letters of the shipper's given name + the\r\n  -- invoice number exactly as printed + any load suffix.\r\n  reference text not null,\r\n  invoice_number text not null,\r\n  -- A/B/C when one invoice number carries more than one real shipment. Always\r\n  -- assigned by a human, never derived.\r\n  load_suffix text,\r\n\r\n  shipper_name text,\r\n  shipper_phone text,\r\n  shipper_address text,\r\n\r\n  recipient_name text,\r\n  recipient_phone text,\r\n  recipient_address text,\r\n  recipient_city text,\r\n\r\n  -- The printed manifest rows, exactly as they went onto the PDF.\r\n  items jsonb not null default '[]'::jsonb,\r\n  -- Sorted \"item:qty\" digest of the goods rows, so a duplicate can be told from\r\n  -- a second load without comparing free text.\r\n  item_fingerprint text,\r\n\r\n  delivery_mode text not null default 'door_to_door'\r\n    check (delivery_mode in ('door_to_door', 'self_collection')),\r\n\r\n  paid boolean not null default false,\r\n  -- Money still owed at the time the note was issued. A note can go out unpaid;\r\n  -- the register has to say so.\r\n  balance_due numeric(12,2),\r\n  unpaid_hold boolean not null default false,\r\n\r\n  note_date date,\r\n  pdf_filename text,\r\n\r\n  -- The raw vision transcription this note was computed from, kept so a\r\n  -- disputed note can be checked against what the invoice actually said.\r\n  source_extraction jsonb,\r\n  -- Flags that were live at confirmation, with who acknowledged what.\r\n  review_flags jsonb not null default '[]'::jsonb,\r\n\r\n  -- Set when the note was raised against a booking in this system; null for an\r\n  -- external invoice, which is the common case.\r\n  shipment_id uuid references public.shipments(id) on delete set null,\r\n\r\n  confirmed_by uuid references auth.users(id) on delete set null,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\n-- One reference, one shipment. This constraint is the whole point of the table:\r\n-- two different real loads must never end up sharing a reference.\r\ncreate unique index if not exists delivery_note_records_reference_key\r\n  on public.delivery_note_records (upper(reference));\r\n\r\ncreate index if not exists delivery_note_records_invoice_idx\r\n  on public.delivery_note_records (invoice_number);\r\ncreate index if not exists delivery_note_records_created_idx\r\n  on public.delivery_note_records (created_at desc);\r\n\r\nalter table public.delivery_note_records enable row level security;\r\n\r\ndrop policy if exists \"Staff read delivery note register\" on public.delivery_note_records;\r\ncreate policy \"Staff read delivery note register\" on public.delivery_note_records\r\n  for select to authenticated\r\n  using (public.is_staff_member());\r\n\r\ndrop policy if exists \"Staff write delivery note register\" on public.delivery_note_records;\r\ncreate policy \"Staff write delivery note register\" on public.delivery_note_records\r\n  for insert to authenticated\r\n  with check (public.is_staff_member() and confirmed_by = auth.uid());\r\n\r\n-- Corrections stay with admins: an issued note is a record of what was printed,\r\n-- not a working draft.\r\ndrop policy if exists \"Admins amend delivery note register\" on public.delivery_note_records;\r\ncreate policy \"Admins amend delivery note register\" on public.delivery_note_records\r\n  for update to authenticated\r\n  using (public.is_operations_admin()) with check (public.is_operations_admin());\r\n\r\ncreate or replace function public.touch_delivery_note_records()\r\nreturns trigger language plpgsql as $$\r\nbegin\r\n  new.updated_at = now();\r\n  return new;\r\nend;\r\n$$;\r\n\r\ndrop trigger if exists delivery_note_records_touch on public.delivery_note_records;\r\ncreate trigger delivery_note_records_touch\r\n  before update on public.delivery_note_records\r\n  for each row execute function public.touch_delivery_note_records();\r\n\n\n-- Audited corrections and voiding for the office delivery-note register.\n-- Issued notes are never physically deleted: retaining the old reference and\n-- invoice is essential to duplicate and multi-load detection.\n\nalter table public.delivery_note_records\n  add column if not exists revision integer not null default 1,\n  add column if not exists amended_at timestamptz,\n  add column if not exists amended_by uuid references auth.users(id) on delete set null,\n  add column if not exists last_change_reason text,\n  add column if not exists voided_at timestamptz,\n  add column if not exists voided_by uuid references auth.users(id) on delete set null,\n  add column if not exists void_reason text;\n\ncreate table if not exists public.delivery_note_record_revisions (\n  id uuid primary key default gen_random_uuid(),\n  record_id uuid not null references public.delivery_note_records(id) on delete cascade,\n  revision integer not null,\n  action text not null check (action in ('edit', 'void')),\n  reason text not null,\n  snapshot jsonb not null,\n  changed_by uuid references auth.users(id) on delete set null,\n  changed_at timestamptz not null default now()\n);\n\ncreate index if not exists delivery_note_record_revisions_record_idx\n  on public.delivery_note_record_revisions(record_id, revision desc);\n\nalter table public.delivery_note_record_revisions enable row level security;\n\ndrop policy if exists \"Staff read delivery note revisions\" on public.delivery_note_record_revisions;\ncreate policy \"Staff read delivery note revisions\" on public.delivery_note_record_revisions\n  for select to authenticated using (public.is_staff_member());\n\ncreate or replace function public.capture_delivery_note_record_revision()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_action text;\n  v_reason text;\nbegin\n  v_action := case when old.voided_at is null and new.voided_at is not null then 'void' else 'edit' end;\n  v_reason := trim(coalesce(\n    case when v_action = 'void' then new.void_reason else new.last_change_reason end,\n    ''\n  ));\n  if v_reason = '' then\n    raise exception 'Enter a reason for changing this delivery note';\n  end if;\n\n  insert into public.delivery_note_record_revisions(\n    record_id, revision, action, reason, snapshot, changed_by\n  ) values (\n    old.id, old.revision, v_action, v_reason, to_jsonb(old), auth.uid()\n  );\n\n  new.revision := old.revision + 1;\n  new.amended_at := now();\n  new.amended_by := auth.uid();\n  return new;\nend;\n$$;\n\ndrop trigger if exists delivery_note_records_capture_revision on public.delivery_note_records;\ncreate trigger delivery_note_records_capture_revision\n  before update on public.delivery_note_records\n  for each row execute function public.capture_delivery_note_record_revision();\n\n-- There is deliberately no DELETE policy. Admin \"Delete\" is a void update so\n-- a historical invoice cannot disappear from the duplicate ledger.\n";

const SETUP_SQL = String.raw`
alter table public.driver_run_stops add column if not exists failure_note text;
alter table public.driver_run_stops add column if not exists failed_at timestamptz;

-- Customer-app onboarding upserts the caller's own profile row. Without an
-- INSERT policy the upsert fails with an RLS violation for brand-new users
-- (no handle_new_user row exists for them). Mirrors
-- supabase/migrations/20260718_profiles_insert_policy.sql.
drop policy if exists "Customers insert own profile" on public.profiles;
create policy "Customers insert own profile" on public.profiles
  for insert to authenticated with check (id = auth.uid());

-- Admins can explicitly assign themselves a run and operate the driver
-- dashboard without changing their permanent role away from admin.
create or replace function public.clock_driver(
  p_action text,
  p_note text default null
) returns jsonb
language plpgsql security definer set search_path = public as $fn$
declare v_row public.driver_attendance%rowtype;
begin
  if not exists (
    select 1 from public.profiles where id = auth.uid()
      and (is_admin = true or lower(coalesce(role, '')) in ('admin', 'logistics', 'driver'))
  ) then raise exception 'Driver access required'; end if;
  if p_action = 'in' then
    insert into public.driver_attendance(driver_id, work_date, clocked_in_at, clock_in_note)
    values(auth.uid(), current_date, now(), p_note)
    on conflict(driver_id, work_date) do update
      set clocked_in_at = coalesce(driver_attendance.clocked_in_at, now()),
          clocked_out_at = null,
          clock_in_note = coalesce(excluded.clock_in_note, driver_attendance.clock_in_note)
    returning * into v_row;
  elsif p_action = 'out' then
    if exists (
      select 1 from public.driver_runs r join public.driver_run_stops s on s.run_id = r.id
      where r.driver_id = auth.uid() and r.run_date = current_date and r.status = 'active'
        and s.status not in ('completed', 'failed')
    ) then raise exception 'Complete or report every active stop before clocking out'; end if;
    update public.driver_attendance set clocked_out_at = now(), clock_out_note = p_note
      where driver_id = auth.uid() and work_date = current_date returning * into v_row;
    if not found then raise exception 'Clock in before clocking out'; end if;
  else raise exception 'Action must be in or out'; end if;
  insert into public.audit_logs(user_id, action, entity_type, entity_id, details)
  values(auth.uid(), 'CLOCK_' || upper(p_action), 'DRIVER_ATTENDANCE', v_row.id,
         jsonb_build_object('workDate', v_row.work_date));
  return to_jsonb(v_row);
end; $fn$;

grant execute on function public.clock_driver(text, text) to authenticated;

create or replace function public.fail_driver_stop(
  p_stop_id uuid,
  p_reason text,
  p_note text default null
) returns jsonb
language plpgsql security definer set search_path = public as $fn$
declare
  v_stop public.driver_run_stops%rowtype;
  v_run public.driver_runs%rowtype;
  v_is_admin boolean := false;
  v_now timestamptz := now();
  v_customer text;
begin
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and (is_admin = true or lower(coalesce(role, '')) in ('admin', 'logistics'))
  ) into v_is_admin;

  select * into v_stop from public.driver_run_stops where id = p_stop_id for update;
  if not found then raise exception 'Driver stop not found'; end if;
  select * into v_run from public.driver_runs where id = v_stop.run_id;
  if not v_is_admin and v_run.driver_id <> auth.uid() then
    raise exception 'This stop is not assigned to you';
  end if;
  if v_stop.status in ('completed', 'failed') then
    raise exception 'This stop is already closed';
  end if;
  if p_reason not in ('not_home', 'goods_not_ready', 'payment_issue', 'access_problem', 'other') then
    raise exception 'Unknown failure reason';
  end if;

  update public.driver_run_stops set
    status = 'failed',
    failure_reason = p_reason,
    failure_note = nullif(trim(coalesce(p_note, '')), ''),
    failed_at = v_now,
    updated_at = v_now
  where id = p_stop_id
  returning * into v_stop;

  update public.shipments set
    driver_status = 'failed',
    updated_at = v_now,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'driverUpdate', jsonb_build_object(
        'status', 'failed', 'reason', p_reason, 'note', p_note,
        'stopType', v_stop.stop_type, 'updatedAt', v_now, 'driverId', v_run.driver_id
      )
    )
  where id = v_stop.shipment_id;

  insert into public.shipment_events(shipment_id, event_type, previous_status, new_status, actor_id, details)
  values (v_stop.shipment_id, 'driver_stop_failed', null, 'failed', auth.uid(),
          jsonb_build_object('runId', v_run.id, 'stopId', v_stop.id, 'reason', p_reason, 'note', p_note));

  select coalesce(metadata->'sender'->>'name', metadata->'recipient'->>'name', tracking_number)
    into v_customer from public.shipments where id = v_stop.shipment_id;

  insert into public.notifications(user_id, title, message, type, related_id, is_read)
  values ('00000000-0000-0000-0000-000000000000',
          'Driver stop failed',
          coalesce(v_customer, 'A stop') || ' — ' || replace(p_reason, '_', ' ') ||
            coalesce(': ' || p_note, '') || '. Replan this ' || v_stop.stop_type || '.',
          'driver_exception', v_stop.shipment_id, false);

  return jsonb_build_object('stopId', v_stop.id, 'status', v_stop.status, 'reason', p_reason);
end; $fn$;

create or replace function public.complete_driver_run(p_run_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $fn$
declare
  v_run public.driver_runs%rowtype;
  v_open integer;
  v_done integer;
  v_failed integer;
  v_cash jsonb;
begin
  select * into v_run from public.driver_runs where id = p_run_id for update;
  if not found then raise exception 'Run not found'; end if;
  if v_run.driver_id <> auth.uid() and not exists (
    select 1 from public.profiles
    where id = auth.uid() and (is_admin = true or lower(coalesce(role, '')) in ('admin', 'logistics'))
  ) then
    raise exception 'This run is not assigned to you';
  end if;
  if v_run.status <> 'active' then raise exception 'Only an active run can be completed'; end if;

  select count(*) filter (where status not in ('completed', 'failed')),
         count(*) filter (where status = 'completed'),
         count(*) filter (where status = 'failed')
    into v_open, v_done, v_failed
    from public.driver_run_stops where run_id = p_run_id;
  if v_open > 0 then
    raise exception 'There are still % open stop(s). Complete or mark them as exceptions first.', v_open;
  end if;

  select coalesce(jsonb_object_agg(currency, total), '{}'::jsonb) into v_cash
  from (
    select i.currency, sum(i.total) as total
    from public.driver_invoices i
    join public.driver_run_stops s on s.id = i.stop_id
    where s.run_id = p_run_id
    group by i.currency
  ) sums;

  update public.driver_runs
     set status = 'completed', completed_at = now(), updated_at = now()
   where id = p_run_id;

  insert into public.notifications(user_id, title, message, type, related_id, is_read)
  values ('00000000-0000-0000-0000-000000000000', 'Driver run completed',
          coalesce(v_run.route_name, 'Run') || ': ' || v_done || ' completed, ' || v_failed || ' failed.',
          'driver_run', p_run_id, false);

  return jsonb_build_object('completed', v_done, 'failed', v_failed, 'invoiced', v_cash);
end; $fn$;
`;

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
  try {
    const body = await req.json().catch(() => ({}));
    if (!["setup", "verify", "invite_staff"].includes(body?.action)) {
      return new Response(JSON.stringify({ error: "Unknown action" }), {
        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Gate every action, not just invite_staff. "setup" executes DDL and "verify"
    // returns operational figures, so neither may run for an anonymous caller.
    const gate = await requireAdmin(req);
    if ("response" in gate) return gate.response;
    const callerId = gate.userId;

    const dbUrl = Deno.env.get("SUPABASE_DB_URL");
    if (!dbUrl) throw new Error("SUPABASE_DB_URL is not available");

    // Admin-only staff invitation: the invite email comes from Supabase Auth;
    // no password is ever handled or stored here.
    if (body.action === "invite_staff") {
      // The caller was already verified as an admin by requireAdmin above.
      const admin = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);
      const email = String(body.email || "").trim().toLowerCase();
      const fullName = String(body.fullName || "").trim();
      const role = String(body.role || "staff").toLowerCase();
      const phone = String(body.phone || "").trim();
      if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
        return new Response(JSON.stringify({ error: "Enter a valid email address" }), {
          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      if (!["admin", "driver", "finance", "logistics", "dispatcher"].includes(role)) {
        return new Response(JSON.stringify({ error: "Unknown staff role" }), {
          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      // The account is created WITH a temporary password rather than emailed an
      // invite link. Invite emails depend on SMTP deliverability, which is the
      // known bottleneck here — a driver who never receives the mail cannot work.
      // The admin reads the temporary password to them, and `must_change_password`
      // forces them to replace it the moment they first sign in.
      const tempPassword = generateTempPassword();

      const { data: invited, error: inviteError } = await admin.auth.admin.createUser({
        email,
        password: tempPassword,
        // No inbox round-trip, so confirm here or the first sign-in is blocked.
        email_confirm: true,
        user_metadata: { full_name: fullName, must_change_password: true },
      });
      if (inviteError) {
        return new Response(JSON.stringify({ error: inviteError.message }), {
          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      await admin.from("profiles").upsert({
        id: invited.user.id,
        email,
        full_name: fullName || null,
        phone_number: phone || null,
        role,
        is_admin: role === "admin",
        staff_active: true,
      }, { onConflict: "id" });
      await admin.from("audit_logs").insert({
        user_id: callerId,
        action: "CREATE_STAFF",
        entity_type: "PROFILE",
        entity_id: invited.user.id,
        // Deliberately never records the temporary password. The audit log is
        // readable by every admin and is retained indefinitely.
        details: { email, role, fullName, method: "temp_password" },
      });

      // The only time this password is ever returned. It is not stored anywhere
      // in readable form — if the admin loses it, use "Reset access" instead.
      return new Response(JSON.stringify({
        ok: true,
        userId: invited.user.id,
        email,
        tempPassword,
        mustChangePassword: true,
      }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Read-only smoke checks over the operations-upgrade schema.
    if (body.action === "verify") {
      const sql = postgres(dbUrl, { prepare: false });
      try {
        const [ref] = await sql`select public.next_customer_reference('Verification Test') as ref`;
        const [counts] = await sql`
          select
            (select count(*) from public.catalogue_items where active) as catalogue,
            (select count(*) from pg_tables where schemaname = 'public'
              and tablename in ('customer_addresses','shipment_seals','ai_usage_events','customer_reference_counters')) as new_tables,
            (select count(*) from pg_policies where tablename in ('customer_addresses','shipment_seals','driver_invoices','delivery_notes')) as policies,
            (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
              where n.nspname = 'public' and p.proname in
              ('create_customer_booking','respond_custom_quote','record_shipment_seals','driver_correct_goods_description',
               'assign_route_run','reassign_run_driver','remove_run_stop','admin_customer_records','consume_ai_quota','next_customer_reference')) as functions`;
        let cronJob = "unavailable";
        try {
          const jobs = await sql`select jobname from cron.job where jobname = 'driver-proofs-retention'`;
          cronJob = jobs.length ? "scheduled" : "missing";
        } catch { /* pg_cron not installed */ }
        const quota1 = await sql`select public.consume_ai_quota('staff-ops-verify','verify-scope',2,60,100) as r`;
        const quota2 = await sql`select public.consume_ai_quota('staff-ops-verify','verify-scope',2,60,100) as r`;
        const quota3 = await sql`select public.consume_ai_quota('staff-ops-verify','verify-scope',2,60,100) as r`;
        await sql`delete from public.ai_usage_events where scope = 'verify-scope'`;

        // Exercise the admin aggregates end-to-end by impersonating a real
        // admin (auth.uid() inside the definer functions reads the JWT claims).
        let aggregates: Record<string, unknown> = { skipped: "no admin profile found" };
        const admins = await sql`select id from public.profiles where is_admin = true limit 1`;
        if (admins.length) {
          const adminId = admins[0].id;
          await sql`select set_config('request.jwt.claim.sub', ${adminId}, false),
                           set_config('request.jwt.claims', ${JSON.stringify({ sub: adminId, role: "authenticated" })}, false)`;
          const [reports] = await sql`select public.admin_reports((current_date - 30)::date, current_date, '{}'::jsonb) as r`;
          // Wide window proves the revenue aggregation itself works even when
          // the recent range happens to contain no completed payments.
          const [wide] = await sql`select public.admin_reports((current_date - 730)::date, current_date, '{}'::jsonb) as r`;
          const [wideRaw] = await sql`
            select coalesce(sum(amount), 0)::numeric as total, count(*)::int as n
            from public.payments
            where lower(coalesce(payment_status, '')) in ('completed','paid','success','succeeded')
              and created_at::date between current_date - 730 and current_date`;
          const wideRevenue = Object.values(((wide.r as any)?.revenue?.byCurrency || {}) as Record<string, number>)
            .reduce((sum, v) => sum + Number(v), 0);
          const statusRows = await sql`
            select coalesce(payment_status, 'null') as status, count(*)::int as n,
                   coalesce(sum(amount), 0)::numeric as total
            from public.payments group by 1 order by 2 desc`;
          const [finance] = await sql`select public.admin_finance_overview() as r`;
          const [staffRows] = await sql`select jsonb_array_length(public.admin_staff_records()) as n`;
          const [zoneRows] = await sql`select jsonb_array_length(public.admin_zone_stats()) as n`;
          const [customers] = await sql`select jsonb_array_length(public.admin_customer_records()) as n`;
          const [zones] = await sql`select count(*)::int as n from public.pickup_zones`;
          // Cross-check: report revenue must agree with the raw payment rows.
          const [rawPay] = await sql`
            select count(*)::int as n,
                   count(*) filter (where shipment_id is not null)::int as linked,
                   coalesce(sum(amount), 0)::numeric as total
            from public.payments
            where lower(coalesce(payment_status, '')) in ('completed','paid','success','succeeded')
              and created_at::date between current_date - 30 and current_date`;
          const reportRevenue = Object.values(((reports.r as any)?.revenue?.byCurrency || {}) as Record<string, number>)
            .reduce((sum, v) => sum + Number(v), 0);
          aggregates = {
            rawCompletedPayments30d: Number(rawPay.n),
            rawPaymentsLinkedToShipment: Number(rawPay.linked),
            rawPaymentTotal30d: Number(rawPay.total),
            reportRevenueTotal: reportRevenue,
            revenueMatchesPayments: Math.abs(reportRevenue - Number(rawPay.total)) < 0.01,
            wide2yCompletedPayments: Number(wideRaw.n),
            wide2yRawTotal: Number(wideRaw.total),
            wide2yReportRevenue: wideRevenue,
            wide2yRevenueMatches: Math.abs(wideRevenue - Number(wideRaw.total)) < 0.01,
            wide2yShipments: (wide.r as any)?.shipments?.total ?? null,
            wide2yStatuses: Object.keys((wide.r as any)?.shipments?.byStatus || {}),
            paymentStatusBreakdown: statusRows.map((r: any) => ({ status: r.status, count: Number(r.n), total: Number(r.total) })),
            reportShipmentsTotal: (reports.r as any)?.shipments?.total ?? null,
            reportRevenueCurrencies: Object.keys((reports.r as any)?.revenue?.byCurrency || {}),
            financeRecentTx: ((finance.r as any)?.recentTransactions || []).length,
            financePendingProofs: (finance.r as any)?.pendingProofs ?? null,
            financePendingByCurrency: (finance.r as any)?.pendingByCurrency ?? null,
            financePendingCount: (finance.r as any)?.pendingPaymentCount ?? null,
            financeUnreconciled: (finance.r as any)?.unreconciledPayments ?? null,
            staffRecords: Number(staffRows.n),
            zoneStats: Number(zoneRows.n),
            pickupZones: Number(zones.n),
            customerRecords: Number(customers.n),
          };
        }
        return new Response(JSON.stringify({
          ok: true,
          sampleReference: ref.ref,
          referenceFormatValid: /^[A-Z]{3}\d{4}\d{4,}$/.test(ref.ref),
          catalogueItems: Number(counts.catalogue),
          newTables: Number(counts.new_tables),
          policies: Number(counts.policies),
          functions: Number(counts.functions),
          retentionCronJob: cronJob,
          aggregates,
          rateLimit: {
            first: quota1[0].r.allowed, second: quota2[0].r.allowed,
            thirdBlocked: quota3[0].r.allowed === false, retryAfter: quota3[0].r.retryAfterSeconds ?? null,
          },
        }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
      } finally {
        await sql.end();
      }
    }

    const sql = postgres(dbUrl, { prepare: false });
    try {
      await sql.unsafe(SETUP_SQL);
      try {
        await sql.unsafe(SETUP_SQL_V2);
      } catch (err) {
        const pos = Number((err as { position?: string })?.position || 0);
        const context = pos ? SETUP_SQL_V2.slice(Math.max(0, pos - 160), pos + 160) : "";
        throw new Error(`${(err as Error).message} @${pos}: …${context}…`);
      }
    } finally {
      await sql.end();
    }
    return new Response(JSON.stringify({ ok: true, message: "Staff ops schema is ready." }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err) {
    console.error("staff-ops error:", err);
    return new Response(JSON.stringify({ error: String((err as Error)?.message || err) }), {
      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});
